/* 构建分类页URL */
function buildCatUrl(cls, page) {
    var mainCls = getMainCat(cls);
    var mainPath = _catPaths[mainCls];
    if (cls === mainCls) {
        /* 大分类 */
        return page > 1
            ? _H + '/category/' + mainPath + '/page/' + page + '/'
            : _H + '/category/' + mainPath + '/';
    } else {
        /* 子分类 */
        var subPath = _catPaths[cls];
        return page > 1
            ? _H + '/category/' + mainPath + '/' + subPath + '/page/' + page + '/'
            : _H + '/category/' + mainPath + '/' + subPath + '/';
    }
}

/* ===== 5. 列表解析 ===== */
/* 提取列表项（标题、封面、备注、详情页链接）*/
function parseList(html) {
    var d = [];
    /* 匹配 <article class="post-item ...">...</article> */
    var re = /<article\s+class="post-item[^"]*"[^>]*>([\s\S]*?)<\/article>/g;
    var m;
    while ((m = re.exec(html)) !== null) {
        var block = m[1];

        /* 提取详情页链接和标题（优先从 media-img 的 title 属性获取） */
        var linkM = block.match(/<a[^>]*class="[^"]*media-img[^"]*"[^>]*href="([^"]*)"[^>]*title="([^"]*)"/);
        if (!linkM) {
            /* 回退：从 entry-title 中的链接获取 */
            linkM = block.match(/<h2\s+class="entry-title">\s*<a[^>]*href="([^"]*)"[^>]*title="([^"]*)"/);
        }
        if (!linkM) continue;

        var title = (linkM[2] || '').replace(/^\s+|\s+$/g, '').replace(/&amp;/g, '&');
        var url = linkM[1];

        /* 封面图：从 data-bg 属性提取 */
        var bgM = block.match(/data-bg="([^"]*)"/);
        var pic = bgM ? _full(bgM[1]) : '';

        /* 备注：浏览次数 */
        var viewsM = block.match(/class="meta-views"[^>]*><i[^>]*><\/i>(\d+)/);
        var views = viewsM ? viewsM[1] : '';

        /* 分类标签 */
        var catM = block.match(/class="entry-cat-dot"[^>]*><a[^>]*>([^<]*)<\/a>/);
        var catName = catM ? catM[1].replace(/^\s+|\s+$/g, '') : '';

        var desc = '';
        if (catName) desc += catName;
        if (views) desc += (desc ? ' · ' : '') + views + '次';

        d.push({
            title: title,
            pic_url: pic + '@Referer=' + _H + '/',
            desc: desc,
            url: _full(url) + '#immersiveTheme#',
            col_type: 'movie_3'
        });
    }
    return d;
}

/* ===== 6. 首页板块解析 ===== */
/* 将首页分割成多个板块 */
function parseSections(html) {
    var allSections = [];

    /* --- 板块1: home-cms-post 精选影视 --- */
    var cmsMatch = html.match(/id="ri_home_cmspost_widget-\d+"[\s\S]*?(?=<div id="ri_home_)/);
    if (cmsMatch) {
        var items = parseList(cmsMatch[0]);
        if (items.length) {
            allSections.push({ title: '最新影视', items: items, cls: 'kb' });
        }
    }

    /* --- 板块2: home-last-post 最新推荐 --- */
    var lastMatch = html.match(/id="ri_home_lastpost_widget-\d+"[\s\S]*?(?=<div id="ri_home_)/);
    if (lastMatch) {
        var lastItems = parseList(lastMatch[0]);
        if (lastItems.length) {
            allSections.push({ title: '最新推荐', items: lastItems, cls: 'kb' });
        }
    }

    /* --- 板块3+: home-title-post 各分类排行榜 --- */
    var titleMatch = html.match(/id="ri_home_titlepost_widget-\d+"[\s\S]*?<\/main>/);
    if (titleMatch) {
        var titleHtml = titleMatch[0];
        /* 每个分类排行榜在 <div class="list-posts"> 中 */
        var rankAltRe = /<div class="list-posts">([\s\S]*?)<\/ul>\s*<\/div>/g;
        var rankM;
        while ((rankM = rankAltRe.exec(titleHtml)) !== null) {
            var rankBlock = rankM[1];

            /* 提取板块标题和分类链接 */
            var titleLinkM = rankBlock.match(/<h3 class="category-title">[\s\S]*?<a[^>]*href="([^"]*)"[^>]*>([^<]*)<\/a>/);
            if (!titleLinkM) continue;
            var secTitle = titleLinkM[2].replace(/&gt;/g, '>').replace(/^\s+|\s+$/g, '').replace(/\s*>\s*$/, '');
            var secLink = titleLinkM[1];

            /* 从链接中提取分类代码 */
            var secCls = '';
            for (var k in _catPaths) {
                if (secLink.indexOf(_catPaths[k]) >= 0 && k !== 'kb') {
                    secCls = k;
                    break;
                }
            }

            /* 解析排行榜列表项 */
            var rankItems = [];
            var liRe = /<li>\s*<div class="title">\s*<span class="post-num[^"]*">(\d+)<\/span>\s*<a[^>]*href="([^"]*)"[^>]*title="([^"]*)"/g;
            var liM;
            while ((liM = liRe.exec(rankBlock)) !== null) {
                var rankTitle = liM[3].replace(/^\s+|\s+$/g, '').replace(/&amp;/g, '&');
                var rankUrl = liM[2];

                /* 提取浏览次数 */
                var afterText = rankBlock.substring(liM.index, liM.index + 500);
                var rankViewsM = afterText.match(/class="post-views">(\d+)/);
                var rankViews = rankViewsM ? rankViewsM[1] : '';

                rankItems.push({
                    title: rankTitle,
                    desc: rankViews ? '热度 ' + rankViews : '',
                    url: _full(rankUrl) + '#immersiveTheme#',
                    col_type: 'text_1'
                });
            }

            if (rankItems.length) {
                allSections.push({ title: secTitle, items: rankItems, cls: secCls });
            }
        }
    }

    return allSections;
}

/* ===== 7. 首页 / 分类 ===== */
function home() {
    var d = [];
    var cls = getMyVar(_cfg.prefix + '_cls', '');
    var page = parseInt(MY_PAGE || '1', 10);

    if (!cls) {
        /* 首页模式 */
        if (page > 1) { setResult([]); return; }
        var html = _fetch(_H + '/');
        if (!html) { setResult(d); return; }

        var allSections = parseSections(html);

        if (allSections.length > 0 && allSections[0].items.length > 0) {
            renderBanner(d, buildBannerData(allSections[0].items), MY_RULE.title);
        }

        renderSearchBox(d);
        renderCatButtons(d, _homeCats);

        for (var si = 0; si < allSections.length; si++) {
            var section = allSections[si];
            var iconUrl = _secIcons[section.title] || 'https://lanmeio.com/tubiao/movie/13.svg';
            var secC = _secClsMap[section.title] || section.cls || '';
            renderSectionTitle(d, section.title, iconUrl, secC);

            /* 排行榜板块用 text_1，其他用 movie_3 */
            var isRank = section.items.length > 0 && section.items[0].col_type === 'text_1';
            if (isRank) {
                renderSectionItems(d, section.items, 10, 'text_1');
            } else {
                renderSectionItems(d, section.items, si === 0 ? 6 : 9, si === 0 ? 'movie_2' : 'movie_3');
            }
        }

        setResult(d);

    } else {
        /* 分类模式 */
        addCloseListener();
        renderNavBar(d, _navCats, cls, getMainCat);

        var mainCls = getMainCat(cls);
        var subCats = _subCats[mainCls] || [{ t: '全部', s: mainCls }];
        renderSubCats(d, subCats, cls);

        /* 分类页 URL（WordPress 格式）*/
        var url = buildCatUrl(cls, page);

        var html = _fetch(url);
        if (!html) { setResult(d); return; }

        var items = parseList(html);
        if (!items.length) { renderEmpty(d, page); return; }

        for (var i = 0; i < items.length; i++) d.push(items[i]);
        setResult(d);
    }
}

/* ===== 8. 搜索 ===== */
function search() {
    var kw = MY_KEYWORD || '';
    if (!kw) { setResult([]); return; }
    var page = parseInt(MY_PAGE || '1', 10);

    /* WordPress 搜索 URL 格式 */
    var searchUrl = page > 1
        ? _H + '/page/' + page + '/?s=' + encodeURIComponent(kw)
        : _H + '/?s=' + encodeURIComponent(kw);

    var html = _fetch(searchUrl);
    var d = [];

    if (html) {
        var items = parseList(html);
        for (var i = 0; i < items.length; i++) d.push(items[i]);
    }

    setResult(d);
}

/* ===== 9. 网盘 URL 解析 ===== */
/* 将 goto?down= 跳转链接或直接网盘链接转换为海阔网盘规则页面 URL */
/* 参照用户的 lazy 规则中的 getNetdiskRuleUrl + x5rule 逻辑 */
function makeNetdiskUrl(url) {
    if (!url) return url;

    /* 网盘规则 URL 转换函数（与 lazy 规则一致）*/
    function getNetdiskRuleUrl(input) {
        if (!input) return '';
        if (/alipan/.test(input)) {
            return 'hiker://page/aliyun?rule=云盘君.简&page=fypage&realurl=' + encodeURIComponent(input);
        }
        if (/quark|uc/.test(input)) {
            return 'hiker://page/quarkList?rule=Quark.简&realurl=' + input;
        }
        if (/baidu/.test(input)) {
            return 'hiker://page/fxlj?rule=百度云盘&page=fypage&realurl=' + input;
        }
        if (/xunlei/.test(input)) {
            return 'hiker://page/diaoyong?rule=迅雷&realurl=' + encodeURIComponent(input);
        }
        if (/guangyapan/.test(input)) {
            /* 光鸭云盘：无海阔规则，直接浏览器打开 */
            return input;
        }
        return '';
    }

    /* 1. 如果已经是直接网盘链接，直接转换 */
    var direct = getNetdiskRuleUrl(url);
    if (direct) return direct;

    /* 2. 如果是 goto?down= 跳转链接，用 webRule 让浏览器自动跟随重定向，
          检测最终 URL 并转换为网盘规则 URL */
    if (url.indexOf('goto') >= 0 && url.indexOf('down') >= 0) {
        var js = $.toString(() => {
            /* 网盘规则 URL 转换（内联，webRule 环境无法访问外部函数）*/
            function getNetdiskRuleUrl(input) {
                if (!input) return '';
                if (/alipan/.test(input)) {
                    return 'hiker://page/aliyun?rule=云盘君.简&page=fypage&realurl=' + encodeURIComponent(input);
                }
                if (/quark|uc/.test(input)) {
                    return 'hiker://page/quarkList?rule=Quark.简&realurl=' + input;
                }
                if (/baidu/.test(input)) {
                    return 'hiker://page/fxlj?rule=百度云盘&page=fypage&realurl=' + input;
                }
                if (/xunlei/.test(input)) {
                    return 'hiker://page/diaoyong?rule=迅雷&realurl=' + encodeURIComponent(input);
                }
                if (/guangyapan/.test(input)) {
                    return input;
                }
                return '';
            }

            /* 循环计数器，防止无限等待 */
            if (window.count == null || window.count == undefined) {
                window.count = 0;
            }
            if (window.count >= 30) {
                return 'toast://网盘跳转超时，请稍后重试';
            }
            window.count = window.count + 1;

            /* 检测当前页面 URL 是否已跳转到网盘 */
            var currentUrl = location.href;
            var netdiskUrl = getNetdiskRuleUrl(currentUrl);
            if (netdiskUrl) {
                return netdiskUrl;
            }
            /* 未检测到网盘 URL，不返回值，海阔继续等待页面跳转 */
        });
        return 'webRule://' + url + '@' + js;
    }

    /* 3. 非网盘链接，原样返回 */
    return url;
}

/* ===== 10. 详情页 ===== */
function detail() {
    var res = _fetch(MY_URL);
    var d = [];

    /* --- 标题 --- */
    var tTitle = (res.match(/<h1\s+class="post-title[^"]*">([\s\S]*?)<\/h1>/) || [])[1] || '-';
    tTitle = tTitle.replace(/<[^>]*>/g, '').replace(/^\s+|\s+$/g, '') || '-';

    /* --- 封面：post-content 中第一张图的 data-src --- */
    var contentMatch = res.match(/<article\s+class="post-content[^"]*"[^>]*>([\s\S]*?)<\/article>/);
    var contentHtml = contentMatch ? contentMatch[1] : res;
    var cover = (contentHtml.match(/data-src="([^"]*)"/) || [])[1] || '';
    cover = _full(cover);

    /* --- 元信息提取 --- */
    /* 电影信息块在 <h1>标题<span class="year">(年份)</span></h1> 之后的 <p> 中 */
    var yearInfo = '', typeInfo = '', actorInfo = '', dirInfo = '';
    var regionInfo = '', langInfo = '', dateInfo = '', durInfo = '';
    var imdbInfo = '', akaInfo = '';

    var infoM = contentHtml.match(/<h1>[^<]*<span class="year">\((\d{4})\)<\/span><\/h1>\s*<p>([\s\S]*?)<\/p>/);
    if (infoM) {
        yearInfo = infoM[1];
        var infoText = infoM[2].replace(/<br\s*\/?>/g, '\n').replace(/<[^>]*>/g, '').replace(/&nbsp;/g, ' ').replace(/&#8230;/g, '...');

        var pickInfo = function(label) {
            var rm = infoText.match(new RegExp(label + '[：:]\\s*([^\\n]+)'));
            return rm ? rm[1].replace(/^\s+|\s+$/g, '') : '';
        };

        dirInfo = pickInfo('导演');
        actorInfo = pickInfo('主演');
        typeInfo = pickInfo('类型');
        regionInfo = pickInfo('制片国家') || pickInfo('制片国家/地区');
        langInfo = pickInfo('语言');
        dateInfo = pickInfo('上映日期');
        durInfo = pickInfo('片长');
        akaInfo = pickInfo('又名');
        imdbInfo = pickInfo('IMDb');
    }

    /* --- 简介 --- */
    var intro = '';
    /* 简介在信息块之后的 <p> 中（跳过空段落） */
    var afterInfo = contentHtml.split(/<\/p>/);
    var foundInfoBlock = false;
    for (var pi = 0; pi < afterInfo.length; pi++) {
        if (afterInfo[pi].indexOf('IMDb:') >= 0 || afterInfo[pi].indexOf('片长') >= 0 || afterInfo[pi].indexOf('又名') >= 0) {
            foundInfoBlock = true;
            continue;
        }
        if (foundInfoBlock) {
            var paraText = afterInfo[pi].replace(/<[^>]*>/g, '').replace(/&nbsp;/g, ' ').replace(/^\s+|\s+$/g, '');
            if (paraText && paraText.length > 5) {
                intro = paraText;
                break;
            }
        }
    }

    /* 组装信息卡片 */
    var chip = '';
    if (yearInfo) chip += yearInfo + ' ';
    if (typeInfo) chip += typeInfo + ' ';
    if (regionInfo) chip += regionInfo;
    var info = chip.trim();
    if (durInfo) info += '  ·  ' + durInfo;
    if (langInfo) info += '  ·  ' + langInfo;
    if (actorInfo) info += '\n主演：' + actorInfo;
    if (dirInfo) info += '\n导演：' + dirInfo;
    if (imdbInfo) info += '\nIMDb：' + imdbInfo;

    /* --- 详情头部卡片 --- */
    d.push({
        title: tTitle,
        desc: info,
        pic_url: cover ? cover + '@Referer=' + _H + '/' : '',
        url: cover ? cover + '#.jpg#' : 'hiker://empty',
        col_type: 'movie_1_vertical_pic_blur',
        extra: { gradient: true }
    });

    /* --- 共享模块 --- */
    setDesc(d, intro, 60);
    renderQuickSearch(d);

    /* --- 下载链接提取（网盘）--- */
    var lineNames = [];
    var allLinesEp = [];
    var dlLinks = [];

    /* === 优先：新结构 one23-dl-list（直连网盘链接）=== */
    /* 页面有两个 one23-dl-list（桌面端/移动端），只取第一个避免重复 */
    var newListMatch = res.match(/<div class="one23-dl-list">([\s\S]*?)(?=<div class="one23-dl-list">|<\/main>|<footer|<div class="entry-copyright)/);
    if (newListMatch) {
        var newListHtml = newListMatch[1];
        /* 每个 item-row: <span class="one23-dl-label">网盘名</span> + <button data-url="直链"> */
        var newRowRe = /<div class="one23-dl-item-row">[\s\S]*?<span class="one23-dl-label">([^<]*)<\/span>[\s\S]*?<button[^>]*data-url="([^"]+)"/g;
        var newRowM;
        while ((newRowM = newRowRe.exec(newListHtml)) !== null) {
            dlLinks.push({
                name: newRowM[1].replace(/^\s+|\s+$/g, ''),
                url: newRowM[2]
            });
        }
    }

    /* === 回退：旧结构 goto?down= 跳转链接 === */
    if (dlLinks.length === 0) {
        var dlRe = /<a\s[^>]*href="([^"]*goto[^"]*down[^"]*)"[^>]*>([\s\S]*?)<\/a>/g;
        var dlM;
        while ((dlM = dlRe.exec(res)) !== null) {
            var dlUrl = _full(dlM[1]);
            var dlName = dlM[2].replace(/<[^>]*>/g, '').replace(/^\s+|\s+$/g, '') || '下载';
            dlLinks.push({ name: dlName, url: dlUrl });
        }
    }

    /* 提取资源文件信息（文件名和大小）*/
    var fileInfos = [];
    var fileRe = /<li[^>]*class="[^"]*list-group-item[^"]*"[^>]*><span>([^:]*):\s*<\/span>\s*<span>([^<]*)<\/span>/g;
    var fileM;
    while ((fileM = fileRe.exec(res)) !== null) {
        var fName = fileM[1].replace(/^\s+|\s+$/g, '');
        var fSize = fileM[2].replace(/^\s+|\s+$/g, '');
        /* 过滤掉非文件信息的条目（只保留看起来像文件名的条目）*/
        var isFile = fName.indexOf('包含资源') < 0
            && fName.indexOf('最近更新') < 0
            && fName.indexOf('下载') < 0
            && fName.indexOf('累计销量') < 0
            && /\d+\s*(GB|MB|KB|TB|gb|mb|kb|tb)/.test(fSize);
        if (isFile) {
            fileInfos.push({ name: fName, size: fSize });
        }
    }

    /* 构建选集：每个下载链接作为一个选集 */
    if (dlLinks.length > 0) {
        lineNames.push('网盘下载');
        var eps = [];
        for (var di = 0; di < dlLinks.length; di++) {
            var epName = dlLinks[di].name;
            /* 如果有对应的文件信息，附加到选集名 */
            if (fileInfos[di]) {
                epName += ' (' + fileInfos[di].size + ')';
            }
            eps.push({
                name: epName,
                url: dlLinks[di].url
            });
        }
        allLinesEp.push(eps);
    } else if (fileInfos.length > 0) {
        /* 没有直接下载链接但有文件信息（可能需要登录/VIP）*/
        lineNames.push('资源信息');
        var infoEps = [];
        for (var fi = 0; fi < fileInfos.length; fi++) {
            infoEps.push({
                name: fileInfos[fi].name + ' (' + fileInfos[fi].size + ')',
                url: MY_URL
            });
        }
        allLinesEp.push(infoEps);
    }

    /* --- 共享模块 --- */
    renderPushModule(d, tTitle, cover, intro, lineNames, allLinesEp);
    renderEpisodes(d, allLinesEp, lineNames, function (epItem) {
        return makeNetdiskUrl(epItem.url);
    });

    setResult(d);
}

