/* ===== 13. 通用播放解析器 ===== */
function makePlayUrl(epUrl) {
    var host = _cfg.host;
    var ua = _cfg.ua;
    var parseTpl = _cfg.parseUrl || '';
    return $().lazyRule(function (pu, host, ua, parseTpl) {
        var ph = fetch(pu, { headers: { "User-Agent": ua, "Referer": host + "/" } });

        var playerUrl = (ph.match(/player_aaaa\s*=\s*\{[\s\S]*?"url"\s*:\s*"([^"]+)"/) || [])[1] || '';
        var playerEnc = (ph.match(/player_aaaa\s*=\s*\{[\s\S]*?"encrypt"\s*:\s*(\d+)/) || [])[1] || '0';

        if (playerEnc === '1' && playerUrl) {
            try { playerUrl = decodeURIComponent(playerUrl); } catch (e) {
                try { playerUrl = unescape(playerUrl); } catch (e2) {}
            }
        }
        playerUrl = playerUrl.replace(/\\\//g, '/').replace(/\\u002f/g, '/');

        /* 直链 */
        if (playerUrl && /\.m3u8|\.mp4/i.test(playerUrl)) {
            return playerUrl + '#isVideo=true#';
        }

        /* 视频站解析 */
        if (parseTpl) {
            var videoSites = ['v.qq.com', 'iqiyi.com', 'youku.com', 'mgtv.com', 'bilibili.com', 'le.com', 'sohu.com', 'pptv.com'];
            var isVideoSite = false;
            for (var vs = 0; vs < videoSites.length; vs++) {
                if (playerUrl.indexOf(videoSites[vs]) >= 0) { isVideoSite = true; break; }
            }
            if (isVideoSite && playerUrl.indexOf('http') === 0) {
                var parseUrl = parseTpl.replace('{url}', encodeURIComponent(playerUrl));
                return 'video://' + parseUrl;
            }
        }

        /* 二次解析 */
        var vurl = '';
        if (playerUrl.indexOf('http') === 0) {
            var ph2 = fetch(playerUrl, { headers: { "User-Agent": ua, "Referer": host + "/" } });
            var m2 = ph2.match(/https?:\/\/[^'"\s,]+\.m3u8/i);
            if (!m2) m2 = ph2.match(/https?:\/\/[^'"\s,]+\.mp4/i);
            if (m2) {
                vurl = m2[0];
            } else {
                var relM = ph2.match(/(?:const|var)\s+url\s*=\s*"([^"]+\.m3u8[^"]*)"/i);
                if (!relM) relM = ph2.match(/(?:const|var)\s+url\s*=\s*"([^"]+\.mp4[^"]*)"/i);
                if (relM) {
                    var relUrl = relM[1].replace(/\\\//g, '/');
                    if (relUrl.indexOf('http') === 0) {
                        vurl = relUrl;
                    } else {
                        var domainM = playerUrl.match(/^(https?:\/\/[^\/]+)/);
                        if (domainM) vurl = domainM[1] + relUrl;
                    }
                }
                if (!vurl) {
                    var jsonM = ph2.match(/"url"\s*:\s*"([^"]+\.m3u8[^"]*)"/i);
                    if (!jsonM) jsonM = ph2.match(/"url"\s*:\s*"([^"]+\.mp4[^"]*)"/i);
                    if (jsonM) {
                        var jUrl = jsonM[1].replace(/\\\//g, '/');
                        if (jUrl.indexOf('http') === 0) {
                            vurl = jUrl;
                        } else {
                            var dM2 = playerUrl.match(/^(https?:\/\/[^\/]+)/);
                            if (dM2) vurl = dM2[1] + jUrl;
                        }
                    }
                }
            }
        }

        if (!vurl) {
