function buildCatUrl(cls, filterState, page) {
    var fArea = filterState.area || '';
    var fSort = filterState.sort || '';
    var fYear = filterState.year || '';

    /* 有筛选条件时用 search.html，无筛选时用 vodtype 分页 */
