/* ===== 7. 首页板块解析 ===== */
/* 首页使用 tab 布局: #home1(电影) #home2(电视剧) #home3(动漫) #home4(综艺)
   每个 tab 内是一个 <ul class="...-vodlist"> 列表 */
function parseSections(html) {
    var allSections = [];

    /* 用 tab id 分割: #home1, #home2, #home3, #home4 */
    var tabNames = ['home1', 'home2', 'home3', 'home4'];
    var tabTitles = ['电影', '电视剧', '动漫', '综艺'];

    for (var ti = 0; ti < tabNames.length; ti++) {
        var tabId = tabNames[ti];
        var idx = html.indexOf('id="' + tabId + '"');
        if (idx < 0) continue;

        /* 取该 tab 到下一个 tab 之间的内容 */
        var nextIdx = html.length;
        if (ti < tabNames.length - 1) {
            nextIdx = html.indexOf('id="' + tabNames[ti + 1] + '"');
            if (nextIdx < 0) nextIdx = html.length;
        }

        var part = html.substring(idx, nextIdx);
        var secItems = parseList(part);
        if (secItems.length) {
            allSections.push({
                title: tabTitles[ti],
                items: secItems,
                cls: _secClsMap[tabTitles[ti]] || ''
            });
        }
    }

    /* 如果 tab 解析失败，回退到通用方式：按 vodlist 分割 */
    if (!allSections.length) {
        var parts = html.split(/<ul[^>]*class="[^"]*vodlist[^"]*"/);
        var fallbackTitles = ['电影', '电视剧', '动漫', '综艺'];
        for (var fi = 1; fi < parts.length && fi <= 4; fi++) {
            var secItems2 = parseList(parts[fi]);
            if (secItems2.length) {
                allSections.push({
                    title: fallbackTitles[fi - 1] || ('板块' + fi),
                    items: secItems2,
                    cls: ''
                });
            }
        }
    }

    return allSections;
}

