            var playerUrl = (ph.match(/player_aaaa\s*=\s*\{[\s\S]*?"url"\s*:\s*"([^"]+)"/) || [])[1] || '';
            var playerEnc = (ph.match(/player_aaaa\s*=\s*\{[\s\S]*?"encrypt"\s*:\s*(\d+)/) || [])[1] || '0';

            if (playerEnc === '1' && playerUrl) {
                try { playerUrl = decodeURIComponent(playerUrl); } catch (e) {
                    try { playerUrl = unescape(playerUrl); } catch (e2) {}
                }
            }
            playerUrl = playerUrl.replace(/\\\//g, '/').replace(/\\u002f/g, '/');

            if (playerUrl && /\.m3u8|\.mp4/i.test(playerUrl)) {
                if (getItem('webpush', '0') == '1') {
                    var tvip1 = getItem('hikertvboxset', 'http://' + getIP() + ':9978');
                    return tvip1 + '/action?key=push&url=' + encodeURIComponent(playerUrl);
                }
                return playerUrl + '#isVideo=true#';
            }

            /* 3. 视频站链接嗅探 */
            if (playerUrl && playerUrl.indexOf('http') === 0) {
                var videoSites = ['v.qq.com', 'iqiyi.com', 'youku.com', 'mgtv.com', 'bilibili.com', 'le.com', 'sohu.com', 'pptv.com'];
                var isVideoSite = false;
                for (var vs = 0; vs < videoSites.length; vs++) {
