                    }
                    return 'video://' + playerUrl;
                }
            }

            /* 4. 二次解析: 从 iframe src 中提取 m3u8 */
            var iframeM = ph.match(/src="[^"]*mui-player\.php\?[^"]*(https?:\/\/[^,]+\.m3u8[^,]*)/i);
