/* ===== 9. 动态筛选（折叠/展开 + 多维度筛选）===== */
/* 参照 qhdaohang 的动态筛选系统：
   - 折叠状态(fold=0)：只显示第一个维度（子分类）
   - 展开状态(fold=1)：显示全部维度（子分类/地区/年份/排序），小字显示
   - 使用 setPreResult 置顶显示
   opts = {
     cls:     当前分类ID,
     page:    当前页码（仅第1页渲染筛选UI）,
     filterDims: [
       { label:'类型', key:'sub',  isSub:true,  options:[{name,value}] },
       { label:'地区', key:'area', isSub:false, options:[{name,value}] },
       { label:'年份', key:'year', isSub:false, options:[{name,value}] },
       { label:'排序', key:'sort', isSub:false, options:[{name,value}] }
     ]
   }
*/
function renderDynamicFilter(opts) {
    if (opts.page !== 1) return;

    var s = [];
    var fold = getVar(MY_RULE.group, "0");
    var fk = _filterKey();
    var vk = _cfg.prefix + '_cls';
    var filterState = JSON.parse(getVar(fk, JSON.stringify({ area: '', sort: '', year: '' })));

    /* 折叠/展开按钮 */
    s.push({
        title: fold === '1' ? '\u2018\u2018\u2019\u2019' + '\u27a5'.fontcolor("#9370db") : '\u2018\u2018\u2019\u2019' + '\u27a6'.fontcolor("#ffbf00"),
        url: $('#noLoading#').lazyRule(function (fold) {
            putVar(MY_RULE.group, fold === '1' ? '0' : '1');
            refreshPage(false);
            return "hiker://empty";
        }, fold),
        col_type: 'scroll_button'
    });

    /* 遍历筛选维度 */
    for (var fi = 0; fi < opts.filterDims.length; fi++) {
        var dim = opts.filterDims[fi];
        if (fold !== '1' && fi > 0) break;  /* 折叠时只显示第一个维度 */

        for (var oi = 0; oi < dim.options.length; oi++) {
            var opt = dim.options[oi];
            var isActive;

            if (dim.isSub) {
                isActive = (opts.cls === opt.value);
            } else {
                isActive = (filterState[dim.key] === opt.value);
            }

            var displayTitle = opt.name;

            if (fold === '1' && fi > 0) {
                /* 展开模式 + 非首维：小字 */
                displayTitle = '\u2018\u2018\u2019\u2019' + opt.name.small();
                if (isActive) displayTitle = '\u2018\u2018\u2019\u2019<b>' + opt.name.fontcolor("#ffffff").small() + '</b>';
            } else {
                /* 折叠模式 或 首维：正常字 */
                if (isActive) displayTitle = '\u2018\u2018\u2019\u2019' + opt.name.fontcolor("#ffffff").bold();
            }

            if (dim.isSub) {
                /* 子分类：切换 cls，清除筛选状态 */
                s.push({
                    title: displayTitle,
                    url: $('#noLoading##noRecordHistory#').lazyRule(function (subVal, key, fk) {
                        putMyVar(key, subVal);
                        clearVar(fk);
                        refreshPage(true);
                        return 'hiker://empty';
                    }, opt.value, vk, fk),
                    col_type: 'scroll_button',
                    extra: { backgroundColor: isActive ? getRangeColors() : '' }
                });
            } else {
                /* 普通筛选：修改 filterState */
                s.push({
                    title: displayTitle,
                    url: $('#noLoading#').lazyRule(function (params) {
                        var state = JSON.parse(getVar(params.fk, '{}'));
                        state[params.key] = params.value;
                        putVar(params.fk, JSON.stringify(state));
                        refreshPage(true);
                        return "hiker://empty";
                    }, { fk: fk, key: dim.key, value: opt.value }),
                    col_type: 'scroll_button',
                    extra: { backgroundColor: isActive ? getRangeColors() : '' }
                });
            }
        }
        s.push({ col_type: "blank_block" });
    }

    setPreResult(s);
}

