}

/* ===== 1. 工具函数 ===== */

function _full(u) {
    if (!u) return '';
    if (u.indexOf('http') === 0) return u;
    if (u.indexOf('//') === 0) return 'https:' + u;
    u = u.replace(/^\.?\//, '');
    return _cfg.host + '/' + u;
}

function _hdr() {
    return { headers: { "User-Agent": _cfg.ua, "Referer": _cfg.host + "/" } };
}

function _fetch(url) {
    try {
        return fetch(url + '#autoCache#', _hdr());
    } catch (e) {
        return "";
