"},{"col_type":"movie_3","name":"2列表解析 + 首页 + 搜索  ","path":"push2","rule":"/* ================================================================
 * 模板模块 2/4 · 列表解析 + 首页 + 搜索  (tpl_2_list.js)
 *
 * 【对应页面】 网站首页 / 分类列表页 / 搜索结果页
 * 【站点】     毒舌影视 (m.xnhrsb.com)
 * 【结构】     结构D — ul/li + h3.dytit + data-original + qb
 * ================================================================ */


/* ===== 1. 列表解析（结构D：毒舌影视 dsshiyi 模板）===== */
function parseList(html) {
    var d = [];

    // 按 h3.dytit 定位每个视频项（列表项的唯一标识）
    var h3Re = /<h3\s+class="dytit"[^>]*>([\s\S]*?)<\/h3>/g;
    var h3M;
    while ((h3M = h3Re.exec(html)) !== null) {
        var h3Inner = h3M[1];

        // 从 h3 内的 <a> 提取详情页链接和标题
        var aM = h3Inner.match(/<a[^>]*href="([^"]+)"[^>]*>([\s\S]*?)<\/a>/);
        if (!aM) continue;
        var detailHref = aM[1];
        var title = aM[2].replace(/<[^>]+>/g, '').replace(/^\s+|\s+$/g, '');
        if (!title) continue;

        // 往回找 1200 字符（li 范围），提取封面和备注
        var beforeStart = Math.max(0, h3M.index - 1200);
        var before = html.substring(beforeStart, h3M.index);

        // 封面：取最后一个 data-original（离 h3 最近的那张图）
        var pic = '';
        var diRe = /data-original="([^"]+)"/g;
        var diM, lastPic = '';
        while ((diM = diRe.exec(before)) !== null) {
            lastPic = diM[1];
        }
        if (lastPic) pic = _full(lastPic);

        // 备注：<span class="qb">更新至14集</span>
        var desc = '';
        var qbRe = /<span[^>]*class="[^"]*qb[^"]*"[^>]*>([^<]*)<\/span>/g;
        var qbM, lastQb = '';
        while ((qbM = qbRe.exec(before)) !== null) {
            lastQb = qbM[1];
        }
        if (lastQb) desc = lastQb.replace(/^\s+|\s+$/g, '');

        // 可选：附加主演信息到 desc
        // var actorM = html.substring(h3M.index, h3M.index + 200).match(/<p\s+class="inzhuy">\s*主演：([^<]*)<\/p>/);
        // if (actorM && actorM[1]) desc = (desc ? desc + ' | ' : '') + '主演：' + actorM[1].replace(/^\s+|\s+$/g,'').substring(0, 30);

        d.push({
            title: title,
            pic_url: pic + '@Referer=' + _H + '/',
            desc: desc,
            url: _full(detailHref) + '#immersiveTheme#',
            col_type: 'movie_3'
        });
    }
    return d;
}


/* ===== 2. 首页板块数据 ===== */

/* 方式B（推荐）：直接请求各分类页获取板块数据 */
function parseSections(html) {
    var allSections = [];

    // 定义要展示的板块（顺序 = 首页从上到下）
    var sections = [
        { title: '电影',   cls: '1', count: 9 },
        { title: '电视剧', cls: '2', count: 9 },
        { title: '综艺',   cls: '3', count: 9 },
        { title: '动漫',   cls: '4', count: 9 },
        { title: '短剧',   cls: '5', count: 9 }
    ];

    for (var i = 0; i < sections.length; i++) {
        var sec = sections[i];
        // 毒舌影视分类页：/dsshiyitp/{id}.html（简单分类，无筛选）
        var catHtml = _fetch(_H + '/dsshiyitp/' + sec.cls + '.html');
        if (!catHtml) continue;
        var items = parseList(catHtml);
        if (items.length > sec.count) items = items.slice(0, sec.count);
        if (items.length) {
            allSections.push({ title: sec.title, items: items, cls: sec.cls });
        }
    }
    return allSections;
}


/* ===== 3. 搜索 ===== */
function search() {
    var kw = MY_KEYWORD || '';
    if (!kw) { setResult([]); return; }

    // 毒舌影视搜索URL：/dsshiyisc/-------------.html?wd=关键词
    var searchUrl = _H + '/dsshiyisc/-------------.html?wd=' + encodeURIComponent(kw);

    var html = _fetch(searchUrl);
    var d = [];

    if (html) {
        var items = parseList(html);
        for (var i = 0; i < items.length; i++) d.push(items[i]);
    }

    setResult(d);
}
"},{"col_type":"movie_3","name":"3 详情页信息 + 选集提取","path":"push3","rule":"/* ================================================================
 * 模板模块 3/4 · 详情页信息 + 选集提取  (tpl_3_detail.js)
 * 站点：毒舌影视 m.xnhrsb.com  (dsshiyi 模板)
 * 依赖：hiker_lib.js / tpl_1_config.js 之后加载
 * ================================================================ */

/* ===== 1. 详情页信息提取 ===== */
function extractDetailInfo(res) {
    // 1.1 标题：优先 h1，兜底 dy_tit_big
    var tTitle = (res.match(/<h1[^>]*>([^<]+)<\/h1>/) || [])[1] || '';
    if (!tTitle) {
        tTitle = (res.match(/<h3 class="dy_tit_big[^"]*"[^>]*>([^<]+)</) || [])[1] || '';
    }
    tTitle = tTitle.replace(/^\s+|\s+$/g, '') || '-';

    // 1.2 封面：dyimg 内的 img src（不是 data-original）
    var cover = (res.match(/class="dyimg[^"]*"[\s\S]*?<img[^>]*src="([^"]+)"/) || [])[1] || '';
    if (!cover) cover = (res.match(/<img[^>]+class="[^"]*dyimg[^"]*"[^>]*src="([^"]+)"/) || [])[1] || '';
    cover = _full(cover);

    // 1.3 元信息：ul.moviedteail_list > li
    var dirInfo = '', actorInfo = '', typeInfo = '', areaInfo = '', yearInfo = '', updateInfo = '', langInfo = '';

    var liRe = /<li>([\s\S]*?)<\/li>/g;
    var lim;
    while ((lim = liRe.exec(res)) !== null) {
        var liHtml = lim[1];
        // 取 li 文本（去标签），保留 a 文本
        var liText = liHtml.replace(/<a[^>]*>([^<]*)<\/a>/g, '$1')
                           .replace(/<[^>]+>/g, '')
                           .replace(/&nbsp;/g, ' ')
                           .replace(/\s+/g, ' ')
                           .trim();
        // 标签识别（冒号/：前是字段名）
        var kv = liText.match(/^([^:：]+)[:：]\s*(.*)$/);
        if (!kv) continue;
        var label = kv[1].replace(/^\s+|\s+$/g, '');
        var val = kv[2].replace(/^\s+|\s+$/g, '');
        if (label.indexOf('类型') >= 0) typeInfo = val;
        else if (label.indexOf('地区') >= 0) areaInfo = val;
        else if (label.indexOf('年份') >= 0) yearInfo = val;
        else if (label.indexOf('导演') >= 0) dirInfo = val;
        else if (label.indexOf('主演') >= 0) actorInfo = val;
        else if (label.indexOf('语言') >= 0) langInfo = val;
        else if (label.indexOf('更新') >= 0) updateInfo = val;
    }
    // 年份兜底：dy_tit_big 里的 <span>2026</span>
    if (!yearInfo) {
        yearInfo = (res.match(/dy_tit_big[^>]*>[\s\S]*?<span>(\d{4})<\/span>/) || [])[1] || '';
    }
    // 类型兜底：从类型搜索链接里抠
    if (!typeInfo) {
        typeInfo = (res.match(/\/dsshiyisc\/----([^"]+?)\.html[^>]*>([^<]+)<\/a>/) || [])[2] || '';
    }

    // 1.4 简介：yp_context
    var intro = (res.match(/class="yp_context"[^>]*>([\s\S]*?)<\/div>/) || [])[1] || '';
    intro = intro.replace(/&nbsp;/g, ' ')
                .replace(/<[^>]+>/g, '')
                .replace(/\s+/g, ' ')
                .trim();

    return {
        tTitle: tTitle,
        cover: cover,
        typeInfo: typeInfo,
        yearInfo: yearInfo,
        actorInfo: actorInfo,
        dirInfo: dirInfo,
        updateInfo: updateInfo,
        areaInfo: areaInfo,
        langInfo: langInfo,
        intro: intro
    };
}


/* ===== 2. 选集提取 ===== */
function extractEpisodes(res) {
    var lineNames = [];
    var allLinesEp = [];

    // 当前视频ID（详情页 URL 形如 /dsshiyidt/269037.html）
    var curVid = (MY_URL || '').match(/\/dsshiyidt\/(\d+)\.html/);
    curVid = curVid ? curVid[1] : '';

    // 按 mi_paly_box 切块，每块是一条线路
    var boxParts = res.split(/<div class="mi_paly_box">/);
    for (var i = 1; i < boxParts.length; i++) {
        var box = boxParts[i];
        // 线路名：ypxingq_t 里取 秒播 / 光速 / 极速 / 索尼
        var lineName = (box.match(/class="ypxingq_t"[^>]*>\s*([^<-]+?)\s*-?\s*<span>/) || [])[1] || '';
        lineName = lineName.replace(/^\s+|\s+$/g, '') || ('线路' + i);

        // 只取 paly_list_btn 块
        var btnBlock = (box.match(/class="paly_list_btn"[^>]*>([\s\S]*?)<\/div>/) || [])[1] || '';

        var eps = [];
        var aRe = /<a class="play_movie" href="([^"]+)"[^>]*>([^<]+)<\/a>/g;
        var am;
        while ((am = aRe.exec(btnBlock)) !== null) {
            var href = am[1];
            var name = am[2].replace(/^\s+|\s+$/g, '');
            // 过滤 APP 秒播（外链 app2.zstv47.com）
            if (href.indexOf('app2.zstv47.com') >= 0) continue;
            // 只认 /dsshiyipy/{vid}-{src}-{ep}.html
            var m = href.match(/\/dsshiyipy\/(\d+)-(\d+)-(\d+)\.html/);
            if (!m) continue;
            if (curVid && m[1] !== curVid) continue;

            // 集数名清洗：第01集 -> 01
            var dim = name.match(/^第(\d+)集$/);
            if (dim) {
                var n = parseInt(dim[1], 10);
                name = n < 10 ? '0' + n : '' + n;
            }
            if (!name) name = String(eps.length + 1);

            eps.push({ name: name, url: _full(href) });
        }

        if (eps.length) {
            lineNames.push(lineName);
            allLinesEp.push(eps);
        }
    }

    return { lineNames: lineNames, allLinesEp: allLinesEp };
}
"},{"col_type":"movie_3","name":"4 播放解析","path":"push4","rule":"/* ================================================================
 * 模板模块 4/4 · 播放解析  (tpl_4_play.js)
 *
 * 【对应页面】 视频播放页（点击集数后跳转的页面）
 * 【要做的事】
 *   1. 设置站内解析口（如果有）
 *   2. 确认 player_aaaa 提取方式是否正确
 *   3. 根据网站实际情况调整3级解析逻辑
 * 【调试方法】
 *   1. 打开任意视频播放页，F12 查看源码
 *   2. 搜索 "player_aaaa"，看里面的 url 和 encrypt 字段
 *   3. 如果 encrypt=1，url 是编码过的，需要解码
 *   4. 点击"查看网页源代码"，搜索 .m3u8 或 .mp4 看有没有直链
 *   5. 如果是视频站链接（腾讯/奇艺等），测试站内解析口是否可用
 *
 * 【依赖】 必须在 hiker_lib.js 之后加载（这个模块可以独立加载）
 * 【输出】 buildPlayUrl(epItem)  返回 lazyRule URL
 *
 * 【解析逻辑分3级】
 *   1级：直链 m3u8/mp4 → 直接播放
 *   2级：视频站链接（腾讯/奇艺/优酷/芒果/B站）→ 站内解析口 + video:// 嗅探
 *   3级：其他链接 → 二次抓取页面提取 m3u8/mp4
 * ================================================================ */


/* ===== 1. 【改】站内解析口配置 ===== */
// ═══════════════════════════════════════════════════════════
// 说明：如果网站有自己的解析接口，填在这里。
//       格式：'https://域名/player/?url={url}'
//       {url} 会自动替换为视频站链接
//
// 怎么找解析口？
//   1. 播放页F12，Network标签，过滤 XHR
//   2. 点击播放，看有没有请求解析接口
