function parseSections(html) {
    var all = [];
    if (!html) return all;

    var parts = html.split(/<h2[^>]*>/);

    for (var i = 1; i < parts.length; i++) {
        var part = parts[i];
        var tEnd = part.indexOf('</h2>');
        if (tEnd < 0) continue;

        var secTitle = part.substring(0, tEnd).replace(/<[^>]+>/g, '').trim();
        if (!secTitle) continue;

        if (secTitle.indexOf('搜索') >= 0) continue;
        if (secTitle.indexOf('记录') >= 0) continue;
        if (secTitle.indexOf('友情') >= 0) continue;
        if (secTitle.indexOf('关于') >= 0) continue;
        if (secTitle.indexOf('联系') >= 0) continue;
        if (secTitle.length > 20) continue;

        var items = parseList(part);
        if (items.length) all.push({ title: secTitle, items: items });
    }

    if (!all.length) {
        var parts3 = html.split(/<h3[^>]*>/);
        for (var j = 1; j < parts3.length; j++) {
            var part3 = parts3[j];
            var tEnd3 = part3.indexOf('</h3>');
            if (tEnd3 < 0) continue;
            var secTitle3 = part3.substring(0, tEnd3).replace(/<[^>]+>/g, '').trim();
            if (!secTitle3 || secTitle3.length > 20) continue;
            if (secTitle3.indexOf('搜索') >= 0) continue;
            if (secTitle3.indexOf('友情') >= 0) continue;
            var items3 = parseList(part3);
            if (items3.length) all.push({ title: secTitle3, items: items3 });
        }
    }

    if (!all.length) {
        var partsM = html.split(/class="module-head[^"]*"[^>]*>/);
        for (var k = 1; k < partsM.length; k++) {
            var partM = partsM[k];
            var tEndM = partM.indexOf('</div>');
            if (tEndM < 0) continue;
            var secTitleM = partM.substring(0, tEndM).replace(/<[^>]+>/g, '').trim();
            if (!secTitleM || secTitleM.length > 20) continue;
            if (secTitleM.indexOf('搜索') >= 0) continue;
            var itemsM = parseList(partM);
            if (itemsM.length) all.push({ title: secTitleM, items: itemsM });
        }
    }

    if (!all.length) {
        var allItems = parseList(html);
        if (allItems.length) all = [{ title: '最新推荐', items: allItems }];
    }

    return all;
}

function getSearchUrl(keyword) {
    return SITE.host + '/vodsearch/-------------/?wd=' + encodeURIComponent(keyword);
}
