function extractEpisodes(html) {
    var lineNames = [];
    var allLinesEp = [];

    if (!html) return { lineNames: lineNames, allLinesEp: allLinesEp };

    /* 片库网详情页结构：
     *   <div class="stui-pannel clearfix">
     *     <div class="stui-pannel__head clearfix">
     *       <h3 class="title">hnyun</h3>  ← 线路名
     *     </div>
     *     <ul class="stui-content__playlist clearfix">
     *       <li><a href="/k/97282-1-1/">第01集</a></li>
     *       ...
     *     </ul>
     *   </div>
     */

    /* 按 stui-pannel 分割，每个pannel可能是一条线路 */
    var pannels = html.split(/<div class="stui-pannel clearfix">/);

    for (var pi = 1; pi < pannels.length; pi++) {
        var pannel = pannels[pi];

        /* 提取线路名：<h3 class="title">hnyun</h3> */
        var nameM = pannel.match(/<h3[^>]*class="title"[^>]*>([^<]+)<\/h3>/);
        if (!nameM) continue;
        var lineName = nameM[1].trim();

        /* 跳过非线路的pannel（剧情介绍、猜你喜欢等） */
        if (lineName.indexOf('剧情') >= 0) continue;
        if (lineName.indexOf('猜你') >= 0) continue;
        if (lineName.indexOf('喜欢') >= 0) continue;
        if (lineName.indexOf('相关') >= 0) continue;
        if (lineName.length > 20) continue;

        /* 提取集数列表：<ul class="stui-content__playlist clearfix"> */
        var ulM = pannel.match(/<ul class="stui-content__playlist clearfix">([\s\S]*?)<\/ul>/);
        if (!ulM) continue;

        var eps = [];
        var aRe = /<a[^>]*href="(\/k\/[^"]+)"[^>]*>([^<]+)<\/a>/g;
        var am;
        while ((am = aRe.exec(ulM[1])) !== null) {
            var epHref = am[1];
            var epName = am[2].trim();
            if (!epName) continue;

            if (epHref.indexOf('http') !== 0 && epHref.indexOf('//') !== 0) {
                epHref = _full(epHref);
            }
            eps.push({ name: epName, url: epHref });
        }

        if (eps.length > 0) {
            lineNames.push(lineName);
            allLinesEp.push(eps);
        }
    }

    return { lineNames: lineNames, allLinesEp: allLinesEp };
}


