"},{"col_type":"movie_3","name":"4 播放解析","path":"push4","rule":"function buildPlayUrl(epItem) {
    var playPageUrl = epItem.url || '';
    if (!playPageUrl) return 'toast://无播放地址';

    return $(playPageUrl).lazyRule(function (pu, host, ua) {
        try {
            var ph = fetch(pu, {
                headers: { "User-Agent": ua, "Referer": host + "/" }
            });

            var urlM = ph.match(/player_aaaa\s*=\s*\{[\s\S]*?"url"\s*:\s*"([^"]+)"/);
            if (!urlM) urlM = ph.match(/player_data\s*=\s*\{[\s\S]*?"url"\s*:\s*"([^"]+)"/);
            if (!urlM) urlM = ph.match(/var\s+url\s*=\s*["']([^"']+)["']/);

            var encM = ph.match(/player_aaaa\s*=\s*\{[\s\S]*?"encrypt"\s*:\s*(\d+)/);
            var playerUrl = urlM ? urlM[1] : '';
            var encrypt = encM ? encM[1] : '0';

            playerUrl = playerUrl.replace(/\\\//g, '/').replace(/\\u002f/g, '/');
            if (encrypt === '1' && playerUrl) {
                try { playerUrl = decodeURIComponent(playerUrl); } catch (e) {}
            }
            if (!playerUrl || playerUrl.length < 5) {
                var b64M = ph.match(/"url"\s*:\s*"([A-Za-z0-9+/=]{20,})"/);
                if (b64M) {
                    try {
                        if (typeof atob === 'function') {
                            playerUrl = atob(b64M[1]);
                        }
                    } catch(e) {}
                }
            }

            if (playerUrl && /\.m3u8|\.mp4|\.m4a/i.test(playerUrl)) {
                if (playerUrl.indexOf('http') !== 0) {
                    if (playerUrl.indexOf('//') === 0) playerUrl = 'https:' + playerUrl;
                    else playerUrl = host + '/' + playerUrl.replace(/^\//, '');
                }
                return playerUrl + '#isVideo=true#';
            }

            if (!playerUrl || !/\.(m3u8|mp4)/i.test(playerUrl)) {
                var m = ph.match(/https?:\/\/[^'"\s,]+\.m3u8[^'"\s,]*/i);
                if (m) return m[0] + '#isVideo=true#';
            }

            if (!playerUrl) {
                var iframeM = ph.match(/<iframe[^>]*src="([^"]+)"[^>]*>/i);
                if (iframeM) {
                    var iframeUrl = iframeM[1];
                    if (iframeUrl.indexOf('http') !== 0) {
                        if (iframeUrl.indexOf('//') === 0) iframeUrl = 'https:' + iframeUrl;
                        else iframeUrl = host + '/' + iframeUrl.replace(/^\//, '');
                    }
                    if (/\.(m3u8|mp4)/i.test(iframeUrl)) {
                        return iframeUrl + '#isVideo=true#';
                    }
                }
            }

            if (playerUrl && playerUrl.indexOf('http') === 0) {
                try {
                    var midRes = fetch(playerUrl, {
                        headers: {
                            "User-Agent": ua,
                            "Referer": host + "/",
                            "Accept": "*/*"
                        }
                    });

                    var midM3u8 = midRes.match(/https?:\/\/[^'"\s,\\]+\.m3u8[^'"\s,\\]*/i);
                    if (midM3u8) return midM3u8[0] + '#isVideo=true#';

                    var midPlayer = midRes.match(/var\s+player\s*=\s*\{[\s\S]*?"url"\s*:\s*"([^"]+)"/);
                    if (midPlayer && /\.m3u8|\.mp4/i.test(midPlayer[1])) {
                        var midUrl = midPlayer[1].replace(/\\\//g, '/');
                        if (midUrl.indexOf('http') !== 0) {
                            if (midUrl.indexOf('//') === 0) midUrl = 'https:' + midUrl;
                        }
                        return midUrl + '#isVideo=true#';
                    }

                    var midVideo = midRes.match(/<video[^>]*src="([^"]+)"/i);
                    if (midVideo && /\.m3u8|\.mp4/i.test(midVideo[1])) {
                        return midVideo[1] + '#isVideo=true#';
                    }

                    var midIframe = midRes.match(/<iframe[^>]*src="([^"]+)"[^>]*>/i);
                    if (midIframe) {
                        var miUrl = midIframe[1];
                        if (miUrl.indexOf('http') !== 0) {
                            if (miUrl.indexOf('//') === 0) miUrl = 'https:' + miUrl;
                        }
                        if (/\.m3u8|\.mp4/i.test(miUrl)) {
                            return miUrl + '#isVideo=true#';
                        }
                    }
                } catch(e) {}
            }

            return pu + '#isVideo=true#';

        } catch (e) {
            return 'toast://解析失败';
        }
    }, playPageUrl, SITE.host, _cfg.ua);
}
