        if (u.indexOf('fengbao12.com') > -1)  return u + '#isVideo=true#;{Referer@https://www.js-jiuyi.com/&&User-Agent@' + UA + '}';
        if (u.indexOf('juhaokan') > -1)       return u + ';{Referer@https://www.juhaokan.cc/}';
        if (u.indexOf('ojbk') > -1)           return u + ';{Referer@https://v.ojbkjx.com/}';
        if (u.indexOf('wkfile') > -1)         return u + ';{Referer@https://fantuan.wkfile.com/}';
        return u + '#isVideo=true#';
    }

    /* ---------------- 快速通道：直取 player_aaaa ---------------- */
    function httpGet(url) {
        var fns = [];
        fns.push(function () { return fba.fetch(url, {}); });
        fns.push(function () { return fba.fetch(url, { 'User-Agent': UA }); });
        fns.push(function () { return fetch(url); });
        fns.push(function () { return $.fetch(url); });
        for (var i = 0; i < fns.length; i++) {
            try { var r = fns[i](); if (r && String(r).length > 200) return String(r); } catch (e) {}
        }
        return '';
    }

    function fastParse(playUrl) {
        var html = httpGet(playUrl);
        if (!html) return '';
        var list = [], mm;

        // 1) player_aaaa（苹果CMS，encrypt:0 时 url 就是明文）
        var blocks = html.match(/player_aaaa\s*=\s*\{[\s\S]{0,3000}?\}/g) || [];
        for (var i = 0; i < blocks.length; i++) {
            var m = blocks[i].replace(/\\\//g, '/').match(/"url"\s*:\s*"([^"]+)"/);
            if (m) list.push(m[1]);
        }
        // 2) 通用 "url":"xxx.m3u8"
        var re1 = /["']url["']\s*[:=]\s*["']([^"']+\.(?:m3u8|mp4|flv)[^"']*)["']/gi;
        while ((mm = re1.exec(html)) !== null) list.push(mm[1]);
        // 3) 裸 m3u8（兼容 \/ 转义）
        var re2 = /https?:[\\/]*[^\s"'<>)]+?\.m3u8[^\s"'<>)]*/gi;
        while ((mm = re2.exec(html)) !== null) list.push(mm[0]);

        for (var k = 0; k < list.length; k++) {
            var u = unwrap(list[k]);
            if (isOk(u)) return withHeader(u);
        }
        return '';
    }

    /* ---------------- webRule 嗅探兜底（内部自包含，不能调外部函数） ---------------- */
    function x5rule(jiexurl, srcurl) {
        showLoading("网页访问检索中，请稍候...");
        return 'webRule://' + jiexurl + '@' + $.toString((srcurl) => {

            var UA = 'Mozilla/5.0 (Linux; Android 16; 23113RKC6C Build/BP2A.250605.031.A3) AppleWebKit/537.36 (KHTML, like Gecko) Version/4.0 Chrome/143.0.7499.192 Mobile Safari/537.36';

            function fix(u) {
                if (!u) return '';
                u = String(u).replace(/\\u002F/gi, '/').replace(/\\\//g, '/')
                             .replace(/&amp;/g, '&').replace(/^[\s"']+|[\s"']+$/g, '');
                if (u.indexOf('//') === 0) u = 'https:' + u;
                return u;
            }
            function unwrap(u) {
                u = fix(u);
                var m = u.match(/[?&](?:url|v|play|link)\s*=\s*([^&]+)/i);
                if (m) {
                    var inner = '';
                    try { inner = decodeURIComponent(m[1]); } catch (e) { inner = m[1]; }
                    inner = fix(inner);
                    if (/^https?:\/\//i.test(inner)) return inner;
                }
                return u;
            }
            function isTrash(u) {
                return /paly[-\s]?\d|fa2025888|vipuuvip|\/shyq\/|m3u8\.tv|ac=dm|&next|[?&](?:url|v|play|link)=|\.html(\?|$)/i.test(u);
            }
            function isStream(u) {
                return /^https?:\/\//i.test(u) &&
                    /\.m3u8|\.mp4|\.flv|video_mp4|type=m3u8|pt=m3u8|dycdn-tos\.pstatp|netease\.com|fengbao12|bilivideo|titan\.mgtv/i.test(u);
            }
            function isOk(u) { return !!u && isStream(u) && !isTrash(u); }
            function withHeader(u) {
                if (!u) return '';
                if (u.indexOf('bilivideo') > -1)      return u + ';{Referer@https://www.bilibili.com&&User-Agent@' + UA + '}';
                if (u.indexOf('titan.mgtv.com') > -1) return u + '#isVideo=true#;{Referer@https://www.mgtv.com&&User-Agent@' + UA + '}';
                if (u.indexOf('fengbao12.com') > -1)  return u + '#isVideo=true#;{Referer@https://www.js-jiuyi.com/&&User-Agent@' + UA + '}';
                if (u.indexOf('juhaokan') > -1)       return u + ';{Referer@https://www.juhaokan.cc/}';
                if (u.indexOf('ojbk') > -1)           return u + ';{Referer@https://v.ojbkjx.com/}';
                if (u.indexOf('wkfile') > -1)         return u + ';{Referer@https://fantuan.wkfile.com/}';
                return u + '#isVideo=true#';
            }

            if (window.count == null) window.count = 0;
            if (window.count >= 15) { fba.hideLoading(); return srcurl; }
            window.count = window.count + 1;

            // 1~3 次：防盗链检测 + 回跳
            if (window.count > 1 && window.count <= 3) {
                var body = document.querySelector('body');
                var txt = body ? (body.innerText || '') : '';
                if (txt.search(/触发了防盗链|未授权|接口防盗|请到主站观看/) != -1) {
