            var urls = _getUrls() || [];
            var list = [];
            for (var i = 0; i < urls.length; i++) {
                var u = unwrap(urls[i]);
                if (u) list.push(u);
            }
            list.push(unwrap(location.href));

            for (var j = 0; j < list.length; j++) {
                if (isOk(list[j])) {
                    fba.log('命中直链：' + list[j]);
                    fba.hideLoading();
                    return withHeader(list[j]);
                }
            }

            // 异步接口场景：抓一次源码再找
            if (window.count > 5 && window.count <= 8) {
                var html = '';
                try { html = fba.fetch(location.href, {}); } catch (e) {}
                if (html) {
                    var h = html.replace(/\\\//g, '/');
                    var m = h.match(/"url"\s*:\s*"([^"]+)"/) || h.match(/https?:[\\/]*[^\s"'<>)]+?\.m3u8[^\s"'<>)]*/i);
