var d = [];
var html = getResCode();

function setFont(title, color) {
    return '‘‘’’<small><font color=' + color + '>' + title + '</font></small>';
}

function getLast(data) {
    try {
        var i, t;
        var ps = pdfa(data, '.data&&a');
        for (i = 0; i < ps.length; i++) {
            t = '' + pdfh(ps[i], 'body&&Text');
            if (t.indexOf('最新') > -1) return t.trim();
        }
        var all = '' + pdfh(data, 'body&&Text');
        var m = all.match(/最新[：:\s]*[^\n\r]{0,50}/);
        if (m) return m[0].trim();
        for (i = ps.length - 1; i >= 0; i--) {
            t = ('' + pdfh(ps[i], 'body&&Text')).trim();
            if (t.indexOf('第') === 0) return t;
        }
        var m2 = all.match(/第\s*\d+\s*章[^\n\r]{0,40}/);
        if (m2) return m2[0].trim();
    } catch (e) {}
    return '';
}

var list = pdfa(html, 'body&&.box&&.row&&.col-12');
for (var j in list) {
    var data = list[j];
    var spans = pdfa(data, '.book_other&&span,1:2');
    var hot = '' + (spans[0] ? pdfh(spans[0], 'body&&Text') : '');
    var status = '' + (spans[1] ? pdfh(spans[1], 'body&&Text') : '');
    var name = pdfh(data, 'a&&title');
    var last = getLast(data);
    if (last && last.indexOf('最新') === -1) last = '最新：' + last;

    var line3 = '';
    if (hot) line3 += setFont(hot, '#FF5722');
    if (status) {
        if (line3) line3 += '\t\t';
        line3 += setFont(status, '#1E9FFF');
    }
    if (last) {
        if (line3) line3 += '\t\t';
        line3 += setFont(last, '#009688');
    }

    d.push({
        title: pdfh(data, 'h3&&Text') + '\n' +
               setFont('' + pdfh(data, '.book_other&&Text'), '#2F4056') +
               (line3 ? '\n' + line3 : ''),
        desc: pdfh(data, '.book-desc&&Text'),
        pic_url: pd(data, 'img&&src') + '@Referer=',
        url: pd(data, 'a&&href') + "#immersiveTheme##autoCache#",
        col_type: '',
        extra: {
            longClick: [{
                title: '聚阅搜索：' + name,
                js: $.toString((title) => {
                    return 'hiker://page/sousuopage?rule=聚阅√&keyword=' + title + '&type=听书'
                }, name)
            }]
        }
    });
}
setResult(d);

