 * |  | [缓存] 数据级缓存                                                |  |
 * |  |   cacheGet(type, url)       读取缓存（过期自动清除）          |  |
 * |  |   cacheSet(type, url, data, expireMs)  写入缓存               |  |
 * |  |   cacheClear(type, url)     清除指定缓存                     |  |
 * |  |   _cacheKey(type, url)      生成缓存键名（内部）              |  |
 * |  +--------------------------------------------------------------+  |
 * |                                                                  |
 * |  !!!!!! 再次提醒：不要改这个文件！!!!!!!                         |
 * |  有问题改规则文件本身，不要动共享库。                              |
 * |                                                                  |
 * |  ═══════════════════════════════════════════════════════════     |
 * |  【修改指南 — 教你区分可改 vs 不可改】                           |
 * |  ═══════════════════════════════════════════════════════════     |
 * |                                                                  |
 * |  本文件所有代码都是 [禁改] 禁止修改 的！                              |
 * |  你只能在【调用方】（其他文件）里使用这些函数。                   |
 * |                                                                  |
 * |  [禁改] 禁止修改的内容：                                              |
 * |    - 所有 function 的名称和参数                                  |
 * |    - 所有 var 变量的名称                                          |
 * |    - 所有函数内部的实现逻辑                                       |
 * |    - _cfg 默认值（用 initLib() 设置，不要直接改）               |
 * |                                                                  |
 * |  [可改] 可以做的操作（在其他文件里）：                                |
 * |    - 调用 initLib() 设置站点信息                                 |
 * |    - 调用 _fetch(url) 发请求                                     |
 * |    - 调用 cacheGet/cacheSet 管理缓存                            |
 * |    - 调用 render* 函数渲染界面                                   |
 * |                                                                  |
 * |  [可改] 使用示例（在其他文件里调用）：                               |
 * |    // 初始化                                                      |
 * |    initLib({ host: 'https://xxx.com', prefix: 'xx' });           |
 * |                                                                  |
 * |    // 带缓存请求                                                  |
 * |    var html = _fetch('https://xxx.com/');                        |
 * |                                                                  |
 * |    // 缓存数据 2 小时                                             |
 * |    cacheSet('home', url, data, 2 * 60 * 60 * 1000);              |
 * |                                                                  |
 * |    // 读取缓存                                                    |
 * |    var cached = cacheGet('home', url);                           |
 * |    if (cached) { ...直接用缓存数据... }                          |
 * |                                                                  |
 * |    // 清除缓存                                                    |
 * |    cacheClear('home', url);                                      |
 * |  ═══════════════════════════════════════════════════════════     |
 * +------------------------------------------------------------------+
 * ================================================================ */


/* ================================================================
 * ⚙️ 站点配置变量
 * ----------------------------------------------------------------
 * 用 initLib() 初始化，不要直接改这里
 * _cfg 保存全局配置，所有函数都通过 _cfg 读取站点信息
 * ================================================================ */
var _cfg = {
    host: '',                                          // 站点域名，如 'https://www.pkavi.com'
    ua: 'Mozilla/5.0 (Linux; Android 12) AppleWebKit/537.36',  // 默认UA（安卓伪装）
    prefix: 'hk',                                      // 变量前缀，多站共存时避免变量冲突
    timeout: 8000                                      // 请求超时（毫秒）
};

/* ================================================================
 * ⚙️ 初始化函数
 * ----------------------------------------------------------------
 * 调用方式：
 *   initLib({
 *       host: 'https://www.pkavi.com',   // 必填
 *       prefix: 'pk',                     // 必填，每个站用不同前缀
 *       ua: '...',                         // 选填
 *       timeout: 8000                      // 选填
 *   });
 * ================================================================ */
function initLib(cfg) {
    _cfg.host = cfg.host || '';
    _cfg.ua = cfg.ua || _cfg.ua;
    _cfg.prefix = cfg.prefix || 'hk';
    _cfg.timeout = cfg.timeout || _cfg.timeout;
}

/* ================================================================
 * ⚙️ 筛选变量key
 * ----------------------------------------------------------------
 * 每个规则+前缀组合一个唯一key，存筛选状态（地区/类型/年份等）
 * 格式：{规则名}_{前缀}filter  如 "七味网_pkfilter"
 * ================================================================ */
function _filterKey() {
    return MY_RULE.title + '_' + _cfg.prefix + 'filter';
}


/* ================================================================
 * ================================================================
 * [工具] 工具函数（内部用，一般不直接调）
 * ================================================================
 * ================================================================ */

/* ----------------------------------------------------------------
 * _full(u) — 相对URL转完整URL
 * ----------------------------------------------------------------
 * 把网站里看到的相对路径（如 '/mv/123.html'）转成完整URL
 *
 * 处理逻辑：
 *   1. 以 http 开头 → 已经是完整URL，直接返回（清理 &amp;）
 *   2. 以 // 开头 → 补上 https:
 *   3. 其他 → 去掉开头的 ./ 或 /，前面加上站点域名
 *
 * 示例：
 *   _full('/mv/123.html') → 'https://www.pkavi.com/mv/123.html'
 *   _full('https://xxx.com/a.mp4') → 原样返回
 * ============================================================= */
function _full(u) {
    if (!u) return '';
    if (u.indexOf('http') === 0) return u.replace(/&amp;/g, '&');
    if (u.indexOf('//') === 0) return 'https:' + u;
    u = u.replace(/^\.?\//, '');
    return _cfg.host + '/' + u;
}

/* ----------------------------------------------------------------
 * _hdr() — 返回请求头对象
 * ----------------------------------------------------------------
 * 所有请求都带上伪装的UA和Referer，防止被网站拦截
 * ============================================================= */
function _hdr() {
    return { headers: { "User-Agent": _cfg.ua, "Referer": _cfg.host + "/" } };
}

/* ----------------------------------------------------------------
 * _fetch(url) — 带UA+Referer+缓存的请求
 * ----------------------------------------------------------------
 * 封装 fetch()，自动加请求头和缓存标记
 * #autoCache# 让海阔自动缓存请求结果，减少重复请求
 * 出错时返回空字符串，不会抛异常
 * ============================================================= */
function _fetch(url) {
    try { return fetch(url + '#autoCache#', _hdr()); } catch (e) { return ""; }
}


/* ================================================================
 * ================================================================
 * [缓存] 数据级缓存 — 缓存解析后的数据，避免重复请求+解析
 * ================================================================
 * ================================================================
 * !!!!!! 以下所有缓存函数禁止修改！!!!!!!
 *
 * 【为什么需要数据级缓存？】
 *   海阔的 #autoCache# 只缓存 HTTP 响应（HTML字符串）
 *   但每次打开页面，还是要重新 pdfa/pdfh 解析 HTML
 *   数据级缓存把【解析结果】直接存本地，下次打开秒出
 *
 * 【缓存策略（建议值，可在调用方调整）】
 *   首页板块数据  → 缓存 2 小时  (2 * 60 * 60 * 1000)
 *   分类列表数据  → 缓存 1 小时  (1 * 60 * 60 * 1000)
 *   详情页数据    → 缓存 6 小时  (6 * 60 * 60 * 1000)
 *   搜索结果      → 不缓存（每次都新的）
 *   播放地址      → 缓存 12 小时 (12 * 60 * 60 * 1000)
 *
 * 【缓存存储位置】
 *   使用海阔的 storage0 API（本地持久化存储）
 *   key 格式：{prefix}_cache_{type}_{urlHash}
 *
 * [可改] 使用示例（在其他文件里调用）：
 *   // 写入缓存：缓存首页数据 2 小时
 *   cacheSet('home', SITE.host + '/', sections, 2 * 60 * 60 * 1000);
 *
 *   // 读取缓存：有缓存直接用，没有再请求
 *   var cached = cacheGet('home', SITE.host + '/');
 *   if (cached) { ...直接用缓存数据渲染... }
 *
 *   // 清除缓存：数据更新后手动清除
 *   cacheClear('home', SITE.host + '/');
 *
 *   // 清除该站所有缓存
 *   cacheClear('*', '');
 * ================================================================ */

/* ----------------------------------------------------------------
 * _cacheKey(type, url) — 生成缓存键名
 * ----------------------------------------------------------------
 * !! 禁止修改！被 cacheGet/cacheSet/cacheClear 内部调用
 *
 * 参数：
 *   type — 缓存类型（'home' / 'cat' / 'detail' / 'play'）
 *   url  — 请求的URL
 * 返回：缓存键名字符串，如 "pk_cache_home_httpswwwpkavicom"
 * ============================================================= */
function _cacheKey(type, url) {
    /* 把URL里的非字母数字去掉，截取前60个字符作为key的一部分 */
    /* 加上 prefix 前缀，确保不同站的缓存互不干扰 */
    return _cfg.prefix + '_cache_' + type + '_' + String(url).replace(/[^a-zA-Z0-9]/g, '').substring(0, 60);
}

/* ----------------------------------------------------------------
 * cacheGet(type, url) — 读取缓存
 * ----------------------------------------------------------------
 * !! 禁止修改！
 *
 * 参数：
 *   type — 缓存类型（'home' / 'cat' / 'detail' / 'play'）
 *   url  — 原始请求URL
 * 返回：缓存的数据对象；过期或不存在返回 null
 *
 * 自动过期判断：读取时检查时间戳，过期自动删除并返回 null
 * ============================================================= */
function cacheGet(type, url) {
    try {
        var key = _cacheKey(type, url);
        var raw = storage0.getItem(key);
        if (!raw) return null;
        var obj = JSON.parse(raw);
        var now = new Date().getTime();
        /* expire > 0 表示有过期时间，检查是否过期 */
        if (obj.expire > 0 && now - obj.time > obj.expire) {
            /* 过期了 → 删除缓存，返回 null */
            storage0.removeItem(key);
            return null;
        }
        return obj.data;
    } catch (e) {
        /* 出错（如缓存损坏）→ 返回 null，不影响正常流程 */
        return null;
    }
}

/* ----------------------------------------------------------------
 * cacheSet(type, url, data, expireMs) — 写入缓存
 * ----------------------------------------------------------------
 * !! 禁止修改！
 *
 * 参数：
 *   type     — 缓存类型（'home' / 'cat' / 'detail' / 'play'）
 *   url      — 原始请求URL（用于生成key）
 *   data     — 要缓存的数据（对象/数组/字符串都行）
 *   expireMs — 过期时间（毫秒），0 = 永不过期
 *
 * [可改] 使用示例：
 *   // 缓存首页板块数据 2 小时
 *   cacheSet('home', SITE.host + '/', allSections, 2 * 60 * 60 * 1000);
 *
 *   // 缓存详情页数据 6 小时
 *   cacheSet('detail', detailUrl, { info: info, epData: epData }, 6 * 60 * 60 * 1000);
 *
 *   // 永不过期（需要手动清除）
 *   cacheSet('play', playUrl, playLink, 0);
 * ============================================================= */
function cacheSet(type, url, data, expireMs) {
    try {
        var key = _cacheKey(type, url);
        /* 存储格式：{ data: 数据, time: 写入时间戳, expire: 过期毫秒数 } */
        storage0.setItem(key, JSON.stringify({
            data: data,
            time: new Date().getTime(),
            expire: expireMs || 0
        }));
    } catch (e) {
        /* 存储失败（如空间不足）→ 静默忽略，不影响正常流程 */
    }
}

/* ----------------------------------------------------------------
 * cacheClear(type, url) — 清除缓存
 * ----------------------------------------------------------------
 * !! 禁止修改！
 *
 * 参数：
 *   type — 缓存类型
 *          传具体类型（如 'home'）→ 只清这一条
 *          传 '*' → 清除该站所有缓存
 *   url  — 原始请求URL（type='*' 时忽略）
 *
 * [可改] 使用示例：
 *   // 清除某条首页缓存
 *   cacheClear('home', SITE.host + '/');
 *
 *   // 清除该站全部缓存（换站或数据更新时）
 *   cacheClear('*', '');
 * ============================================================= */
function cacheClear(type, url) {
    try {
        if (type === '*') {
            /* 遍历所有 storage 键，清除带本站前缀的 */
            var keys = storage0.keys();
            for (var i = 0; i < keys.length; i++) {
                if (keys[i].indexOf(_cfg.prefix + '_cache_') === 0) {
                    storage0.removeItem(keys[i]);
                }
            }
        } else {
            storage0.removeItem(_cacheKey(type, url));
        }
    } catch (e) {}
}


/* ----------------------------------------------------------------
 * isCaptcha(html) — 检测是否验证码页面
 * ----------------------------------------------------------------
 * 有些网站在频繁访问时会弹出验证码，检测到后提示用户
 * 通过检查页面中是否有"系统安全验证"等关键词判断
 * ============================================================= */
function isCaptcha(html) {
    if (!html) return true;
    return html.indexOf('系统安全验证') >= 0 || html.indexOf('mac_verify') >= 0;
}

/* ----------------------------------------------------------------
 * getRangeColors() — 生成随机浅色背景色
 * ----------------------------------------------------------------
 * 用于分类按钮等元素的随机背景色，让界面看起来不单调
 * 返回格式：'#a3f5c1'（6位hex色值）
 * ============================================================= */
function getRangeColors() {
    return '#' + ('00000' + (Math.random() * 0x1000000 << 0).toString(16)).substr(-6);
}


/* ================================================================
 * ================================================================
 * [首页] 首页用函数 — 轮播图
 * ================================================================
 * ================================================================
 * banner()         → 轮播图核心逻辑（定时自动切换图片）
 * renderBanner()   → 渲染轮播图 + 开关按钮
 *
 * 数据格式：
 *   lunData = [{ title, img, desc, url }, ...]
 *
 * 调用方式：
 *   renderBanner(d, lunData, MY_RULE.title);
 *   // 或者直接用核心函数：
 *   banner(MY_RULE.title, true, d, lunData, { time: 3000 });
 * ================================================================ */

/* ----------------------------------------------------------------
 * banner() — 轮播图核心函数
 * ----------------------------------------------------------------
 * 参数说明：
 *   title   — 轮播图唯一标识（用 MY_RULE.title，避免多规则冲突）
 *   start   — 是否启动自动轮播
 *   arr     — 结果数组 d（往里面 push 轮播卡片）
 *   data    — 轮播数据 [{title, img, desc, url}, ...]
 *   cfg     — 配置 {
 *       time: 3000,           // 切换间隔（毫秒）
 *       col_type: 'pic_1_card', // 卡片类型
 *       desc: '热播推荐'       // 卡片描述
 *   }
 *
 * 工作原理：
 *   1. 随机选一张图作为初始显示
 *   2. 注册定时任务，每隔 time 毫秒切换到下一张
 *   3. 通过 updateItem() 更新卡片内容
 *   4. 全局变量 benstart 控制开关
 * ============================================================= */
function banner(title, start, arr, data, cfg) {
    var id = title + 'lunbo';
    var rnum = Math.floor(Math.random() * data.length);
    var item = data[rnum];
    putMyVar('rnum', rnum);
    var time = 3000;
    var col_type = 'pic_1_card';
    var desc = '';
    if (cfg != undefined) {
        time = cfg.time ? cfg.time : time;
        col_type = cfg.col_type ? cfg.col_type : col_type;
        desc = cfg.desc ? cfg.desc : desc;
    }
    arr.push({
        col_type: col_type,
        img: item.img,
        desc: desc,
        title: item.title,
        url: item.url,
        extra: { id: id + 'bar' }
    });
    if (start == false || getMyVar('benstart', 'true') == 'false') {
        unRegisterTask(id);
        return;
    }
    var obj = { data: data };
    registerTask(id, time, $.toString(function (obj, id) {
        var data = obj.data;
        var rum = getMyVar('rnum');
        var i = Number(getMyVar('banneri', '0'));
        if (rum != '') {
            i = Number(rum) + 1;
            clearMyVar('rnum');
        } else {
            i = i + 1;
        }
        if (i > data.length - 1) i = 0;
        var item = data[i];
        try {
            updateItem(id + 'bar', {
                title: item.title,
                desc: item.desc || '',
                img: item.img,
                url: item.url,
                extra: item.extra || {}
            });
        } catch (e) {
            log(e.message);
            unRegisterTask(id);
        }
        putMyVar('banneri', i);
    }, obj, id));
}

/* ----------------------------------------------------------------
 * renderBanner() — 渲染轮播图 + 开关按钮
 * ----------------------------------------------------------------
 * 调用方式：renderBanner(d, lunData, MY_RULE.title);
 *
 * 渲染内容：
 *   1. 轮播开关按钮（ON/OFF），点击切换状态
 *   2. 轮播图片卡片（自动播放）
 *
 * 全局变量：
 *   benstart — 'true' 开启轮播 / 'false' 关闭轮播
 * ============================================================= */
function renderBanner(d, lunData, ruleTitle) {
    if (!lunData || !lunData.length) return;

    var benStart = getMyVar('benstart', 'true') == 'true';
    d.push({
        title: benStart ? '\u2018\u2018\u2019\u2019<b><font color="#FF5D50">轮播 ON</font></b>' : '\u2018\u2018\u2019\u2019<b>轮播 OFF</b>',
        url: $('#noLoading#').lazyRule(function () {
            var cur = getMyVar('benstart', 'true');
            putMyVar('benstart', cur == 'true' ? 'false' : 'true');
            refreshPage(true);
            return 'hiker://empty';
        }),
        col_type: 'scroll_button',
        extra: { backgroundColor: benStart ? '#20FA7298' : '#20CCCCCC' }
    });
    d.push({ col_type: 'line_blank' });

    banner(ruleTitle, true, d, lunData, {
        time: 4000,
        col_type: 'pic_1_card',
        desc: '热播推荐'
    });
    d.push({ col_type: 'line_blank' });
}


/* ================================================================
 * ================================================================
 * [首页] 首页用函数 — 搜索框
 * ================================================================
 * ================================================================
 * 调用方式：renderSearchBox(d);
 *
 * 渲染一个输入框，用户输入关键词后跳转到搜索页面
 * 搜索时使用 MY_RULE.title 作为规则名（海阔内置变量）
 *
 * !! 注意：规则文件里不要自己定义 var MY_RULE = {...}
 *     会覆盖海阔内置的 MY_RULE，导致搜索提示"找不到搜索引擎"
 * ================================================================ */

function renderSearchBox(d) {
    /* 照独播库正常规则：跳 hiker://search?rule=<本规则真实标题>，靠 &rule= 锁本规则，
     * 绝不回落全局搜索（回落=请求全局死域 search_url，触发 Connection reset）。
     * 关键点：MY_RULE.title 在规则顶层求值、烤成字面量进 rn，url 里只剩 +input 尾巴；
     * input 由海阔在确认时代入。取不到 MY_RULE.title 时兜底 '蚂蚁影视'，绝不 undefined。 */
    var rn = (typeof MY_RULE !== "undefined" && MY_RULE && MY_RULE.title) ? MY_RULE.title : "蚂蚁影视";
    d.push({
        title: "搜索",
        col_type: "input",
        url: "'hiker://search?rule=" + rn + "&s='+input",
        extra: { defaultValue: "" }
    });
    d.push({ col_type: "line_blank" });
}


/* ================================================================
 * ================================================================
 * [详情] 详情页用函数 — 简介展开/收起
 * ================================================================
 * ================================================================
 * 调用方式：setDesc(d, '简介内容', 60);
 *
 * 参数说明：
 *   d    — 结果数组
 *   desc — 简介文本
 *   num  — 展开前显示多少字（默认60）
 *
 * 效果：
 *   简介超过 num 字时，只显示前 num 字 + "展开:" 按钮
 *   点击展开按钮显示完整简介，再点击收起
 *
 * 实现原理：
 *   用 storage0 存储展开/收起状态
 *   用 updateItem() 动态更新标题内容
 * ================================================================ */

function setDesc(d, desc, num) {
    if (!desc || !String(desc).trim()) return;
    num = num || 60;
    desc = String(desc).replace(/\s+/g, ' ').replace(/&nbsp;/g, ' ').trim();
    var head = '<b><font color="#098AC1">剧情简介\t</font></b>';
    var m = 'desc';
    var full = '　　' + desc;
    var sdc = desc.length > num ? '　　' + desc.substr(0, num) : full;
    var isLong = desc.length > num;

    var title = head;
    if (isLong) {
        var fn = '(function(dc,sdc,m,cs){'
            + 'var show=storage0.getItem(m,"0");'
            + 'var title=findItem(m).title;'
            + 'var re=/(<\\/small><br>.*?>).+/g;'
            + 'var exp="展开:";var ret="收起:";'
            + 'if(show=="1"){'
            + 'updateItem(m,{title:title.replace(ret,exp).replace(re,"$1"+sdc+"</small>").replace(/(<\\/small><br>\\<font color=").*?(">)/,"$1"+cs.hide+"$2")});'
            + 'storage0.setItem(m,"0");'
            + '}else{'
            + 'updateItem(m,{title:title.replace(exp,ret).replace(re,"$1"+dc+"</small>").replace(/(<\\/small><br>\\<font color=").*?(">)/,"$1"+cs.show+"$2")});'
            + 'storage0.setItem(m,"1");'
            + '}'
            + 'return "hiker://empty";})';
        var args = '(' + JSON.stringify(full) + ',' + JSON.stringify(sdc)
            + ',"' + m + '",{"show":"black","hide":"grey"})';
        var lazy = '#noLoading#@lazyRule=.js:' + fn + args;
        title += "<small><a style='text-decoration:none;' href='" + lazy + "'>展开:</a></small>";
    }
    title += "<br><small>" + sdc + "</small>";

    d.push({
        title: title,
        col_type: 'rich_text',
        extra: { id: m }
    });
}


/* ================================================================
 * ================================================================
 * [详情] 详情页用函数 — 快速搜索 + TVBOX推送
 * ================================================================
 * ================================================================
 * 调用方式：
 *   renderQuickSearch(d, {
 *       lists: allLinesEp,     // 必填：集数二维数组（TVBOX推送用）
 *       tabs: lineNames,       // 必填：线路名数组（TVBOX推送用）
 *       tTitle: tTitle,        // 必填：视频标题
 *       cover: cover,          // 必填：封面图URL
 *       intro: intro          // 选填：简介
 *   });
 *
 * 渲染4个图标按钮：
 *   1. 海阔搜索 — 用当前规则搜索影片名
 *   2. 云盘君.简 — 跳转到云盘君规则搜索（需安装该规则）
 *   3. 香情影视 — 跳转到香情影视规则搜索（需安装该规则）
 *   4. TVBOX推送 — 把选集数据推送到 TVBOX（通过 XYQ推送 页面）
 *
 * TVBOX推送数据格式：
 *   name  — 影片名
 *   pic   — 封面图
 *   content — 简介
 *   from  — 线路名（用 $$$ 分隔多条线路）
 *   url   — 选集数据（格式：集名$链接#集名$链接$$$线路2...）
 * ================================================================ */

function renderQuickSearch(d, opts) {
    opts = opts || {};
    var lists = opts.lists || [];
    var tabs = opts.tabs || [];
    var tTitle = opts.tTitle || '';
    var cover = opts.cover || '';
    var intro = opts.intro || '';

    d.push({ col_type: 'line' });

    try {
        var title = tTitle || getPageTitle();
        var Color = "#f13b66a";
        var Color1 = "#098AC1";
        function getHead(ttl) {
            return '‘‘’’<strong><font color="' + Color + '">' + ttl + '</front></strong>';
        }
    } catch (e) {}

    var rules = {
        "quickSearchConfigs": {
            "mode": "icon_round_small_4",
            "order": ["云盘君.简", "聚阅", "香情", "TVBOX推送"],
            /* !! 海阔搜索的 name 必须是 MY_RULE.title
             *     MY_RULE.title 是海阔内置变量，自动=当前规则名
             *     规则文件里不要自己定义 var MY_RULE = {...}，会覆盖它！ */
            "云盘君.简": {
                "name": "云盘君.简",
                "pic": "https://pic1.imgdb.cn/item/6346beda16f2c2beb1f1bbde.jpg",
            "rule": "copy://https://netcut.cn/p/f6fe3bec87025d5e"
        },
            "聚阅": {
                "name": "聚阅",
                "pic": "http://wenjian.xuruifeng.cn/tubiao/57.svg",
                "rule": "copy://https://netcut.cn/p/f6fe3bec87025d5e"
            },
            "香情": {
                "name": "香情影视",
                "pic": "http://wenjian.xuruifeng.cn/tubiao/24.svg"
            },
            "TVBOX推送": {
                "name": "推送",
                "pic": "http://wenjian.xuruifeng.cn/tubiao/%E5%9B%BE%E6%A0%87%281%29.svg"
            }
        }
    };

    var json = rules;
    var list = json.quickSearchConfigs.order;

    for (var l in list) {
        var obj = json.quickSearchConfigs[list[l]];

        if (list[l] === "TVBOX推送") {
            if (lists && lists.length > 0) {
                /* 构造TVBOX推送数据：集名$链接#集名$链接$$$线路2... */
                var playUrls = '';
                for (var i = 0; i < lists.length; i++) {
                    var listItem = lists[i];
                    for (var j = 0; j < listItem.length; j++) {
                        var epName = listItem[j].name || '';
                        var epUrl = listItem[j].url || '';
                        if (j == listItem.length - 1) {
                            playUrls += epName + "$" + epUrl + "$$$";
                        } else {
                            playUrls += epName + "$" + epUrl + "#";
                        }
                    }
                }
                if (playUrls.length > 3) playUrls = playUrls.substring(0, playUrls.length - 3);

                var pushData = JSON.stringify({
                    "name": title,
                    "pic": cover,
                    "content": intro,
                    "from": tabs.join('$$$'),
                    "url": playUrls.replace(/\&/g, '＆＆')
                });

                d.push({
                    title: list[l],
                    url: 'hiker://page/push?rule=XYQ推送&pushurl=' + encodeURIComponent(pushData),
                    pic_url: obj.pic,
                    col_type: json.quickSearchConfigs.mode,
                    extra: { id: 'qsearch' }
                });
            } else {
                d.push({
                    title: list[l],
                    url: "toast://当前页面没有可推送的播放列表",
                    pic_url: obj.pic,
                    col_type: json.quickSearchConfigs.mode,
                    extra: { id: 'qsearch' }
                });
            }
        } else {
            d.push({
                title: list[l],
                url: $('#noLoading#').lazyRule(function (obj, home, ttl) {
                    var ruleList = JSON.parse(request(home));
                    var hasRule = ruleList.some(function (item) { return item.title === obj.name; });
                    if (hasRule || obj.name == '') {
                        /* 本板块名对应已装规则时，若无独立搜索规则则以 toast 提示并停留本页（hiker://empty）兜底，
                         * 不强行跳转全局搜索（全局搜索页初始化请求可能被线路 RST）。 */
                        try {
                            toast('全局搜索暂不可用，请改用本规则首页搜索框');
                        } catch (e) {}
                        return 'hiker://empty';
                    } else {
                        if (obj.hasOwnProperty("rule")) {
                            if (obj.rule.indexOf('copy') != -1) {
                                toast("已经复制请导入规则");
                            }
                            return obj.rule;
                        } else {
                            return "toast://请安装" + obj.name + "小程序";
                        }
                    }
                }, obj, "hiker://home", title),
                pic_url: obj.pic,
                col_type: json.quickSearchConfigs.mode,
                extra: { id: 'qsearch' }
            });
        }
    }
    d.push({ col_type: 'line_blank' });
}


/* ================================================================
 * ================================================================
 * [详情] 详情页用函数 — 选集列表渲染
 * ================================================================
 * ================================================================
 * 调用方式：
 *   renderEpisodes(d, allLinesEp, lineNames, function(epItem) {
 *       return buildPlayUrl(epItem.url);   // 点击每集时调用
 *   });
 *
 * 参数说明：
 *   d          — 结果数组（push用）
 *   allLinesEp — 二维数组，每个线路一个集数列表
 *                格式: [[{name,url}, {name,url}, ...], ...]
 *   lineNames  — 线路名数组 ['线路1', '线路2', ...]
 *   buildUrlFn — 回调函数，传入每一集对象，返回播放地址
 *                不传则直接用 epItem.url
 *
 * 渲染内容：
 *   1. 线路切换按钮（多线路时显示，可点击切换）
 *   2. 正序/倒序按钮（点击切换集数排列顺序）
 *   3. 集数列表（自动选列数：2~5列）
 *
 * 全局变量：
 *   {prefix}_line — 当前选中线路索引（如 '0','1'）
 *   {prefix}_sort — 排序方式（'asc' 正序 / 'desc' 倒序）
 *
 * 列数自动选择逻辑：
 *   ≤8集 → 2列   ≤20集 → 3列   ≤50集 → 4列   >50集 → 5列
 * ================================================================ */

function renderEpisodes(d, allLinesEp, lineNames, buildUrlFn) {
    if (!allLinesEp || !allLinesEp.length) {
        d.push({ title: '暂无选集', url: 'javascript:;', col_type: 'text_3' });
        return;
    }

    var vp = _cfg.prefix;
    var curLineIdx = parseInt(getMyVar(vp + '_line', '0'), 10);
    var sortType = getMyVar(vp + '_sort', 'asc');
    if (curLineIdx < 0 || curLineIdx >= allLinesEp.length) curLineIdx = 0;

    /* ---- 线路切换按钮 ----
     * 多条线路时显示一排按钮，点击切换
     * 当前选中的线路名用红色高亮 */
    if (allLinesEp.length > 1) {
        for (var li2 = 0; li2 < allLinesEp.length; li2++) {
            var active = (li2 === curLineIdx);
            d.push({
                title: active ? "\u2018\u2018\u2019\u2019<b><font color=\"#FF5D50\">" + lineNames[li2] + "</font></b>" : lineNames[li2],
                col_type: 'scroll_button',
                url: $('#noLoading#').lazyRule(function (idx, key) {
                    putMyVar(key, String(idx));
                    refreshPage();
                    return 'hiker://empty';
                }, li2, vp + '_line'),
                extra: { backgroundColor: active ? '#20FA7298' : '', textSize: 14 }
            });
        }
        d.push({ col_type: 'blank_block', extra: { height: 8 } });
    }

    /* ---- 正序/倒序按钮 ----
     * 点击切换集数排列顺序 */
    d.push({
        title: "\u2018\u2018\u2019\u2019<b><font color=\"#4285F4\">" + (sortType === 'asc' ? '正序 ▲' : '倒序 ▼') + "</font></b>",
        col_type: 'scroll_button',
        url: $('#noLoading#').lazyRule(function (oldSort, key) {
            putMyVar(key, oldSort === 'asc' ? 'desc' : 'asc');
            refreshPage();
            return 'hiker://empty';
        }, sortType, vp + '_sort'),
        extra: { backgroundColor: '#EEEEEE', textSize: 14 }
    });
    d.push({ col_type: 'blank_block', extra: { height: 8 } });

    /* ---- 集数列表 ----
     * 深拷贝当前线路的集数，倒序时反转
     * 列数根据集数多少自动调整 */
    var nowEps = JSON.parse(JSON.stringify(allLinesEp[curLineIdx] || []));
    if (sortType === 'desc') nowEps.reverse();

    var ct = nowEps.length > 50 ? 'text_5' : nowEps.length > 20 ? 'text_4' : nowEps.length > 8 ? 'text_3' : 'text_2';
    for (var j = 0; j < nowEps.length; j++) {
        d.push({
            title: nowEps[j].name || '-',
            url: buildUrlFn ? buildUrlFn(nowEps[j]) : nowEps[j].url,
            col_type: ct
        });
    }
}


/* ================================================================
 * ================================================================
 * [网盘] 网盘资源用函数 — URL转换
 * ================================================================
 * ================================================================
 * 作用：把网盘链接转换成海阔对应网盘规则的页面URL
 *       这样点击网盘资源时直接在海阔内打开，不用跳浏览器
 *
 * 支持的网盘类型及转换规则：
 *   +-------------------------------------------------------------+
 *   | 原始链接              → 转换后的海阔规则URL                  |
 *   | ----------------------------------------------------------- |
 *   | 阿里网盘 (alipan)     → 云盘君.简规则                        |
 *   | 夸克/UC网盘 (quark)   → Quark.简规则                         |
 *   | 百度网盘 (baidu)      → 百度云盘规则                          |
 *   | 迅雷网盘 (xunlei)    → 迅雷规则                               |
 *   | 光鸭网盘 (guangya)    → 无对应规则，返回空                    |
 *   | 磁力链接 (magnet:)    → 原样返回（海阔自己处理）              |
 *   | goto跳转链接           → webRule等待跳转后转换                |
 *   +-------------------------------------------------------------+
 *
 * 调用方式：makeNetdiskUrl(url)
 * 返回：转换后的URL（不是网盘链接则原样返回）
 * ================================================================ */

function makeNetdiskUrl(url) {
    if (!url) return url;

    /* 网盘规则URL转换函数（内部用） */
    function getNetdiskRuleUrl(input) {
        if (!input) return '';
        /* 阿里网盘 → 云盘君.简 */
        if (/alipan|aliyundrive/.test(input)) {
            return 'hiker://page/aliyun?rule=云盘君.简&page=fypage&realurl=' + encodeURIComponent(input);
        }
        /* 夸克/UC网盘 → Quark.简 */
        if (/quark|ucpan|uc\./.test(input) && input.indexOf('pan') >= 0) {
            return 'hiker://page/quarkList?rule=Quark.简&realurl=' + input;
        }
        /* 百度网盘 → 百度云盘 */
        if (/baidu|pan\.baidu/.test(input)) {
            return 'hiker://page/fxlj?rule=百度云盘&page=fypage&realurl=' + input;
        }
        /* 迅雷网盘 → 迅雷 */
        if (/xunlei|pan\.xunlei/.test(input)) {
            return 'hiker://page/diaoyong?rule=迅雷&realurl=' + encodeURIComponent(input);
        }
        /* 光鸭网盘（无对应海阔规则，返回空） */
        if (/guangyapan|guangya/.test(input)) {
            return '';
        }
        return '';
    }

    /* 1. 直接网盘链接 → 转换 */
    var direct = getNetdiskRuleUrl(url);
    if (direct) return direct;

    /* 2. 磁力链接 → 原样返回（海阔自己处理） */
    if (url.indexOf('magnet:') === 0) {
        return url;
    }

    /* 3. goto?down= 跳转链接 → 用 webRule 等待跳转后转换
     *    有些站网盘链接是跳转链接，需要先跳转到真实网盘地址 */
    if (url.indexOf('goto') >= 0 && url.indexOf('down') >= 0) {
        var js = $.toString(function () {
            function getNetdiskRuleUrl(input) {
                if (!input) return '';
                if (/alipan|aliyundrive/.test(input)) {
                    return 'hiker://page/aliyun?rule=云盘君.简&page=fypage&realurl=' + encodeURIComponent(input);
                }
                if (/quark|ucpan|uc\./.test(input) && input.indexOf('pan') >= 0) {
                    return 'hiker://page/quarkList?rule=Quark.简&realurl=' + input;
                }
                if (/baidu|pan\.baidu/.test(input)) {
                    return 'hiker://page/fxlj?rule=百度云盘&page=fypage&realurl=' + input;
                }
                if (/xunlei|pan\.xunlei/.test(input)) {
                    return 'hiker://page/diaoyong?rule=迅雷&realurl=' + encodeURIComponent(input);
                }
                if (/guangyapan|guangya/.test(input)) {
                    return input;
                }
                return '';
            }
            if (window.count == null) window.count = 0;
            if (window.count >= 30) return 'toast://网盘跳转超时，请稍后重试';
            window.count++;
            var currentUrl = location.href;
            var netdiskUrl = getNetdiskRuleUrl(currentUrl);
            if (netdiskUrl) return netdiskUrl;
        });
        return 'webRule://' + url + '@' + js;
    }

    /* 4. 其他（光鸭网盘或未知）→ 原样返回，浏览器打开 */
    return url;
}


/* ================================================================
 * ================================================================
 * [网盘] 网盘资源用函数 — 资源渲染
 * ================================================================
 * ================================================================
 * 调用方式：
 *   renderPanResources(d, groupNames, allGroups);
 *
 * 参数说明：
 *   d          — 结果数组（push用）
 *   groupNames — 分组名数组，如 ['百度网盘', '磁力链接', '夸克网盘']
 *   allGroups  — 二维数组，每个分组对应一个资源列表
 *                资源格式：{ name: '资源名', url: '链接地址' }
 *
 * 渲染效果：
 *   +-----------------------------------------+
 *   | [网盘] 网盘 / 磁力资源                      |
 *   | [百度网盘(3)] [磁力链接(2)] [夸克(1)]   | ← tab切换
 *   |                                         |
 *   | 资源1  资源2  资源3                     | ← 当前分组资源列表
 *   +-----------------------------------------+
 *
 *   顶部tab左右滑动切换网盘类型
 *   点击资源时自动转换网盘URL（通过 makeNetdiskUrl）
 *
 * 全局变量：
 *   {prefix}_pan — 当前选中的网盘分组索引
 * ================================================================ */

function renderPanResources(d, groupNames, allGroups) {
    if (!allGroups || !allGroups.length) return;

    var vp = _cfg.prefix;
    var curIdx = parseInt(getMyVar(vp + '_pan', '0'), 10);
    if (curIdx < 0 || curIdx >= allGroups.length) curIdx = 0;

    /* 分组标题 */
    d.push({ col_type: 'line' });
    d.push({
        title: '[网盘] 网盘 / 磁力资源',
        url: 'hiker://empty',
        col_type: 'text_3'
    });

    /* 类型切换按钮（tab）— 多组资源时显示切换按钮 */
    if (allGroups.length > 1) {
        for (var gi = 0; gi < allGroups.length; gi++) {
            var active = (gi === curIdx);
            var count = allGroups[gi] ? allGroups[gi].length : 0;
            d.push({
                title: active ? "\u2018\u2018\u2019\u2019<b><font color=\"#FF5D50\">" + groupNames[gi] + "(" + count + ")</font></b>" : groupNames[gi] + "(" + count + ")",
                col_type: 'scroll_button',
                url: $('#noLoading#').lazyRule(function (idx, key) {
                    putMyVar(key, String(idx));
                    refreshPage();
                    return 'hiker://empty';
                }, gi, vp + '_pan'),
                extra: { backgroundColor: active ? '#20FA7298' : '', textSize: 14 }
            });
        }
        d.push({ col_type: 'blank_block', extra: { height: 8 } });
    }

    /* 资源列表 — URL自动转换：网盘链接转海阔规则URL */
    var nowList = allGroups[curIdx] || [];
    var ct = nowList.length > 10 ? 'text_2' : 'text_3';
    for (var k = 0; k < nowList.length; k++) {
        d.push({
            title: nowList[k].name || '-',
            url: makeNetdiskUrl(nowList[k].url) || 'hiker://empty',
            col_type: ct
        });
    }
}


/* ================================================================
 * ================================================================
 * [首页] 首页用函数 — 分类按钮
 * ================================================================
 * ================================================================
 * 调用方式：renderCatButtons(d, SITE.cats);
 *
 * cats 格式：[{ t: '电影', s: '1' }, { t: '剧集', s: '2' }, ...]
 *   t — 分类显示名
 *   s — 分类ID（用于URL构建）
 *
 * 渲染一排可横向滑动的按钮，点击进入对应分类
 * 每个按钮随机背景色
 *
 * 全局变量：
 *   {prefix}_cls — 当前选中的分类ID（空=首页模式）
 * ================================================================ */

function renderCatButtons(d, cats) {
    if (!cats || !cats.length) return;
    var vk = _cfg.prefix + '_cls';
    var fk = _filterKey();
    for (var ci = 0; ci < cats.length; ci++) {
        d.push({
            title: cats[ci].t,
            col_type: 'scroll_button',
            url: $('#noLoading##noRecordHistory#').lazyRule(function (s, key, fk) {
                putMyVar(key, s);
                clearVar(fk);
                refreshPage(true);
                return 'hiker://empty';
            }, cats[ci].s, vk, fk),
            extra: { backgroundColor: getRangeColors() }
        });
    }
    d.push({ col_type: 'line_blank' });
}


/* ================================================================
 * ================================================================
 * [首页] 首页用函数 — 分类页导航栏
 * ================================================================
 * ================================================================
 * 调用方式：
 *   renderNavBar(d, SITE.cats, cls, SITE.getMainCat, { homeBtn: true });
 *
 * 参数说明：
 *   d            — 结果数组
 *   cats         — 分类数组 [{ t, s }, ...]
 *   cls          — 当前选中的分类ID
 *   getMainCatFn — 子分类→大分类映射函数（用于导航栏高亮）
 *   opts.homeBtn — true 表示最前面显示"首页"按钮
 *
 * 和 renderCatButtons 的区别：
 *   renderCatButtons → 首页用，无高亮
 *   renderNavBar     → 分类页用，当前分类高亮显示
 * ================================================================ */

function renderNavBar(d, cats, cls, getMainCatFn, opts) {
    if (!cats || !cats.length) return;
    opts = opts || {};
    var vk = _cfg.prefix + '_cls';
    var fk = _filterKey();
    var mainCls = getMainCatFn ? getMainCatFn(cls) : cls;

    /* 首页按钮（可选） */
    if (opts.homeBtn) {
        d.push({
            title: '[首页]首页',
            col_type: 'scroll_button',
            url: $('#noLoading##noRecordHistory#').lazyRule(function (key, fk) {
                putMyVar(key, '');
                clearVar(fk);
                refreshPage(true);
                return 'hiker://empty';
            }, vk, fk),
            extra: { backgroundColor: getRangeColors() }
        });
    }

    for (var i = 0; i < cats.length; i++) {
        var c = cats[i];
        var active = (mainCls === c.s);
        d.push({
            title: active ? '\u2018\u2018\u2019\u2019<b><font color="#FF5D50">' + c.t + '</font></b>' : c.t,
            col_type: 'scroll_button',
            url: $('#noLoading##noRecordHistory#').lazyRule(function (s, key, fk) {
                putMyVar(key, s);
                clearVar(fk);
                refreshPage(true);
                return 'hiker://empty';
            }, c.s, vk, fk),
            extra: {
                backgroundColor: active ? '#20FA7298' : getRangeColors()
            }
        });
    }
    d.push({ col_type: 'line_blank' });
}


/* ================================================================
 * ================================================================
 * [分类] 分类页用函数 — 动态筛选栏
 * ================================================================
 * ================================================================
 * 调用方式：
 *   renderDynamicFilter(d, {
 *       filterDims: filterDims,  // 筛选维度数组（从分类页HTML解析）
 *       cls: cls                  // 当前大分类ID
 *   });
 *
 * filterDims 格式：
 *   [
 *     { label: '排序', key: 'sort', options: [{name:'按时间',value:'time'},...] },
 *     { label: '类型', key: 'type', options: [...], isSub: true },
 *     { label: '地区', key: 'area', options: [...] },
 *     ...
 *   ]
 *
 *   isSub=true 表示子分类维度（切换大分类用，不是普通筛选）
 *
 * 功能：
 *   1. 多于1个维度时显示展开/折叠按钮
 *   2. 折叠时只显示第1行维度，展开后显示全部
 *   3. 当前选中项高亮
 *   4. 点击选项后更新筛选状态并刷新页面
 *
 * 全局变量：
 *   {prefix}filter — 筛选状态JSON（存 area/sort/year 等）
 *   MY_RULE.group  — 折叠状态（'0'折叠 / '1'展开）
 * ================================================================ */

function renderDynamicFilter(d, opts) {
    if (!opts || !opts.filterDims || !opts.filterDims.length) return;

    var s = [];
    var foldGroup = MY_RULE.group;
    var fold = getVar(foldGroup, "0");
    var fk = _filterKey();
    var vk = _cfg.prefix + '_cls';
    var filterState = JSON.parse(getVar(fk, JSON.stringify({ area: '', sort: '', year: '' })));
    var dimCount = opts.filterDims.length;

    /* 折叠/展开按钮（多于1个维度才显示） */
    if (dimCount > 1) {
        s.push({
            title: fold === '1' ? '› 收起' : '‹ 展开',
            url: $('#noLoading#').lazyRule(function (fold, group) {
                putVar(group, fold === '1' ? '0' : '1');
                refreshPage(false);
                return "hiker://empty";
            }, fold, foldGroup),
            col_type: 'scroll_button'
        });
    }

    /* 遍历筛选维度 */
    for (var fi = 0; fi < opts.filterDims.length; fi++) {
        var dim = opts.filterDims[fi];
        if (fold !== '1' && fi > 0) break;

        for (var oi = 0; oi < dim.options.length; oi++) {
            var opt = dim.options[oi];
            var isActive;

            if (dim.isSub) {
                isActive = (opts.cls === opt.value);
            } else {
                isActive = (filterState[dim.key] === opt.value);
            }

            var displayTitle = opt.name;

            if (fold === '1' && fi > 0) {
                displayTitle = '\u2018\u2018\u2019\u2019' + opt.name.small();
                if (isActive) displayTitle = '\u2018\u2018\u2019\u2019<b>' + opt.name.fontcolor("#ffffff").small() + '</b>';
            } else {
                if (isActive) displayTitle = '\u2018\u2018\u2019\u2019' + opt.name.fontcolor("#ffffff").bold();
            }

            if (dim.isSub) {
                /* 子分类：切换 cls，清除筛选 */
                s.push({
                    title: displayTitle,
                    url: $('#noLoading##noRecordHistory#').lazyRule(function (subVal, key, fk) {
                        putMyVar(key, subVal);
                        clearVar(fk);
                        refreshPage(true);
                        return 'hiker://empty';
                    }, opt.value, vk, fk),
                    col_type: 'scroll_button',
                    extra: { backgroundColor: isActive ? getRangeColors() : '' }
                });
            } else {
                /* 普通筛选：修改 filterState */
                s.push({
                    title: displayTitle,
                    url: $('#noLoading#').lazyRule(function (params) {
                        var state = JSON.parse(getVar(params.fk, '{}'));
                        state[params.key] = params.value;
                        putVar(params.fk, JSON.stringify(state));
                        refreshPage(true);
                        return "hiker://empty";
                    }, { fk: fk, key: dim.key, value: opt.value }),
                    col_type: 'scroll_button',
                    extra: { backgroundColor: isActive ? getRangeColors() : '' }
                });
            }
        }
        s.push({ col_type: "blank_block" });
    }

    setPreResult(s);
}

/* ----------------------------------------------------------------
 * getFilterState() — 获取当前筛选状态
 * ----------------------------------------------------------------
 * 返回JSON对象，如 { area: '日本', sort: 'time', year: '2026' }
 * ============================================================= */
function getFilterState() {
    return JSON.parse(getVar(_filterKey(), '{}'));
}


/* ================================================================
 * ================================================================
 * [首页] 首页用函数 — 板块标题 + 板块内容
 * ================================================================
 * ================================================================
 * 调用方式：
 *   renderSectionTitle(d, '最新电影', iconUrl, '1');
 *   renderSectionItems(d, items, 9, 'movie_3');
 *
 * renderSectionTitle 参数：
 *   d       — 结果数组
 *   title   — 板块标题文字（如"电影推荐"）
 *   iconUrl — 图标URL（可以是emoji或图片地址）
 *   catId   — 板块对应分类ID，点击标题跳转到分类页
 *             传空字符串则不可点击
 *
 * renderSectionItems 参数：
 *   d        — 结果数组
 *   items    — 视频卡片数组（parseList 返回的格式）
 *   maxItems — 最多显示几个
 *   colType  — 卡片排版类型（movie_2/movie_3 等）
 * ================================================================ */

function renderSectionTitle(d, secTitle, iconUrl, catId) {
    var vk = _cfg.prefix + '_cls';
    var fk = _filterKey();
    var clickUrl = catId
        ? $('#noLoading##noRecordHistory#').lazyRule(function (s, key, fk) {
            putMyVar(key, s);
            clearVar(fk);
            refreshPage(true);
            return 'hiker://empty';
        }, catId, vk, fk)
        : 'javascript:;';
    d.push({
        title: '\u258d'.fontcolor(getRangeColors()) + '<b>' + secTitle + '</b>'.fontcolor("Black"),
        pic_url: iconUrl,
        url: clickUrl,
        col_type: "text_icon"
    });
}

function renderSectionItems(d, items, maxItems, colType) {
    if (!items || !items.length) return;
    for (var j = 0; j < items.length && j < maxItems; j++) {
        d.push(items[j]);
    }
    d.push({ col_type: "line_blank" });
}


