/* ================================================================
 * ================================================================
 * 站点配置  (config/tpl_1_config.js)
 * ================================================================
 * ================================================================
 *
 * +------------------------------------------------------------------+
 * |  文件说明                                                        |
 * |  ---------                                                       |
 * |  这是规则模板系统的【第2层】，定义目标网站的所有配置信息。       |
 * |                                                                  |
 * |  修改级别：[可改] 全部可以修改（换站必改这里）                       |
 * |  换站时只需要改这个文件 + 解析器里的CSS选择器。                   |
 * |                                                                  |
 * |  架构层级：                                                      |
 * |    第1层（最底层）：hiker_lib.js    共享库（[禁改] 禁止修改）        |
 * |    第2层：          tpl_1_config.js ← 你在这里（[可改] 可以修改）   |
 * |    第3层：          tpl_2/3/4.js     解析器（[可改] 选择器可改）     |
 * |    第4层（最顶层）：hiker_template_unified.js  风格模板          |
 * |                                                                  |
 * |  ══════════════════════════════════════════════════════════      |
 * |  【修改指南 — 教你区分可改 vs 不可改】                           |
 * |  ══════════════════════════════════════════════════════════      |
 * |                                                                  |
 * |  [可改] 可以修改的内容：                                              |
 * |    - host, prefix, name → 改成目标站的信息                      |
 * |    - cats 数组 → 改成目标站的分类                                |
 * |    - secIcons, secClsMap → 改成目标站的板块图标和映射           |
 * |    - buildCatUrl 函数体 → 改成目标站的URL格式                   |
 * |    - parseFilterOptions 函数体 → 改成目标站筛选栏结构           |
 * |    - getMainCat 函数体 → 改成目标站的映射逻辑                   |
 * |    - getSearchUrl 函数体 → 改成目标站的搜索URL格式             |
 * |                                                                  |
 * |  [禁改] 禁止修改的内容：                                              |
 * |    - var SITE → 变量名不能改（其他文件都叫 SITE）               |
 * |    - 函数名 buildCatUrl / parseFilterOptions / getMainCat /      |
 * |      getSearchUrl → 函数名不能改（其他文件按名调用）             |
 * |    - 函数的参数个数和顺序 → 不能改（调用方按固定参数传）         |
 * |    - buildCatUrl 的参数 (cls, filter, page)                     |
 * |    - parseFilterOptions 的参数 (html, cls)                        |
 * |    - getMainCat 的参数 (title)                                   |
 * |    - getSearchUrl 的参数 (keyword)                               |
 * |                                                                  |
 * |  [可改] 适配新站步骤：                                                |
 * |    1. 改 host 为目标站域名                                       |
 * |    2. 改 prefix 为唯一的2字母前缀                                |
 * |    3. 改 cats 为目标站分类列表                                   |
 * |    4. 改 buildCatUrl 函数体为目标站URL格式                       |
 * |    5. 改 getSearchUrl 函数体为目标站搜索URL                      |
 * |    6. 改 parseFilterOptions 函数体匹配目标站HTML                 |
 * |    7. 更新 tpl_2/3/4.js 中的CSS选择器                             |
 * |                                                                  |
 * |  [可改] 完整适配示例 — 假设适配 example.com：                        |
 * |    host: 'https://www.example.com',                              |
 * |    prefix: 'ex',    // 每个站不同前缀，避免缓存/变量冲突         |
 * |    name: '示例网',                                                |
 * |    cats: [                                                       |
 * |      { t: '电影', s: 'movie' },   // s值=URL里的分类标识         |
 * |      { t: '电视剧', s: 'tv' },                                  |
 * |    ],                                                           |
 * |    // buildCatUrl 改成目标站的URL格式：                          |
 * |    buildCatUrl: function(cls, filter, page) {                    |
 * |      var url = this.host + '/list/' + cls;                      |
 * |      if (filter && filter.area) url += '?area=' + filter.area;  |
 * |      if (page > 1) url += '&page=' + page;                      |
 * |      return url;                                                 |
 * |    },                                                            |
 * |    // getSearchUrl 改成目标站搜索URL：                           |
 * |    getSearchUrl: function(keyword) {                             |
 * |      return this.host + '/search?q=' + keyword;                  |
 * |    },                                                            |
 * +------------------------------------------------------------------+
 * ================================================================ */

var SITE = {

    /* ============================================================
     * [可改] 基础配置（换站必改）
     * ============================================================
     *
     * host   — 站点完整域名（不要加结尾/）
     *          [可改] 示例：'https://www.pkavi.com'
     *          [可改] 示例：'https://m.mihdr.top'
     *          ❌ 错误：'https://www.pkavi.com/'  （结尾多了/）
     *
     * prefix — 变量前缀，每个站用不同前缀避免变量和缓存冲突
     *          [可改] 示例：'pk'  （七味网）
     *          [可改] 示例：'mh'  （mihdr）
     *          [可改] 示例：'ex'  （example站）
     *          !! 要求：2~3个字母，全小写，每个站唯一
     *          !! 改了 prefix 后，旧缓存不会自动清除（key不同了）
     *
     * name   — 站点中文名，用于界面显示和 toast 提示
     *          [可改] 示例：'七味网'
     *          [可改] 示例：'蜜蜂影视'
     * ======================================================== */
    host: 'https://www.91mayitv.com',
    prefix: 'my',
    name: '蚂蚁影视',

    /* ============================================================
     * [可改] 大分类列表（换站必改）
     * ============================================================
     *
     * 对应网站导航栏的分类
     * t = 显示名（界面按钮上显示的文字）
     * s = 分类ID（用于构建分类页URL，是 buildCatUrl 的第1个参数）
     *
     * [可改] pkavi.com 分类对应关系：
     *    电影 → /ms/1-...    剧集 → /ms/2-...
     *    综艺 → /ms/3-...    动漫 → /ms/4-...
     *    短剧 → /ms/30-...
     *
     * [可改] 其他站示例：
     *    cats: [
     *      { t: '电影', s: 'movie' },
     *      { t: '电视剧', s: 'tvshow' },
     *      { t: '综艺', s: 'variety' },
     *    ]
     *
     * !! s 的值要和 buildCatUrl 里用到的分类ID一致
     * ======================================================== */
    cats: [
        { t: '电影',   s: '1'  },
         { t: '连续剧', s: '2'  },
         { t: '综艺',   s: '3'  },
         { t: '动漫',   s: '4'  }
     ],

    /* ============================================================
     * [可改] 首页各板块图标（可改，不改也能用）
     * ============================================================
     *
     * 板块标题 → 图标的映射
     * 用 emoji 作为图标，也可以换成图片URL
     *
     * [可改] 用 emoji：'M'
     * [可改] 用图片：'https://xxx.com/icon.png'
     * [可改] 不想要图标：留空字符串 ''
     *
     * !! key 必须和首页板块标题完全匹配
     *    （板块标题是 parseSections 从 HTML 的 h2 标签提取的）
     * ======================================================== */
    secIcons: {
        '电影': 'MV',
        '连续剧': 'T',
        '综艺': 'Z',
        '动漫': 'A',
        '热播榜': 'HOT'
    },

    /* ============================================================
     * [可改] 板块标题 → 分类ID 映射（换站必改）
     * ============================================================
     *
     * 首页板块标题点"更多"时，跳转到对应分类页
     * key   = 板块标题（和 parseSections 提取的标题一致）
     * value = 分类ID（和 cats 里的 s 对应）
     *
     * [可改] 示例：
     *    '电影推荐': '1'  → 点"电影推荐"更多 → 进入电影分类
     *
     * !! 如果板块名和分类名不一致，这里必须手动映射
     * ======================================================== */
    secClsMap: {
        '电影': '1',
        '连续剧': '2',
        '综艺': '3',
        '动漫': '4'
    },

    /* ============================================================
     * [可改] 分类页URL构建函数（换站必改函数体，不改函数名和参数）
     * ============================================================
     *
     * [禁改] 禁止修改：函数名 buildCatUrl、参数 (cls, filter, page)
     * [可改] 可以修改：函数体内部的URL拼接逻辑
     *
     * 参数说明：
     *   cls    — 分类ID（cats 数组里的 s 值，如 '1'）
     *   filter — 筛选条件对象，可能包含：
     *            { area: '日本', year: '2026', class: '剧情', lang: '日语' }
     *            没有筛选时为 null
     *   page   — 页码（1开始），第1页通常不需要特殊处理
     *
     * 返回：完整的分类页URL字符串
     *
     * ═════════════════════════════════════════════════════════
     * pkavi.com 的URL格式：
     *   /ms/{cls}-{area}-{year}-{class}-{lang}-------{page}.html
     *   共12段（cls + 11段），用 - 分隔
     *   第1段 = cls（分类ID）
     *   第2段 = area（地区）
     *   第3段 = year（年份）
     *   第4段 = class（类型/剧情）
     *   第5段 = lang（语言）
     *   第6~11段 = 空（网站预留字段）
     *   第12段 = page（分页号，第1页为空）
     *
     *   示例：
     *   全部第1页 → /ms/1-----------.html
     *   类型=剧情  → /ms/1---剧情---------.html
     *   第2页     → /ms/1-----------2.html
     * ═════════════════════════════════════════════════════════
     *
     * [可改] 其他站的 buildCatUrl 示例：
     *
     *   // 简单的 ?page= 格式
     *   buildCatUrl: function(cls, filter, page) {
     *      var url = this.host + '/list/' + cls;
     *      if (filter && filter.area) url += '/' + filter.area;
     *      if (page > 1) url += '?page=' + page;
     *      return url;
     *   }
     *
     *   // 路径参数格式
     *   buildCatUrl: function(cls, filter, page) {
     *      var url = this.host + '/category/' + cls;
     *      if (filter && filter.year) url += '/year/' + filter.year;
     *      url += '/page/' + (page || 1);
     *      return url;
     *   }
     * ======================================================== */
    buildCatUrl: function (cls, filter, page) {
        /* 独播库 12 段 URL：/vodshow/{cls}-{area}-{sort}-{class}-{lang}-{letter}---{page}---{year}.html
         * 段位（含 cls 共 12 段，索引 0..11）：
         *   0=cls  1=area  2=sort  3=class(剧情)  4=lang  5=letter
         *   6,7 空  8=page  9,10 空  11=year
         * 实测依据：
         *   第1页 /vodshow/2-----------.html
         *   第2页 /vodshow/2--------2---.html      ← 分页在段8
         *   地区   /vodshow/2-大陆----------.html  ← 段1
         *   排序   /vodshow/2--人气---------.html  ← 段2
         *   剧情   /vodshow/2---悬疑--------.html  ← 段3
         *   语言   /vodshow/2----国语-------.html  ← 段4
         *   字母   /vodshow/2-----A------.html     ← 段5
         *   年份   /vodshow/2-----------2026.html  ← 段11 */
        var parts = ['', '', '', '', '', '', '', '', '', '', ''];
        var enc = function (v) {
            if (!v) return '';
            return (String(v).indexOf('%') >= 0) ? String(v) : encodeURIComponent(v);
        };
        if (filter) {
            if (filter.area)   parts[0] = enc(filter.area);
            if (filter.sort)   parts[1] = enc(filter.sort);
            if (filter.class)  parts[2] = enc(filter.class);
            if (filter.lang)   parts[3] = enc(filter.lang);
            if (filter.letter) parts[4] = enc(filter.letter);
            if (filter.year)   parts[10] = enc(filter.year);
        }
        if (page > 1) parts[7] = String(page);
        return this.host + '/vodshow/' + cls + '-' + parts.join('-') + '.html';
    },

    /* ============================================================
     * [可改] 筛选选项解析（换站必改函数体，不改函数名和参数）
     * ============================================================
     *
     * [禁改] 禁止修改：函数名 parseFilterOptions、参数 (html, cls)
