     *
     *   t  — 选项文字（界面按钮显示）
     *   s  — 选项链接（点击后跳转的URL，相对路径即可）
     *   on — 是否当前选中（true=高亮）
     *
     * ═════════════════════════════════════════════════════════
     * pkavi.com 筛选栏HTML结构：
     *   <div class="list-box">
     *     <dl>
     *       <dt>类型</dt>
     *       <dd><a href="...">全部</a><a class="current" href="...">剧情</a>...</dd>
     *     </dl>
     *     <dl>...</dl>
     *   </div>
     * ═════════════════════════════════════════════════════════
     *
     * [可改] 其他站的 parseFilterOptions 示例：
     *
     *   // 如果目标站筛选栏是 div 标签格式
     *   parseFilterOptions: function(html, cls) {
     *      var dims = [];
     *      var groups = pdfa(html, '.filter-group');
     *      for (var i = 0; i < groups.length; i++) {
     *          var title = pdfh(groups[i], '.filter-title&&Text');
     *          var opts = [];
     *          var links = pdfa(groups[i], 'a');
     *          for (var j = 0; j < links.length; j++) {
     *              opts.push({
     *                  t: pdfh(links[j], 'a&&Text'),
     *                  s: pdfh(links[j], 'a&&href'),
     *                  on: /active/.test(pdfh(links[j], 'a&&class') || '')
     *              });
     *          }
     *          dims.push({ title: title, options: opts });
     *      }
     *      return dims;
     *   }
     * ======================================================== */
    parseFilterOptions: function (html, cls) {
        /* 蚂蚁影视筛选栏（stui 模板）：
         *   <ul class="stui-screen__list type-slide ... clearfix">
         *     <li><span class="text-muted">按分类</span></li>          ← 组名：li 内只有 span，无 a
         *     <li class="active"><a href="/vodshow/1-----------.html">全部</a></li>  ← 选中态在父 li
         *     <li><a class="text-muted" href="/vodshow/1---%E5%96%9C%E5%89%A7...">喜剧</a></li>
         *   </ul>
         * 5 组：按分类 / 按地区 / 按语言 / 按年份 / 按字母
         * !! 与独播库差异：组名在无 a 的 li 里取 span 文本；选中态 a 无 class，须看父 li 是否 active */
        var dims = [];
        var groups = pdfa(html, 'body&&ul.stui-screen__list');
        if (!groups || groups.length === 0) {
            groups = pdfa(html, 'body&&.stui-screen__list');
        }
        if (!groups || groups.length === 0) return dims;
        for (var i = 0; i < groups.length; i++) {
            var g = groups[i];
            var lis = pdfa(g, 'body&&li');
            if (!lis || lis.length === 0) continue;
            var dimTitle = '';
            var opts = [];
            for (var j = 0; j < lis.length; j++) {
                var liClass = pdfh(lis[j], 'li&&class') || '';
                var href = pdfh(lis[j], 'a&&href') || '';
                var text = pdfh(lis[j], 'a&&Text') || '';
                text = text.replace(/\s+/g, ' ').trim();
                if (href && text) {
                    opts.push({
                        t: text,
                        s: href,
                        on: /(^|\s)active(\s|$)/.test(liClass)
                    });
                } else if (!href && !text) {
                    /* 组名 li：无 a，取内层 span 文本（如"按分类"） */
                    var spanTxt = (pdfh(lis[j], 'span&&Text') || '').replace(/\s+/g, ' ').trim();
                    if (spanTxt && !dimTitle) dimTitle = spanTxt;
                }
            }
            if (opts.length > 0) {
                /* 组名"按分类"→"分类"，去掉"按"前缀；无组名则用序号兜底 */
                var label = dimTitle ? dimTitle.replace(/^按/, '') : ('筛选' + (i + 1));
                dims.push({ title: label, options: opts });
            }
        }
        return dims;
    },

