/* ================================================================
 * parseList(html) — 从HTML提取视频卡片列表
 * ----------------------------------------------------------------
 * [禁改] 禁止修改：函数名 parseList、参数 (html)、返回值字段名
 * [可改] 可以修改：函数体内的 CSS 选择器
 *
 * 参数：html — 包含视频列表的HTML字符串
 * 返回：视频卡片数组 [{ title, desc, pic_url, url, col_type }, ...]
 *
 * 解析逻辑：
 *   1. 先用 ul.pic-list&&li 选择器找视频列表
 *   2. 找不到则备用方案：直接找所有 li
 *   3. 遍历每个 li，提取标题、链接、封面、画质、评分、描述
 *   4. 只保留包含 /mv/ 的链接（过滤非视频卡片）
 *
 * pdfa/pdfh 是海阔内置的HTML解析函数：
 *   pdfa(html, '选择器') — 返回匹配的元素数组
 *   pdfh(html, '选择器') — 返回第一个匹配的元素内容
 *   选择器格式：'父元素&&子元素&&属性'
 *
 * [可改] 选择器修改示例：
 *   'ul.pic-list&&li'      → 列表容器+每个卡片
 *   'a&&title'             → 卡片标题（取a标签的title属性）
 *   'a&&href'              → 卡片链接（取a标签的href属性）
 *   'img&&src'             → 封面图（取img标签的src属性）
 *   '.s1&&Text'            → 画质标签（取class=s1的文本）
 *   '.s2&&Text'            → 评分（取class=s2的文本）
 *   'p&&Text'              → 描述行（取p标签的文本）
 * ================================================================ */
function parseList(html) {
    var items = [];

    /* [可改] 可以修改：列表选择器
     * 先尝试 ul.pic-list&&li，找不到则找所有 li
     * [可改] 换站时改成目标站的列表选择器 */
    /* [可改] 列表选择器（蚂蚁影视 · stui 模板）
     * 分类页/首页板块：<ul class="stui-vodlist clearfix"><li><div class="stui-vodlist__box">
     * 搜索页/侧栏：<ul class="stui-vodlist__media"><li><div class="thumb"><a class="m-thumb">
     * 两者结构不同，做双分支；否则搜索出结果但列表为空 */
    var list = pdfa(html, 'body&&ul.stui-vodlist&&li');
    if (!list || list.length === 0) {
        list = pdfa(html, 'body&&ul.stui-vodlist__media&&li');
    }
    if (!list || list.length === 0) {
        list = pdfa(html, 'body&&.stui-vodlist__box');
    }

    for (var i = 0; i < list.length; i++) {
        try {
            var item = list[i];

            /* [可改] 可以修改：字段提取选择器
             * 每个字段都有备用方案（用 || 连接），
             * 确保某个选择器找不到时不影响其他字段 */

            /* 标题：分类页/搜索页卡片 a 都带 title 属性，其次 h4 内 a 文本 */
            var title = pdfh(item, 'a&&title') || pdfh(item, 'h4&&a&&Text') || pdfh(item, 'h4&&Text') || '';

            /* 链接：a 标签的 href 属性 */
            var link  = pdfh(item, 'a&&href') || '';

            /* 封面：独播库封面 data-original 挂在 a.myui-vodlist__thumb 上，不在 img 上
             * 顺序：a 的 data-original → img 的 data-original → img 的 src */
            var pic   = pdfh(item, 'a&&data-original') || pdfh(item, 'img&&data-original') || pdfh(item, 'img&&src') || '';

            /* 画质/更新状态：span.pic-text，如 "更新至8集" "全47集" "正片" */
            var quality = pdfh(item, '.pic-text&&Text') || '';

            /* 评分：span.tag，如 "8.3分" "6分" */
            var rating = pdfh(item, '.tag&&Text') || '';

            /* 描述行：
             *   分类/首页板块 → p.text（演员列表）
             *   搜索页卡片   → .detail 里含 导演/主演/类型/地区/年份，需按字段边界拆
             * 拆分用带前瞻的正则，避免 类型 吞掉 地区、地区 吞掉 年份 */
            var descText = pdfh(item, 'p.text&&Text') || '';
            if (!descText) {
                var detailTxt = String(pdfh(item, '.detail&&Text') || '')
                    .replace(/&nbsp;/g, ' ')
                    .replace(/\s+/g, ' ')
                    .trim();
                if (detailTxt) {
                    var mStar = detailTxt.match(/主演：([^类]*?)(?=\s*类型：|$)/);
                    var mType = detailTxt.match(/类型：([^地]*?)(?=\s*地区：|$)/);
                    var mArea = detailTxt.match(/地区：([^年]*?)(?=\s*年份：|$)/);
                    var mYear = detailTxt.match(/年份：(\d{4})/);
                    var parts = [];
                    if (mStar && mStar[1]) parts.push('主演：' + mStar[1].trim());
                    if (mType && mType[1]) parts.push('类型：' + mType[1].trim());
                    if (mArea && mArea[1]) parts.push('地区：' + mArea[1].trim());
                    if (mYear && mYear[1]) parts.push(mYear[1]);
                    descText = parts.join(' / ');
                }
            }
            if (!descText) descText = pdfh(item, 'p&&Text') || '';

            /* [禁改] 禁止删除：过滤逻辑
             * 没有标题或链接的跳过 */
            if (!title || !link) continue;
            /* [禁改] 禁止删除：只保留详情页链接
             * [可改] 独播库详情页路径：/voddetail/{id}.html
             * 注意不能用 '/vod'，因为 /vodplay/ /vodsearch/ 也含 vod */
            if (link.indexOf('/voddetail/') < 0) continue;

            /* 清理空白字符 */
            title = title.replace(/\s+/g, ' ').trim();
            rating = rating.replace(/\s+/g, ' ').trim();
            quality = quality.replace(/\s+/g, ' ').trim();

            /* 组合描述：画质 + 评分 + 描述行 */
            var desc = '';
            if (quality) desc += quality;
            if (rating && rating !== 'N/A') desc += '  ' + rating;
            if (descText) desc += '\n' + descText;

            items.push({
                title: title,
                desc: desc,
                /* [禁改] 禁止删除：@Referer 防盗链处理
                 * 网站图片有防盗链，不加 Referer 会显示裂图 */
                pic_url: pic + '@Referer=' + SITE.host + '/',
                /* [禁改] 禁止删除：#immersiveTheme# 后缀
                 * 海阔沉浸式主题依赖这个标记 */
                url: _full(link) + '#immersiveTheme#',
                /* [可改] 可以修改：卡片排版类型
                 * [可改] 可选值：movie_2（2列大图）/ movie_3（3列中图）
                 * [可改] movie_2 适合手机竖屏，movie_3 适合平板 */
                col_type: 'movie_2'
            });
        } catch (e) { continue; }
    }
    return items;
}


/* ================================================================
 * parseSections(html) — 从首页HTML提取板块列表
 * ----------------------------------------------------------------
 * [禁改] 禁止修改：函数名 parseSections、参数 (html)、返回值结构
 * [可改] 可以修改：函数体内的正则表达式和选择器
 *
 * 参数：html — 首页完整HTML
 * 返回：板块数组 [{ title, catId, items }, ...]
 *
 * pkavi.com 首页HTML结构：
 *   <h2 class="index-h2">电影推荐<span>...换一换...</span></h2>
 *   <div class="indexShowBox">
 *   <ul class="pic-list pic-list-nth clearfix" id="change-ul-X">
 *     <li>...</li>
 *     <li>...</li>
 *   </ul>
 *   </div>
 *
 * 解析逻辑：
 *   1. 用正则找到所有 h2.index-h2 标题
 *   2. 只保留"XX推荐"格式的板块
 *   3. 从 h2 位置向后找最近的 ul.pic-list
 *   4. 截取整个 ul 元素HTML，调用 parseList() 解析视频卡片
 *
 * [可改] 换站时需要修改：
 *   - h2Regex 正则：匹配目标站的板块标题标签
 *   - '推荐' 关键词过滤：改成目标站板块标题的关键词
 *   - '<ul class="pic-list' 列表选择器
 *
 * [可改] 其他站示例：
 *   如果目标站板块标题是 <h3 class="section-title">最新电影</h3>
 *   则正则改为：/<h3[^>]*class="[^"]*section-title[^"]*"[^>]*>([^<]*)/g
 *   过滤关键词改为：if (h2Text.indexOf('最新') < 0) continue;
 *   列表选择器改为：var ulStart = afterH2.indexOf('<div class="video-list');
 * ================================================================ */
function parseSections(html) {
    var sections = [];

    /* [可改] 板块标题（蚂蚁影视 · stui 模板）
     * 首页结构（两栏交错）：
     *   <h3 class="title"><img src="...icon_1.png"/><a href="/vodshow/1-----------.html">电影</a></h3>
     *   <div class="stui-pannel_bd clearfix"><ul class="stui-vodlist clearfix">主板块卡片</ul></div>
     *   <h3 class="title"><img src="...icon_12.png"/>热播榜</h3>
     *   <div class="stui-pannel_bd"><ul class="stui-vodlist__media ...">侧栏卡片</ul></div>
     * !! h3 内部可能含 <img>/<a>，标题文本须剥掉标签再取。
     * !! 板块与列表按 DOM 顺序配对：在 h3 结束 ~ 下一个 h3 之间找第一个 stui-vodlist 列表 */
    var h3Re = /<h3[^>]*class="title"[^>]*>[\s\S]*?<\/h3>/g;
    var h3s = [];
    var m;
    while ((m = h3Re.exec(html)) !== null) {
        h3s.push({ start: m.index, end: m.index + m[0].length, raw: m[0] });
    }
    for (var si = 0; si < h3s.length; si++) {
        /* 剥掉 <img>/<a> 等标签，取纯文本标题（"电影"/"热播榜"/"友情链接"） */
        var inner = h3s[si].raw.replace(/<h3[^>]*>/, '').replace(/<\/h3>\s*$/, '');
        var title = inner.replace(/<[^>]+>/g, ' ').replace(/\s+/g, ' ').trim();
        if (!title) continue;
        if (title.length > 10) continue;

        /* 在 h3 结束 ~ 下一个 h3 之间找第一个【主板块】stui-vodlist 列表
         * !! 只匹配 "stui-vodlist clearfix"（主板块），侧栏"热播榜"是
         *    "stui-vodlist__media active col-pd clearfix"，不含该精确串，自动排除 */
        var from = h3s[si].end;
        var to = (si + 1 < h3s.length) ? h3s[si + 1].start : html.length;
        var seg = html.substring(from, to);
        var ulStart = seg.indexOf('<ul class="stui-vodlist clearfix"');
        if (ulStart < 0) continue;
        var absStart = from + ulStart;
        var ulEnd = html.indexOf('</ul>', absStart);
        if (ulEnd < 0) continue;
        var ulHtml = html.substring(absStart, ulEnd + 5);

        /* 调用 parseList 解析这个板块下的视频卡片 */
        var items = parseList(ulHtml);
        if (items.length > 0) {
            sections.push({
                title: title,                              /* 板块标题 */
                catId: SITE.getMainCat(title),              /* 对应的分类ID */
                items: items                                /* 视频卡片数组 */
            });
        }
    }
    return sections;
}


