/* ================================================================
 * extractDetailInfo(html) — 提取详情页基本信息
 * ----------------------------------------------------------------
 * [禁改] 禁止修改：函数名 extractDetailInfo、参数 (html)、返回值字段名
 * [可改] 可以修改：函数体内的 CSS 选择器
 *
 * 参数：html — 详情页完整HTML
 * 返回：{
 *   title:    '电影名',           // 标题
 *   pic:      '封面.jpg',          // 封面图URL
 *   desc:     '简介内容...',       // 完整简介
 *   director: '张三',              // 导演
 *   actor:    '李四 / 王五',       // 主演
 *   year:     '2026',             // 年份
 *   area:     '中国',             // 地区
 *   type:     '剧情 / 动作',       // 类型
 *   lang:     '普通话',           // 语言
 *   rating:   '豆瓣 8.5 / IMDB 7.9' // 评分
 * }
 *
 * 解析逻辑：
 *   1. 标题：从 h1 标签提取，去掉 (年份) 后缀
 *   2. 年份：先从 h1 内的 span.year 提取，备用从 h1 文本正则匹配
 *   3. 封面：从 .row .img img 提取 src
 *   4. 导演/主演/类型/地区/语言/评分：遍历 .content-rt 下的 p 标签
 *      每个 p 标签结构：<p><span>字段名</span> <a>值1</a> <a>值2</a></p>
 *   5. 简介：优先完整版 .sqjj_a，其次短版 .zkjj_a
 *
 * [可改] 换站时需要修改的选择器（用目标站的替换）：
 *   '.content-rt h1&&Text' → 目标站标题选择器
 *   '.row .img img&&src'  → 目标站封面选择器
 *   '.content-rt&&p'       → 目标站信息行选择器
 *   '.sqjj_a&&Text'        → 目标站简介选择器
 * ================================================================ */
function extractDetailInfo(html) {
    var info = { title: '', pic: '', desc: '', director: '', actor: '', year: '', area: '', type: '', lang: '', rating: '' };

    /* ---- 标题 ----
     * [可改] 蚂蚁影视（stui）：<h1 class="title">卖冰淇淋的人</h1>（无年份后缀） */
    var h1Text = pdfh(html, '.stui-content__detail h1&&Text') || pdfh(html, 'h1&&Text') || '';
    info.title = h1Text.replace(/\(.*\)/, '').replace(/\s+/g, ' ').trim();

    /* ---- 年份：不在 h1，在信息行的「年份：2026」（下方循环填充） ---- */

    /* ---- 封面图 ----
     * [可改] stui：封面在 <div class="stui-content__thumb"><a class="stui-vodlist__thumb picture v-thumb">
     *   <img class="lazyload" src="占位/360" data-original="真实封面">
     * !! 必须取 data-original */
    info.pic = pdfh(html, '.stui-content__thumb img&&data-original')
             || pdfh(html, 'a.stui-vodlist__thumb&&data-original')
             || pdfh(html, 'img&&data-original')
             || pdfh(html, 'img&&src') || '';
    if (/loading\.png/.test(info.pic)) info.pic = '';

    /* [可改] stui 信息行：多个独立 <p class="data">
     *   主演 p：值在 <a> 里（多个 a，用 / 连接）
     *   导演 p：值在 <a> 里
     *   类型/地区/年份 p：值是【纯文本】（<span class="text-muted">类型：</span>恐怖,恐怖片
     *     <span>地区：</span>美国 <span>年份：</span>2026，三字段合并在同一个 p）
     * 策略：主演/导演从 a 提取；类型/地区/年份把整段 p 去标签成纯文本后按「字段名：值」边界正则拆分 */
    var infoParas = pdfa(html, 'body&&p.data');
    if (!infoParas || infoParas.length === 0) {
        infoParas = pdfa(html, '.stui-content__detail&&p');
    }

    for (var i = 0; i < infoParas.length; i++) {
        var pEl = infoParas[i];

        /* 主演/导演：值在 a 标签里 */
        var links = pdfa(pEl, 'body&&a');
        var linkTexts = [];
        for (var j = 0; j < links.length; j++) {
            var lt = (pdfh(links[j], 'a&&Text') || '').replace(/\s+/g, ' ').trim();
            if (lt) linkTexts.push(lt);
        }
        var linksJoined = linkTexts.join(' / ').trim();

        /* 该 p 去标签后的纯文本（含"字段名：值"），用于类型/地区/年份拆分 */
        var pText = String(pEl)
            .replace(/<[^>]+>/g, ' ')
            .replace(/&nbsp;/g, ' ')
            .replace(/\s+/g, ' ')
            .trim();

        if (pText.indexOf('导演') >= 0 && linksJoined) {
            if (!info.director) info.director = linksJoined;
        }
        if ((pText.indexOf('主演') >= 0 || pText.indexOf('出演') >= 0) && linksJoined) {
            if (!info.actor) info.actor = linksJoined;
        }
        /* 类型/地区/年份：纯文本值（无 a），按字段名边界拆分 */
        var tm = pText.match(/类型：\s*(.+?)(?=\s+(?:地区|年份|语言)：|$)/);
        if (tm && !info.type) info.type = tm[1].replace(/\s+/g, ' ').trim();
        var ram = pText.match(/地区：\s*(.+?)(?=\s+(?:年份|语言)：|$)/);
        if (ram && !info.area) info.area = ram[1].replace(/\s+/g, ' ').trim();
        var lm = pText.match(/语言：\s*(.+?)(?=\s+(?:年份|类型|地区)：|$)/);
        if (lm && !info.lang) info.lang = lm[1].replace(/\s+/g, ' ').trim();
        var ym = pText.match(/年份：\s*(\d{4})/);
        if (ym && !info.year) info.year = ym[1];
    }

    /* ---- 评分 ----
     * [可改] stui 蚂蚁影视详情页无评分字段（score/rating 计数为 0），留空 */
    info.rating = '';

    /* ---- 简介 ----
     * [可改] stui：<p class="desc detail"><span class="detail-sketch">短</span>
     *   <span class="detail-content" style="display:none">完整</span></p>
     * 优先取隐藏的 detail-content（完整版），回退 detail-sketch */
    info.desc = pdfh(html, 'span.detail-content&&Text')
             || pdfh(html, '.detail-sketch&&Text')
             || pdfh(html, 'p.desc&&Text') || '';
    info.desc = info.desc.replace(/\s+/g, ' ').trim();

    return info;
}


/* ================================================================
 * extractEpisodes(html) — 提取选集（线路 + 集数）
 * ----------------------------------------------------------------
 * [禁改] 禁止修改：函数名 extractEpisodes、参数 (html)、返回值结构
 * [可改] 可以修改：函数体内的 CSS 选择器
 *
 * 参数：html — 详情页完整HTML
 * 返回：{
 *   lineNames: ['天堂', '暴风', ...],         // 线路名数组
 *   allLinesEp: [                             // 二维数组，每条线路一个集数列表
 *     [{ name:'HD中字', url:'https://...' }, ...],
 *     [{ name:'第1集', url:'https://...' }, ...],
 *     ...
 *   ]
 * }
 *
 * pkavi.com 选集区HTML结构：
 *   <select class="py-tabs">
 *     <option>天堂(1)</option>     ← 线路名(集数)
 *     <option>暴风(1)</option>
 *   </select>
 *   <ul class="player-all-ul">
 *     <li>                        ← 线路容器
 *       <ul class="player">
 *         <li><a href="/py/xxx.html">HD中字</a></li>
 *       </ul>
 *     </li>
 *   </ul>
 *
 * [可改] 换站时需要修改：
 *   - select.py-tabs&&option → 目标站线路名选择器
 *   - body&&ul.player → 目标站选集列表选择器
 *   - lineNames 去括号的正则（如果格式不同）
 * ================================================================ */
function extractEpisodes(html) {
    var lineNames = [];
    var allLinesEp = [];

    /* ---- 线路名 + 选集列表（蚂蚁影视 · stui 模板） ----
     * [可改] stui 结构：
     *   线路 tab：<a class="btn title" data-mid="1">红牛资源</a>  （顺序未必连号：1,3,4,5,2）
     *   选集 ul ：<ul class="stui-content__playlist play_source_list_item clearfix" data-mid="1">
     *   每个 li ：<li><a href="/vodplay/{id}-{sid}-{nid}.html">正片/HD中字/HD</a></li>
     * 靠 data-mid 把 tab 名对应到 ul；单线路站没有 tab 时自动补"线路N"。
     * !! 集名是「正片/HD中字/HD」这类质量/版本标签，非"第N集"，原样保留
     *    （下方 第N集 剥离正则对它们不命中，故自动保留）。
     * 每条线路独立 push，禁止合并。 */
    var lineTabMap = {};
    var tabLinks = pdfa(html, 'body&&a.btn.title');
    for (var t = 0; t < tabLinks.length; t++) {
        var tmid = String(tabLinks[t]).match(/data-mid="(\d+)"/);
        var tname = (pdfh(tabLinks[t], 'a&&Text') || '').replace(/\s+/g, ' ').trim();
        if (tmid && tname) lineTabMap[tmid[1]] = tname;
    }

    /* 线路容器：每个 ul.play_source_list_item[data-mid] 算一条线路 */
    var blocks = pdfa(html, 'body&&ul.play_source_list_item');
    if (!blocks || !blocks.length) {
        blocks = pdfa(html, 'body&&ul.stui-content__playlist');
    }

    for (var bi = 0; bi < blocks.length; bi++) {
        var eps = [];
        var lis = pdfa(blocks[bi], 'body&&li');
        for (var li = 0; li < lis.length; li++) {
            var epTitle = pdfh(lis[li], 'a&&Text') || '';
            var epLink = pdfh(lis[li], 'a&&href') || '';
            if (!epTitle || !epLink) continue;
            /* [禁改] 只保留播放页链接，避免把排序按钮等混进来 */
            if (epLink.indexOf('/vodplay/') < 0) continue;
            /* 只显示集数数字，不加"第XX集"；本站集名为质量标签，正则不命中则原样保留 */
            var epName = epTitle.replace(/\s+/g, ' ').trim();
            var numM = epName.match(/^第\s*(\d+)\s*[集话期]/);
            if (numM) epName = numM[1];
            eps.push({
                name: epName,
                /* [禁改] 禁止删除：_full 转完整URL，禁止带 # */
                url: _full(epLink)
            });
        }
        if (eps.length > 0) {
            /* 取本 ul 的 data-mid，匹配 tab 名 */
            var midM = String(blocks[bi]).match(/data-mid="(\d+)"/);
            var mid = midM ? midM[1] : '';
            var lname = lineTabMap[mid] || ('线路' + (allLinesEp.length + 1));
            lineNames.push(lname);
            allLinesEp.push(eps);
        }
    }

    /* 备用：如果没找到线路名但找到了选集，用默认名 */
    if (allLinesEp.length > 0 && lineNames.length === 0) {
        for (var k = 0; k < allLinesEp.length; k++) {
            lineNames.push('线路' + (k + 1));
        }
    }

    return { lineNames: lineNames, allLinesEp: allLinesEp };
}


/* ================================================================
 * extractPanResources(html) — 提取网盘/磁力资源
 * ----------------------------------------------------------------
 * [禁改] 禁止修改：函数名 extractPanResources、参数 (html)、返回值结构
 * [可改] 可以修改：函数体内的选择器和URL分类规则
 *
 * 参数：html — 详情页完整HTML
 * 返回：{
 *   groupNames: ['磁力链接', '百度网盘', '夸克网盘', ...],
 *   allGroups: [
 *     [{ name:'资源1', url:'magnet:...' }, ...],
 *     [{ name:'资源2', url:'https://pan.baidu.com/...' }, ...],
 *     ...
 *   ]
 * }
 *
 * pkavi.com 下载资源区HTML结构：
 *   <div class="down-list">
 *     <a class="folder" href="magnet:?xt=urn:btih:...">磁力链接名</a>
 *     <a class="folder" href="https://pan.baidu.com/s/...">百度网盘资源名</a>
 *   </div>
 *
 * [可改] 换站时需要修改：
 *   - body&&a.folder → 目标站下载资源链接选择器
 *   - URL分类规则 → 根据目标站支持的网盘类型调整
 * ================================================================ */
function extractPanResources(html) {
    var groupMap = {};
    var groupOrder = [];

    /* [可改] 可以修改：资源链接选择器
     * 优先用 a.folder 找所有资源链接（pkavi.com 特有结构） */
    var folderLinks = pdfa(html, 'body&&a.folder');

    /* ---- 备用1：从"下载"区域提取 ----
     * 很多站详情页有专门的"下载地址"板块，只在那个区域内搜索链接
     * 这样可以避免误匹配页脚的"百度蜘蛛"之类的链接 */
    if (!folderLinks || folderLinks.length === 0) {
        var downloadHtml = '';
        var downloadKeywords = ['下载地址', '网盘下载', '磁力下载', '下载专区', '下载资源'];
        for (var dk = 0; dk < downloadKeywords.length; dk++) {
            var idx = html.indexOf(downloadKeywords[dk]);
            if (idx > 0) {
                downloadHtml = html.substring(idx, idx + 5000);
                break;
            }
        }
        if (downloadHtml) {
            folderLinks = pdfa(downloadHtml, 'body&&a');
        }
    }

    /* ---- 备用2：搜索 magnet: 开头的链接 ---- */
    if (!folderLinks || folderLinks.length === 0) {
        folderLinks = pdfa(html, 'body&&a[href^="magnet:"]');
    }

    var seen = {};
    for (var i = 0; i < folderLinks.length; i++) {
        var fLink = pdfh(folderLinks[i], 'a&&href') || '';
        var fTitle = pdfh(folderLinks[i], 'a&&Text') || pdfh(folderLinks[i], 'a&&title') || '';

        /* [禁改] 禁止删除：过滤和去重逻辑 */
        if (!fLink || !fTitle || seen[fLink]) continue;

        /* [可改] 可以修改：URL分类规则
         * 用精确域名匹配，避免误匹配页脚的"百度蜘蛛"等链接
         * 磁力：magnet:
         * 百度：pan.baidu.com / yun.baidu.com
         * 夸克：pan.quark.cn / quark.cn
         * 阿里：aliyundrive.com / alipan.com
         * 天翼：cloud.189.cn
         * 迅雷：pan.xunlei.com
         * UC：pan.uc.cn / drive.uc.cn */
        var gName = '';
        if (/^magnet:/i.test(fLink)) {
            gName = '磁力链接';
        } else if (/pan\.baidu\.com|yun\.baidu\.com/i.test(fLink)) {
            gName = '百度网盘';
        } else if (/pan\.quark\.cn|quark\.cn/i.test(fLink)) {
            gName = '夸克网盘';
        } else if (/aliyundrive\.com|alipan\.com/i.test(fLink)) {
            gName = '阿里网盘';
        } else if (/cloud\.189\.cn/i.test(fLink)) {
            gName = '天翼网盘';
        } else if (/pan\.xunlei\.com/i.test(fLink)) {
            gName = '迅雷网盘';
        } else if (/pan\.uc\.cn|drive\.uc\.cn/i.test(fLink)) {
            gName = 'UC网盘';
        }

        /* 不是网盘/磁力链接则跳过 */
        if (!gName) continue;

        seen[fLink] = true;
        fTitle = fTitle.replace(/\s+/g, ' ').trim();

        /* 按分类分组 */
        if (!groupMap[gName]) { groupMap[gName] = []; groupOrder.push(gName); }
        groupMap[gName].push({ name: fTitle, url: fLink });
    }

    /* 构造返回数据 */
    var groupNames = groupOrder;
    var allGroups = [];
    for (var k = 0; k < groupOrder.length; k++) {
        allGroups.push(groupMap[groupOrder[k]]);
    }

    return { groupNames: groupNames, allGroups: allGroups };
}


