 * 流程：
 *   1. 第1页顶部加风格切换按钮
 *   2. 读取 STYLE_KEY 变量判断当前风格
 *   3. 调用 home_scroll() 或 home_classic()
 * ================================================================ */

function home() {
    var page = parseInt(MY_PAGE || '1', 10);
    var curStyle = getMyVar(STYLE_KEY, 'classic');
    var d = [];

    /* 第1页顶部加风格切换按钮 */
