    secClsMap: {
        '电影': '1',
        '电视剧': '2',
        '综艺': '3',
        '动漫': '4',
        '推荐电影': '1',
        '推荐电视剧': '2'
    },

    /* ============================================================
     * [可改] 分类页URL构建函数（换站必改函数体，不改函数名和参数）
     * ============================================================
     *
     * [禁改] 禁止修改：函数名 buildCatUrl、参数 (cls, filter, page)
     * [可改] 可以修改：函数体内部的URL拼接逻辑
     *
     * 参数说明：
     *   cls    — 分类ID（cats 数组里的 s 值，如 '1'）
     *   filter — 筛选条件对象，可能包含：
     *            { area: '日本', year: '2026', class: '剧情', lang: '日语' }
     *            没有筛选时为 null
     *   page   — 页码（1开始），第1页通常不需要特殊处理
     *
     * 返回：完整的分类页URL字符串
     *
     * ═════════════════════════════════════════════════════════
     * pkavi.com 的URL格式：
     *   /ms/{cls}-{area}-{year}-{class}-{lang}-------{page}.html
     *   共12段（cls + 11段），用 - 分隔
     *   第1段 = cls（分类ID）
     *   第2段 = area（地区）
     *   第3段 = year（年份）
     *   第4段 = class（类型/剧情）
     *   第5段 = lang（语言）
     *   第6~11段 = 空（网站预留字段）
     *   第12段 = page（分页号，第1页为空）
     *
     *   示例：
     *   全部第1页 → /ms/1-----------.html
     *   类型=剧情  → /ms/1---剧情---------.html
     *   第2页     → /ms/1-----------2.html
     * ═════════════════════════════════════════════════════════
     *
     * [可改] 其他站的 buildCatUrl 示例：
     *
     *   // 简单的 ?page= 格式
     *   buildCatUrl: function(cls, filter, page) {
     *      var url = this.host + '/list/' + cls;
     *      if (filter && filter.area) url += '/' + filter.area;
     *      if (page > 1) url += '?page=' + page;
     *      return url;
     *   }
     *
     *   // 路径参数格式
     *   buildCatUrl: function(cls, filter, page) {
     *      var url = this.host + '/category/' + cls;
     *      if (filter && filter.year) url += '/year/' + filter.year;
     *      url += '/page/' + (page || 1);
     *      return url;
     *   }
     * ======================================================== */
    buildCatUrl: function (cls, filter, page) {
        /* 独播库 12 段 URL：/vodshow/{cls}-{area}-{sort}-{class}-{lang}-{letter}---{page}---{year}.html
         * 段位（含 cls 共 12 段，索引 0..11）：
         *   0=cls  1=area  2=sort  3=class(剧情)  4=lang  5=letter
         *   6,7 空  8=page  9,10 空  11=year
         * 实测依据：
         *   第1页 /vodshow/2-----------.html
         *   第2页 /vodshow/2--------2---.html      ← 分页在段8
         *   地区   /vodshow/2-大陆----------.html  ← 段1
         *   排序   /vodshow/2--人气---------.html  ← 段2
         *   剧情   /vodshow/2---悬疑--------.html  ← 段3
         *   语言   /vodshow/2----国语-------.html  ← 段4
         *   字母   /vodshow/2-----A------.html     ← 段5
         *   年份   /vodshow/2-----------2026.html  ← 段11 */
        var parts = ['', '', '', '', '', '', '', '', '', '', ''];
        var enc = function (v) {
            if (!v) return '';
            return (String(v).indexOf('%') >= 0) ? String(v) : encodeURIComponent(v);
        };
        if (filter) {
            if (filter.area)   parts[0] = enc(filter.area);
            if (filter.sort)   parts[1] = enc(filter.sort);
            if (filter.class)  parts[2] = enc(filter.class);
            if (filter.lang)   parts[3] = enc(filter.lang);
            if (filter.letter) parts[4] = enc(filter.letter);
            if (filter.year)   parts[10] = enc(filter.year);
        }
        if (page > 1) parts[7] = String(page);
        return this.host + '/vodshow/' + cls + '-' + parts.join('-') + '.html';
    },

    /* ============================================================
     * [可改] 筛选选项解析（换站必改函数体，不改函数名和参数）
     * ============================================================
     *
     * [禁改] 禁止修改：函数名 parseFilterOptions、参数 (html, cls)
     * [可改] 可以修改：函数体内部的CSS选择器和解析逻辑
     *
     * 从分类页HTML中提取筛选栏的所有选项
     *
     * 参数：
     *   html — 分类页完整HTML字符串
     *   cls  — 当前分类ID（有些站根据分类显示不同筛选维度）
     *
     * 返回格式（必须是这个结构，调用方按此读取）：
     *   [
     *     {
     *       title: '类型',              ← 维度标题
     *       options: [
     *         { t: '全部', s: '/ms/1---.html', on: false },  ← 选项
     *         { t: '剧情', s: '/ms/1---剧情-.html', on: true }, ← on=当前选中
     *         ...
     *       ]
     *     },
     *     { title: '地区', options: [...] },
     *     ...
     *   ]
     *
     *   t  — 选项文字（界面按钮显示）
     *   s  — 选项链接（点击后跳转的URL，相对路径即可）
     *   on — 是否当前选中（true=高亮）
     *
     * ═════════════════════════════════════════════════════════
     * pkavi.com 筛选栏HTML结构：
     *   <div class="list-box">
     *     <dl>
     *       <dt>类型</dt>
     *       <dd><a href="...">全部</a><a class="current" href="...">剧情</a>...</dd>
     *     </dl>
     *     <dl>...</dl>
     *   </div>
     * ═════════════════════════════════════════════════════════
     *
     * [可改] 其他站的 parseFilterOptions 示例：
     *
     *   // 如果目标站筛选栏是 div 标签格式
     *   parseFilterOptions: function(html, cls) {
     *      var dims = [];
     *      var groups = pdfa(html, '.filter-group');
     *      for (var i = 0; i < groups.length; i++) {
     *          var title = pdfh(groups[i], '.filter-title&&Text');
     *          var opts = [];
     *          var links = pdfa(groups[i], 'a');
     *          for (var j = 0; j < links.length; j++) {
     *              opts.push({
     *                  t: pdfh(links[j], 'a&&Text'),
     *                  s: pdfh(links[j], 'a&&href'),
     *                  on: /active/.test(pdfh(links[j], 'a&&class') || '')
     *              });
     *          }
     *          dims.push({ title: title, options: opts });
     *      }
     *      return dims;
     *   }
     * ======================================================== */
    parseFilterOptions: function (html, cls) {
        /* 星廷影院筛选栏（MacCMS 模板）：
         *   <div class="FPre1waj item collapse list_type" id="collapse">
         *     <ul class="clearfix">
         *       <li class="text"><span class="text-muted">按分类</span></li>
         *       <li><a href="/vodshow/6-----------.html" title="全部" data="id-1">全部</a></li>
         *       <li><a class="active" href="...">喜剧</a></li>   ← 选中态在 a 的 class 上
         *     </ul>
         *     ... 多组 ul（按分类/按类型/按地区/按年份/按字母）
         * !! 组名在无 a 的 li 里取 span 文本；选中态看 a 是否含 active。 */
        var dims = [];
        var groups = pdfa(html, 'body&&div[id^="collapse"]&&ul');
        if (!groups || groups.length === 0) {
            groups = pdfa(html, 'body&&div.list_type&&ul');
        }
        if (!groups || groups.length === 0) return dims;
        for (var i = 0; i < groups.length; i++) {
            var g = groups[i];
            var lis = pdfa(g, 'body&&li');
            if (!lis || lis.length === 0) continue;
            var dimTitle = '';
            var opts = [];
            for (var j = 0; j < lis.length; j++) {
                var href = pdfh(lis[j], 'a&&href') || '';
                var text = pdfh(lis[j], 'a&&Text') || '';
                text = text.replace(/\s+/g, ' ').trim();
                if (href && text) {
                    var aClass = pdfh(lis[j], 'a&&class') || '';
                    opts.push({
                        t: text,
                        s: href,
                        on: /(^|\s)active(\s|$)/.test(aClass)
                    });
                } else if (!href && !text) {
                    /* 组名 li：无 a，取内层 span 文本（如"按分类"） */
                    var spanTxt = (pdfh(lis[j], 'span&&Text') || '').replace(/\s+/g, ' ').trim();
                    if (spanTxt && !dimTitle) dimTitle = spanTxt;
                }
            }
            if (opts.length > 0) {
                /* 组名"按分类"→"分类"，去掉"按"前缀；无组名则用序号兜底 */
                var label = dimTitle ? dimTitle.replace(/^按/, '') : ('筛选' + (i + 1));
                dims.push({ title: label, options: opts });
            }
        }
        return dims;
    },

    /* ============================================================
     * [可改] 获取主分类ID（换站必改函数体，不改函数名和参数）
     * ============================================================
     *
     * [禁改] 禁止修改：函数名 getMainCat、参数 (title)
