     *      }
     *      return this.cats[0].s;
     *   }
     * ======================================================== */
    getMainCat: function (title) {
        /* 先精确匹配，再包含匹配（独播库板块名：热剧推荐/陆剧/日韩剧/台泰剧/短剧/电影/综艺/动漫） */
        if (this.secClsMap[title]) return this.secClsMap[title];
        var best = null, bestLen = 0;
        for (var key in this.secClsMap) {
            if (title.indexOf(key) >= 0 && key.length > bestLen) {
                best = this.secClsMap[key];
                bestLen = key.length;
            }
        }
        if (best) return best;
        return '1';
