/* ================================================================
 * extractDetailInfo(html) — 提取详情页基本信息
 * ----------------------------------------------------------------
 * [禁改] 禁止修改：函数名 extractDetailInfo、参数 (html)、返回值字段名
 * [可改] 可以修改：函数体内的 CSS 选择器
 *
 * 参数：html — 详情页完整HTML
 * 返回：{
 *   title:    '电影名',           // 标题
 *   pic:      '封面.jpg',          // 封面图URL
 *   desc:     '简介内容...',       // 完整简介
 *   director: '张三',              // 导演
 *   actor:    '李四 / 王五',       // 主演
 *   year:     '2026',             // 年份
 *   area:     '中国',             // 地区
 *   type:     '剧情 / 动作',       // 类型
 *   lang:     '普通话',           // 语言
 *   rating:   '豆瓣 8.5 / IMDB 7.9' // 评分
 * }
 *
 * 解析逻辑：
 *   1. 标题：从 h1 标签提取，去掉 (年份) 后缀
 *   2. 年份：先从 h1 内的 span.year 提取，备用从 h1 文本正则匹配
 *   3. 封面：从 .row .img img 提取 src
 *   4. 导演/主演/类型/地区/语言/评分：遍历 .content-rt 下的 p 标签
 *      每个 p 标签结构：<p><span>字段名</span> <a>值1</a> <a>值2</a></p>
 *   5. 简介：优先完整版 .sqjj_a，其次短版 .zkjj_a
 *
 * [可改] 换站时需要修改的选择器（用目标站的替换）：
 *   '.content-rt h1&&Text' → 目标站标题选择器
 *   '.row .img img&&src'  → 目标站封面选择器
 *   '.content-rt&&p'       → 目标站信息行选择器
 *   '.sqjj_a&&Text'        → 目标站简介选择器
 * ================================================================ */
function extractDetailInfo(html) {
    var info = { title: '', pic: '', desc: '', director: '', actor: '', year: '', area: '', type: '', lang: '', rating: '' };

    /* ---- 标题 ----
     * [可改] 星廷影院：<h2 class="text-overflow">鉴定</h2>（在 div.details-info 内） */
    info.title = pdfh(html, 'div.details-info&&h2&&Text') || pdfh(html, 'h2&&Text') || '';
    info.title = info.title.replace(/\s+/g, ' ').trim();

    /* ---- 封面图 ----
     * [可改] 星廷影院：封面不在 img 上，在 <a class="video-pic" style="background: url(https://...webp) no-repeat">
     * 从 style 属性里正则取 url(...) */
    var styleTxt = pdfh(html, 'div.details-pic&&a&&style') || pdfh(html, 'a.video-pic&&style') || '';
    var picMatch = String(styleTxt).match(/url\(["']?([^"')\s]+)["']?\)/);
    info.pic = picMatch ? picMatch[1] : '';
    if (!info.pic) {
        info.pic = pdfh(html, 'div.details-pic&&a&&data-original')
                 || pdfh(html, 'img&&data-original')
                 || pdfh(html, 'img&&src') || '';
    }

    /* [可改] 星廷影院信息行：div.details-info 下 ul.info > li，每个 li 一个字段：
     *   <span class="hidden-xs">类型：</span><a href="/vodtype/13.html">国产剧</a>
     *   <span class="hidden-xs">主演： 张慧雯,岳丽娜,...</span>
     *   <span>导演： 郭世民</span>
     *   <span>国家/地区：</span>中国大陆
     *   <span>语言/字幕：</span>汉语普通话
     *   <span>上映时间：</span>2026
     * 策略：每个 li 去标签成纯文本，按「字段名：值」边界正则拆分。 */
    var infoParas = pdfa(html, 'body&&div.details-info&&ul.info&&li');
    if (!infoParas || infoParas.length === 0) {
        infoParas = pdfa(html, 'body&&div.details-info&&li');
    }

    for (var i = 0; i < infoParas.length; i++) {
        var pEl = infoParas[i];

        /* 该 li 去标签后的纯文本（含"字段名：值"），用于拆分 */
        var pText = String(pEl)
            .replace(/<[^>]+>/g, ' ')
            .replace(/&nbsp;/g, ' ')
            .replace(/\s+/g, ' ')
            .trim();

        var mDir = pText.match(/导演：\s*(.+)$/);
        if (mDir && mDir[1]) {
            var dv = mDir[1].replace(/\s+/g, ' ').trim();
            if (!info.director) info.director = dv;
        }
        var mStar = pText.match(/(?:主演|出演)：\s*(.+)$/);
        if (mStar && mStar[1]) {
            var av = mStar[1].replace(/\s+/g, ' ').trim();
            if (!info.actor) info.actor = av;
        }
        var mType = pText.match(/类型：\s*([^\s]+)/);
        if (mType && mType[1]) {
            if (!info.type) info.type = mType[1].replace(/\s+/g, ' ').trim();
        }
        var mArea = pText.match(/国家\/地区：\s*(.+)$/);
        if (mArea && mArea[1]) {
            var ar = mArea[1].replace(/\s+/g, ' ').trim();
            if (!info.area) info.area = ar;
        }
        var mLang = pText.match(/语言\/字幕：\s*(.+)$/);
        if (mLang && mLang[1]) {
            var lg = mLang[1].replace(/\s+/g, ' ').trim();
            if (!info.lang) info.lang = lg;
        }
        var mYear = pText.match(/上映时间：\s*(\d{4})/);
        if (mYear && mYear[1] && !info.year) info.year = mYear[1];
    }

    /* ---- 评分 ----
     * [可改] 星廷影院详情页评分区只有百分比条，无直接数字评分，留空 */
    info.rating = '';

    /* ---- 简介 ----
     * [可改] 星廷影院：<span class="details-content-all">完整版（display:none）
     *   <span class="details-content-default">短版；优先完整版 */
    info.desc = pdfh(html, 'span.details-content-all&&Text')
             || pdfh(html, 'span.details-content-default&&Text')
             || pdfh(html, 'p.desc&&Text') || '';
    info.desc = info.desc.replace(/\s+/g, ' ').trim();

    return info;
}


/* ================================================================
 * extractEpisodes(html) — 提取选集（线路 + 集数）
 * ----------------------------------------------------------------
 * [禁改] 禁止修改：函数名 extractEpisodes、参数 (html)、返回值结构
 * [可改] 可以修改：函数体内的 CSS 选择器
 *
 * 参数：html — 详情页完整HTML
 * 返回：{
 *   lineNames: ['天堂', '暴风', ...],         // 线路名数组
 *   allLinesEp: [                             // 二维数组，每条线路一个集数列表
 *     [{ name:'HD中字', url:'https://...' }, ...],
 *     [{ name:'第1集', url:'https://...' }, ...],
 *     ...
 *   ]
 * }
 *
 * pkavi.com 选集区HTML结构：
 *   <select class="py-tabs">
 *     <option>天堂(1)</option>     ← 线路名(集数)
 *     <option>暴风(1)</option>
 *   </select>
 *   <ul class="player-all-ul">
 *     <li>                        ← 线路容器
 *       <ul class="player">
 *         <li><a href="/py/xxx.html">HD中字</a></li>
 *       </ul>
 *     </li>
 *   </ul>
 *
 * [可改] 换站时需要修改：
 *   - select.py-tabs&&option → 目标站线路名选择器
 *   - body&&ul.player → 目标站选集列表选择器
 *   - lineNames 去括号的正则（如果格式不同）
 * ================================================================ */
function extractEpisodes(html) {
    var lineNames = [];
    var allLinesEp = [];

    /* ---- 线路名 + 选集列表（星廷影院 · MacCMS 模板） ----
     * [可改] 结构：
     *   线路 tab：<ul class="nav nav-tabs" id="playTab"> <li><a href="#con_playlist_3" data-toggle="tab">baof云</a></li> ...
     *   选集 ul ：<ul class="clearfix fade in active " id="con_playlist_3"> <li><a href="/vodplay/{id}-{sid}-{nid}.html">第1集</a></li> ...
     * !! 线路 tab 的 href="#con_playlist_N" 与选集 ul 的 id 对应，用它配对线路名，禁止按 DOM 顺序硬配。
     * !! 每条线路独立 push 进 allLinesEp，禁止合并。
     * !! 集名是「第N集」，剥离为纯数字（不加"第XX集"前缀）。 */
    var lineNames = [];
    var allLinesEp = [];

    /* 线路 tab：按 href 收集 {name, href} */
    var tabLis = pdfa(html, 'body&&ul[id^="playTab"]&&li');
    var tabNames = [];
    for (var ti = 0; ti < tabLis.length; ti++) {
        var tabName = (pdfh(tabLis[ti], 'a&&Text') || '').replace(/\s+/g, ' ').trim();
        var tabHref = (pdfh(tabLis[ti], 'a&&href') || '').trim();
        if (tabName && tabHref.indexOf('#con_playlist_') === 0) {
            tabNames.push({ name: tabName, href: tabHref });
        }
    }

    /* 选集容器：ul[id^="con_playlist_"] */
    var blocks = pdfa(html, 'body&&ul[id^="con_playlist_"]');
    if (!blocks || !blocks.length) {
        blocks = pdfa(html, 'body&&div.playlist&&ul');
    }

    for (var bi = 0; bi < blocks.length; bi++) {
        var eps = [];
        var lis = pdfa(blocks[bi], 'body&&li');
        for (var li = 0; li < lis.length; li++) {
            var epTitle = (pdfh(lis[li], 'a&&Text') || '').replace(/\s+/g, ' ').trim();
            var epLink = pdfh(lis[li], 'a&&href') || '';
            if (!epTitle || !epLink) continue;
            /* [禁改] 只保留播放页链接 */
            if (epLink.indexOf('/vodplay/') < 0) continue;
            /* 只显示集数数字，不加"第XX集" */
            var numM = epTitle.match(/^第\s*(\d+)\s*[集话期]/);
            var epName = numM ? numM[1] : epTitle;
            eps.push({
                name: epName,
                /* [禁改] 禁止删除：_full 转完整URL，禁止带 # */
                url: _full(epLink)
            });
        }
        if (eps.length > 0) {
            /* 取本 ul 的 id，匹配线路 tab 名 */
            var idM = String(blocks[bi]).match(/id="(con_playlist_\d+)"/);
            var lname = '';
            if (idM) {
                for (var t2 = 0; t2 < tabNames.length; t2++) {
                    if (tabNames[t2].href === '#' + idM[1]) { lname = tabNames[t2].name; break; }
                }
            }
            if (!lname) lname = '线路' + (allLinesEp.length + 1);
            lineNames.push(lname);
            allLinesEp.push(eps);
        }
    }

    /* 备用：如果没找到线路名但找到了选集，用默认名 */
    if (allLinesEp.length > 0 && lineNames.length === 0) {
        for (var k = 0; k < allLinesEp.length; k++) {
            lineNames.push('线路' + (k + 1));
        }
    }

    return { lineNames: lineNames, allLinesEp: allLinesEp };
}


/* ================================================================
 * extractPanResources(html) — 提取网盘/磁力资源
 * ----------------------------------------------------------------
 * [禁改] 禁止修改：函数名 extractPanResources、参数 (html)、返回值结构
 * [可改] 可以修改：函数体内的选择器和URL分类规则
 *
 * 参数：html — 详情页完整HTML
 * 返回：{
 *   groupNames: ['磁力链接', '百度网盘', '夸克网盘', ...],
 *   allGroups: [
 *     [{ name:'资源1', url:'magnet:...' }, ...],
 *     [{ name:'资源2', url:'https://pan.baidu.com/...' }, ...],
 *     ...
 *   ]
 * }
 *
 * pkavi.com 下载资源区HTML结构：
 *   <div class="down-list">
 *     <a class="folder" href="magnet:?xt=urn:btih:...">磁力链接名</a>
 *     <a class="folder" href="https://pan.baidu.com/s/...">百度网盘资源名</a>
 *   </div>
 *
 * [可改] 换站时需要修改：
 *   - body&&a.folder → 目标站下载资源链接选择器
 *   - URL分类规则 → 根据目标站支持的网盘类型调整
 * ================================================================ */
function extractPanResources(html) {
    var groupMap = {};
    var groupOrder = [];

    /* [可改] 可以修改：资源链接选择器
     * 星廷影院详情页【无网盘/磁力资源】，只有影片下载入口
     *   /label/download/{id}.html（跳转到下载页，非 magnet/pan 直链）
     * 因此三级兜底链自然返回空（下方 URL 分类规则不会命中任何链接），
     * renderPanResources 会跳过，不影响详情页其余部分。 */
    var folderLinks = pdfa(html, 'body&&a.folder');

    /* ---- 备用1：从"下载"区域提取 ----
     * 很多站详情页有专门的"下载地址"板块，只在那个区域内搜索链接
     * 这样可以避免误匹配页脚的"百度蜘蛛"之类的链接 */
    if (!folderLinks || folderLinks.length === 0) {
        var downloadHtml = '';
        var downloadKeywords = ['下载地址', '网盘下载', '磁力下载', '下载专区', '下载资源'];
        for (var dk = 0; dk < downloadKeywords.length; dk++) {
            var idx = html.indexOf(downloadKeywords[dk]);
            if (idx > 0) {
                downloadHtml = html.substring(idx, idx + 5000);
                break;
            }
        }
        if (downloadHtml) {
            folderLinks = pdfa(downloadHtml, 'body&&a');
        }
    }

    /* ---- 备用2：搜索 magnet: 开头的链接 ---- */
    if (!folderLinks || folderLinks.length === 0) {
        folderLinks = pdfa(html, 'body&&a[href^="magnet:"]');
    }

    var seen = {};
    for (var i = 0; i < folderLinks.length; i++) {
        var fLink = pdfh(folderLinks[i], 'a&&href') || '';
        var fTitle = pdfh(folderLinks[i], 'a&&Text') || pdfh(folderLinks[i], 'a&&title') || '';

        /* [禁改] 禁止删除：过滤和去重逻辑 */
        if (!fLink || !fTitle || seen[fLink]) continue;

        /* [可改] 可以修改：URL分类规则
         * 用精确域名匹配，避免误匹配页脚的"百度蜘蛛"等链接
         * 磁力：magnet:
         * 百度：pan.baidu.com / yun.baidu.com
         * 夸克：pan.quark.cn / quark.cn
         * 阿里：aliyundrive.com / alipan.com
         * 天翼：cloud.189.cn
         * 迅雷：pan.xunlei.com
         * UC：pan.uc.cn / drive.uc.cn */
        var gName = '';
        if (/^magnet:/i.test(fLink)) {
            gName = '磁力链接';
        } else if (/pan\.baidu\.com|yun\.baidu\.com/i.test(fLink)) {
            gName = '百度网盘';
        } else if (/pan\.quark\.cn|quark\.cn/i.test(fLink)) {
            gName = '夸克网盘';
        } else if (/aliyundrive\.com|alipan\.com/i.test(fLink)) {
            gName = '阿里网盘';
        } else if (/cloud\.189\.cn/i.test(fLink)) {
            gName = '天翼网盘';
        } else if (/pan\.xunlei\.com/i.test(fLink)) {
            gName = '迅雷网盘';
        } else if (/pan\.uc\.cn|drive\.uc\.cn/i.test(fLink)) {
            gName = 'UC网盘';
        }

        /* 不是网盘/磁力链接则跳过 */
        if (!gName) continue;

        seen[fLink] = true;
        fTitle = fTitle.replace(/\s+/g, ' ').trim();

        /* 按分类分组 */
        if (!groupMap[gName]) { groupMap[gName] = []; groupOrder.push(gName); }
        groupMap[gName].push({ name: fTitle, url: fLink });
    }

    /* 构造返回数据 */
    var groupNames = groupOrder;
    var allGroups = [];
    for (var k = 0; k < groupOrder.length; k++) {
        allGroups.push(groupMap[groupOrder[k]]);
    }

    return { groupNames: groupNames, allGroups: allGroups };
}


