/* ===== 初始化共享库 =====
 * 用站点配置初始化共享库，设置 host 和 prefix
 * 之后所有 _cfg.xxx 读取的都是这个站的配置 */
initLib({
    host: SITE.host,
    prefix: SITE.prefix
});

/* ===== 风格变量名 =====
 * 存储当前选中的风格（classic / scroll）
 * 格式：{prefix}_style  如 "pk_style" */
var STYLE_KEY = SITE.prefix + '_style';


/* ================================================================
 * ================================================================
 * [风格] 风格切换按钮
 * ================================================================
 * ================================================================
 * 调用方式：renderStyleSwitcher(d);
 *
 * 渲染两个按钮：
 *   [经典风格]  [滚动风格]
 *
 * 点击按钮切换风格：
 *   1. 保存风格选择到 STYLE_KEY 变量
 *   2. 刷新页面（不记录历史，切换不产生返回层级）
 *   3. 显示切换提示 toast
 *
 * 当前选中的风格用对应颜色高亮
 * ================================================================ */

function renderStyleSwitcher(d) {
    var curStyle = getMyVar(STYLE_KEY, 'classic');
    var styles = [
        { key: 'classic', name: '经典风格', color: '#FF6B6B' },
        { key: 'scroll',  name: '滚动风格', color: '#4ECDC4' }
    ];

    for (var i = 0; i < styles.length; i++) {
        var s = styles[i];
        var active = curStyle === s.key;
        d.push({
            title: active
                ? '\u2018\u2018\u2019\u2019<b><font color="' + s.color + '">' + s.name + '</font></b>'
                : s.name,
            url: $('#noLoading##noHistory#').lazyRule(function (params) {
                putMyVar(params.key, params.value);
                refreshPage(false);
                return 'toast://已切换到' + params.label;
            }, { key: STYLE_KEY, value: s.key, label: s.name }),
            col_type: 'scroll_button',
            extra: active ? { backgroundColor: s.color + '20' } : {}
        });
    }
    d.push({ col_type: 'line_blank' });
}


/* ================================================================
 * ================================================================
 * [首页] 主入口 · 首页函数
 * ================================================================
 * ================================================================
 * 海阔调用 home() 时执行
 * 根据当前风格变量调度到对应风格的首页函数
 *
 * 参数说明：
 *   MY_PAGE — 海阔内置变量，当前页码（字符串，从1开始）
 *
 * 流程：
 *   1. 第1页顶部加风格切换按钮
 *   2. 读取 STYLE_KEY 变量判断当前风格
 *   3. 调用 home_scroll() 或 home_classic()
 * ================================================================ */

function home() {
    var page = parseInt(MY_PAGE || '1', 10);
    var curStyle = getMyVar(STYLE_KEY, 'classic');
    var d = [];

    /* 第1页顶部加风格切换按钮 */
    if (page === 1) {
        renderStyleSwitcher(d);
    }

    /* 根据风格变量调度 */
    if (curStyle === 'scroll') {
        home_scroll(d, page);
    } else {
        home_classic(d, page);
    }
}


/* ================================================================
 * ================================================================
 * [按钮] 经典风格专用：带高亮的分类按钮
 * ================================================================
 * ================================================================
 * 调用方式：renderCatButtonsActive(d, SITE.cats, cls);
 *
 * 和共享库的 renderCatButtons 的区别：
 *   renderCatButtons       → 首页用，无高亮，随机背景色
 *   renderCatButtonsActive → 分类页用，当前分类高亮
 *
 * 渲染内容：
 *   [[首页]首页] [电影] [剧集] [综艺] [动漫] [短剧]
 *              ↑ 当前分类高亮红色
 *
 * 点击按钮：
 *   - 首页按钮：清空 _cls 变量 → 回到首页模式
 *   - 分类按钮：设置 _cls = 分类ID → 进入分类模式
 *   - 同时清空筛选变量（url, t, fold）
 * ================================================================ */

function renderCatButtonsActive(d, cats, activeCls) {
    if (!cats || !cats.length) return;
    var vk = SITE.prefix + '_cls';
    var fk = _filterKey();

    /* 返回首页按钮 */
    d.push({
        title: '\u2018\u2018\u2019\u2019<b>[首页]首页</b>',
        col_type: 'scroll_button',
        url: $('#noLoading##noRecordHistory#').lazyRule(function (key, fk) {
            putMyVar(key, '');
            clearVar(fk);
            clearMyVar('url');
            clearMyVar('t');
            clearMyVar('fold');
            refreshPage(true);
            return 'hiker://empty';
        }, vk, fk),
        extra: { backgroundColor: '#e8e8e8' }
    });

    /* 分类按钮，当前选中的高亮 */
    for (var ci = 0; ci < cats.length; ci++) {
        var isActive = (activeCls === cats[ci].s);
        d.push({
            title: isActive
                ? '\u2018\u2018\u2019\u2019<b><font color="#FF5D50">' + cats[ci].t + '</font></b>'
                : cats[ci].t,
            col_type: 'scroll_button',
            url: $('#noLoading##noRecordHistory#').lazyRule(function (s, key, fk) {
                putMyVar(key, s);
                clearVar(fk);
                clearMyVar('url');
                clearMyVar('t');
                clearMyVar('fold');
                refreshPage(true);
                return 'hiker://empty';
            }, cats[ci].s, vk, fk),
            extra: { backgroundColor: isActive ? '#FF5D5015' : '#f5f5f5' }
        });
    }
    d.push({ col_type: 'line_blank' });
}


/* ================================================================
 * ================================================================
 * [按钮] 共用：URL计算 + 折叠筛选栏
 * ================================================================
 * ================================================================
 * 两个函数：
 *   computeFilterUrl(defaultUrl, page)  → 计算要请求的URL（含分页）
 *   renderScrollBoxFilter(d, catHtml)   → 通用scroll-box格式筛选栏
 *   renderSiteFilter(d, catHtml)       → pkavi.com专用筛选栏
 *
 * 筛选变量（两种风格共用）：
 *   url  — 当前选中的筛选URL（切换筛选时更新）
 *   t    — 各组选中索引的JSON数组
 *   fold — 展开/折叠状态（'0'折叠 / '1'展开）
 * ================================================================ */

/* ----------------------------------------------------------------
 * computeFilterUrl(defaultUrl, page) — 计算要请求的URL
 * ----------------------------------------------------------------
 * 参数：
 *   defaultUrl — 默认分类页URL（由 SITE.buildCatUrl 生成）
 *   page       — 当前页码
 *
 * 逻辑：
 *   1. 读取用户选中的筛选URL（getMyVar('url')），没有则用默认
 *   2. 根据URL格式追加分页参数
 *
 * 支持的URL格式：
 *   /ms/xxx-----------.html → 替换最后一段为页码
 *   /year/2026.html          → 改为 /page/N/year/2026.html
 *   /year/2026/              → 改为 /page/N/year/2026/
 *   其他                     → 追加 /page/N
 * ============================================================= */
function computeFilterUrl(defaultUrl, page) {
    var trueUrl = getMyVar('url', defaultUrl);
    if (page > 1) {
        if (/\/show\//.test(trueUrl) || /\/vodshow\//.test(trueUrl)) {
            /* MacCMS /show/ 或 /vodshow/ 格式: 第9段是分页号（索引8）
             * 独播库实测：第1页 /vodshow/2-----------.html
             *             第2页 /vodshow/2--------2---.html
             * 前8个分隔符(9段) + 分页段 + 剩余段 + .html */
            trueUrl = trueUrl.replace(/(\/(?:vod)?show\/(?:[^-]*-){8})[^-]*(-.*\.html)/, '$1' + page + '$2');
        } else if (/\/ms\//.test(trueUrl)) {
            /* pkavi.com /ms/ 格式: 替换最后一段(分页号) */
            trueUrl = trueUrl.replace(/(-)([^-]*)\.html$/, '-' + page + '.html');
        } else if (/year\/(\d+)\.html/.test(trueUrl)) {
            trueUrl = trueUrl.replace(/year\/(\d+)\.html/, 'page/' + page + '/year/$1.html');
        } else if (/year\/(\d+)\//.test(trueUrl)) {
            trueUrl = trueUrl.replace(/year\/(\d+)\//, 'page/' + page + '/year/$1/');
        } else {
            trueUrl = trueUrl.replace(/\.html$/, '/page/' + page + '.html');
        }
    }
    return trueUrl;
}

/* ----------------------------------------------------------------
 * renderScrollBoxFilter(d, catHtml) — 通用scroll-box格式筛选栏
 * ----------------------------------------------------------------
 * 适用于使用 .scroll-box 格式的网站
 * 渲染折叠/展开按钮 + 各筛选维度的选项
 * ============================================================= */
function renderScrollBoxFilter(d, catHtml) {
    var cateColor = getRangeColors();
    var categories = [];
    try {
        categories = pdfa(catHtml, 'body&&.scroll-box');
    } catch (e) {
        categories = [];
    }
    if (!categories.length) return;

    var initCate = [];
    for (var ci = 0; ci < 20; ci++) initCate.push('0');
    var cateTemp = JSON.parse(getMyVar('t', JSON.stringify(initCate)));
    var fold = getMyVar('fold', '0');

    /* 🔒/🔓 展开/折叠按钮 */
    d.push({
        title: fold === '1'
            ? '\u2018\u2018\u2019\u2019<b><span style="color: #FF0000">\uD83D\uDD13</span></b>'
            : '\u2018\u2018\u2019\u2019<b><span style="color: #1aad19">\uD83D\uDD12</span></b>',
        url: $().lazyRule(function (fold) {
            putMyVar('fold', fold === '1' ? '0' : '1');
            refreshPage(false);
            return 'hiker://empty';
        }, fold),
        col_type: 'scroll_button'
    });

    /* 遍历每个 scroll-box 分组 */
    for (var index = 0; index < categories.length; index++) {
        var subCats = pdfa(categories[index], 'body&&a');
        /* 第1组始终显示，其他组展开后才显示 */
        if (index === 0 || fold === '1') {
            for (var key = 0; key < subCats.length; key++) {
                var catTitle = pdfh(subCats[key], 'a&&Text');
                var catLink = _full(pdfh(subCats[key], 'a&&href'));
                if (!catTitle || !catLink) continue;

                var isActive = key.toString() === cateTemp[index];
                d.push({
                    title: isActive
                        ? '\u2018\u2018\u2019\u2019<b><span style="color: ' + cateColor + '">' + catTitle + '</span></b>'
                        : catTitle,
                    url: $(catLink + '#noLoading#').lazyRule(function (params) {
                        if (params.index === 0) {
                            var newCate = [];
                            params.cate_temp.forEach(function (cate, idx) {
                                newCate.push(idx === 0 ? params.key.toString() : '0');
                            });
                            putMyVar('t', JSON.stringify(newCate));
                        } else {
                            params.cate_temp[params.index] = params.key.toString();
                            putMyVar('t', JSON.stringify(params.cate_temp));
                        }
                        putMyVar('url', input.split('#')[0]);
                        refreshPage(true);
                        return 'hiker://empty';
                    }, { cate_temp: cateTemp, index: index, key: key }),
                    col_type: 'scroll_button'
                });
            }
            d.push({ col_type: 'blank_block' });
        }
    }
}


/* ================================================================
 * ================================================================
 * [按钮] pkavi.com专用：折叠筛选栏
 * ================================================================
 * ================================================================
 * 调用方式：renderSiteFilter(d, catHtml);
 *
 * 从分类页HTML解析 .list-box dl 格式的筛选栏
 * 调用 SITE.parseFilterOptions() 提取筛选维度
 *
 * 渲染内容：
 *   [展开/收起] [类型标题] [全部] [剧情] [喜剧] ...
 *               [地区标题] [全部] [中国] [日本] ...
 *
 * 折叠时只显示第1个维度，展开后显示全部
 * 点击选项时更新 url 变量 → 刷新页面加载新数据
 * ================================================================ */

function renderSiteFilter(d, catHtml) {
    var dims = [];
    try {
        dims = SITE.parseFilterOptions(catHtml);
    } catch (e) {
        dims = [];
    }
    if (!dims || !dims.length) return;

    var cateColor = getRangeColors();
    var fold = getMyVar('fold', '1');
    /* 展开/收起按钮（多于1个维度才显示） */
    if (dims.length > 1) {
        d.push({
            title: fold === '1'
                ? '\u2018\u2018\u2019\u2019<b><span style="color: #FF0000">收起</span></b>'
                : '\u2018\u2018\u2019\u2019<b><span style="color: #1aad19">展开</span></b>',
            url: $().lazyRule(function (fold) {
                putMyVar('fold', fold === '1' ? '0' : '1');
                refreshPage(false);
                return 'hiker://empty';
            }, fold),
            col_type: 'scroll_button'
        });
    }

    /* 遍历每个筛选维度 */
    for (var di = 0; di < dims.length; di++) {
        var dim = dims[di];
        /* 折叠时只显示第1个维度 */
        if (di > 0 && fold !== '1') break;

        /* 维度标题（如"类型""地区"） */
        d.push({
            title: '\u2018\u2018\u2019\u2019<b><font color="' + cateColor + '">' + dim.title + '</font></b>',
            url: 'hiker://empty',
            col_type: 'scroll_button'
        });

        /* 选项按钮 */
        for (var oi = 0; oi < dim.options.length; oi++) {
            var opt = dim.options[oi];
            d.push({
                title: opt.on
                    ? '\u2018\u2018\u2019\u2019<b><font color="#FF5D50">' + opt.t + '</font></b>'
                    : opt.t,
                url: $(_full(opt.s) + '#noLoading#').lazyRule(function () {
                    putMyVar('url', input.split('#')[0]);
                    refreshPage(true);
                    return 'hiker://empty';
                }),
                col_type: 'scroll_button',
                extra: { backgroundColor: opt.on ? '#20FA7298' : '' }
            });
        }
        d.push({ col_type: 'blank_block' });
    }
}


/* ================================================================
 * ================================================================
 * [首页] 经典风格 · 首页函数
 * ================================================================
 * ================================================================
 * 调用方式：home_classic(d, page);
 *
 * 两种模式：
 *   1. 首页模式（_cls 为空）：
 *      轮播图 → 搜索框 → 分类按钮 → 分板块展示视频
 *
 *   2. 分类模式（_cls 有值）：
 *      分类按钮(带高亮) → 折叠筛选栏 → 视频列表
 *
 * _cls 变量说明：
 *   空 → 首页模式
 *   '1' → 电影分类
 *   '2' → 剧集分类
 *   '30' → 短剧分类
 *
 * 第1页加载筛选栏，后续页只加载视频列表
 * ================================================================ */

function home_classic(d, page) {
    var cls = getMyVar(SITE.prefix + '_cls', '');

    /* ---------- 首页模式 ---------- */
    if (!cls) {
        if (page > 1) { setResult(d.concat([])); return; }

        /* [禁改] 禁止删除：数据级缓存 — 首页板块数据缓存 2 小时
         * 两种风格共用同一个缓存 key，切换风格不需要重新请求 */
        var homeUrl = SITE.host + '/';
        var cachedSections = cacheGet('home', homeUrl);
        var allSections;
        if (cachedSections && cachedSections.length > 0) {
            /* 命中缓存 → 直接用缓存数据，不再请求+解析 */
            allSections = cachedSections;
        } else {
            /* 未命中缓存 → 请求 + 解析 → 写入缓存 */
            var html = _fetch(homeUrl);
            if (!html) { setResult(d); return; }
            allSections = parseSections(html);
            if (allSections.length > 0) {
                cacheSet('home', homeUrl, allSections, 2 * 60 * 60 * 1000);
            }
        }
        if (!allSections.length) { setResult(d); return; }

        var maxSec = SITE.maxSections || 5;
        if (allSections.length > maxSec) allSections = allSections.slice(0, maxSec);

        /* 轮播图（无开关，自动轮播） */
        var banIdx = SITE.bannerSection || 0;
        if (allSections.length > banIdx && allSections[banIdx].items.length > 0) {
            var lunData = buildBannerData(allSections[banIdx].items);
            banner(MY_RULE.title, true, d, lunData, {
                time: 3000,
                col_type: 'pic_1_card',
                desc: '0'
            });
            d.push({ col_type: 'line_blank' });
        }

        /* 搜索框 */
        renderSearchBox(d);

        /* 分类导航按钮 */
        renderCatButtons(d, SITE.cats);

        /* 分板块展示视频 */
        for (var si = 0; si < allSections.length; si++) {
            var sec = allSections[si];
            var icon = (SITE.secIcons && SITE.secIcons[sec.title]) || '';
            var catId = (SITE.secClsMap && SITE.secClsMap[sec.title]) || '';
            renderSectionTitle(d, sec.title, icon, catId);
            var maxItems = si === 0 ? 6 : 9;
            var colType = si === 0 ? 'movie_2' : 'movie_3';
            renderSectionItems(d, sec.items, maxItems, colType);
        }

        setResult(d);
        return;
    }

    /* ---------- 分类模式（折叠筛选栏） ---------- */

    /* onClose 清理筛选变量 */
    addCloseListener(_filterKey());
    addListener('onClose', $.toString(function () {
        clearMyVar('url');
        clearMyVar('t');
        clearMyVar('fold');
    }));

    /* 第1页：大分类按钮在顶部（带高亮选中状态） */
    if (page === 1) {
        renderCatButtonsActive(d, SITE.cats, cls);
    }

    /* 计算要请求的URL（含分页 + 筛选条件） */
    var defaultCatUrl = SITE.buildCatUrl(cls, null, 1);
    var trueUrl = computeFilterUrl(defaultCatUrl, page);

    /* [禁改] 禁止删除：数据级缓存 — 分类列表缓存 1 小时 */
    var catCacheKey = trueUrl + '_p' + page;
    var cachedCat = cacheGet('cat', catCacheKey);
    if (cachedCat) {
        /* 命中缓存 → 直接用缓存数据 */
        if (page === 1 && cachedCat.html) renderSiteFilter(d, cachedCat.html);
        for (var ci = 0; ci < cachedCat.items.length; ci++) d.push(cachedCat.items[ci]);
        setResult(d);
        return;
    }

    var html = _fetch(trueUrl);

    /* 验证码检测 */
    if (!html || isCaptcha(html)) {
        renderEmpty(d, '分类页无法访问（可能有验证码防护）\n建议通过首页各板块浏览');
        d.push({
            title: '← 返回首页',
            url: $('#noLoading#').lazyRule(function (key) {
                putMyVar(key, '');
                refreshPage(true);
                return 'hiker://empty';
            }, SITE.prefix + '_cls'),
            col_type: 'button_1'
        });
        setResult(d);
        return;
    }

    /* 筛选栏在大分类按钮下方（折叠模式） */
    if (page === 1) {
        renderSiteFilter(d, html);
    }

    /* 视频列表 */
    var items = parseList(html);

    /* [禁改] 禁止删除：写入缓存（1小时过期） */
    if (items.length > 0) {
        cacheSet('cat', catCacheKey, { items: items, html: page === 1 ? html : '' }, 60 * 60 * 1000);
    }

    if (!items.length) {
        if (page === 1) renderEmpty(d, '暂无数据');
        setResult(page === 1 ? d : []);
        return;
    }

    for (var i = 0; i < items.length; i++) d.push(items[i]);
    setResult(d);
}


