        if (!allSections.length) { setResult(d); return; }

        var maxSec = SITE.maxSections || 5;
        if (allSections.length > maxSec) allSections = allSections.slice(0, maxSec);

        /* 轮播图（无开关） */
        var banIdx = SITE.bannerSection || 0;
        if (allSections.length > banIdx && allSections[banIdx].items.length > 0) {
            var lunData = buildBannerData(allSections[banIdx].items);
            banner(MY_RULE.title, true, d, lunData, {
                time: 3000,
                col_type: 'pic_1_card',
                desc: '0'
            });
