                    col_type: 'avatar'
                });
            }
            renderSectionItems(d, sec.items, 8, 'movie_2');
        }

        setResult(d);
        return;
    }

    /* ---------- 分类模式（和经典风格共用 _cls + url + t + fold） ---------- */
    addCloseListener(_filterKey());

    addListener('onClose', $.toString(function () {
        clearMyVar('url');
        clearMyVar('t');
        clearMyVar('fold');
    }));

    /* 第1页：大分类按钮在顶部（带高亮选中状态，和经典风格一致） */
    if (page === 1) {
        renderCatButtonsActive(d, SITE.cats, cls);
    }

    /* 计算要请求的URL（含分页 + 筛选条件） */
    var defaultCatUrl = SITE.buildCatUrl(cls, null, 1);
    var trueUrl = computeFilterUrl(defaultCatUrl, page);

    /* [禁改] 禁止删除：数据级缓存 — 分类列表缓存 1 小时 */
    var catCacheKey = trueUrl + '_p' + page;
    var cachedCat = cacheGet('cat', catCacheKey);
    if (cachedCat) {
        if (page === 1 && cachedCat.html) renderSiteFilter(d, cachedCat.html);
        for (var ci = 0; ci < cachedCat.items.length; ci++) d.push(cachedCat.items[ci]);
        setResult(d);
        return;
    }

    var catHtml = _fetch(trueUrl);
    if (!catHtml) { setResult(d); return; }

    /* 折叠分类导航（共用函数） */
    if (page === 1) {
        renderSiteFilter(d, catHtml);
    }

    /* 视频列表（共用 parseList） */
    var items = parseList(catHtml);

    /* [禁改] 禁止删除：写入缓存（1小时过期） */
    if (items.length > 0) {
        cacheSet('cat', catCacheKey, { items: items, html: page === 1 ? catHtml : '' }, 60 * 60 * 1000);
