/* ----------------------------------------------------------------
 * buildBannerData(items) — 从视频列表构造轮播数据
 * ----------------------------------------------------------------
 * 取前4个视频作为轮播图数据
 * 去掉 pic_url 中的 @Referer 后缀（轮播图不需要防盗链处理）
 *
 * 返回格式：[{ title, img, desc, url, extra }, ...]
 * ============================================================= */
function buildBannerData(items) {
    if (!items || !items.length) return [];
    var lun = [];
    for (var i = 0; i < items.length && i < 4; i++) {
        var it = items[i];
        var pureImg = (it.pic_url || '').replace(/@Referer=.*$/, '');
        /* url 用 lazyRule 包裹，确保点击后在规则内导航到详情页
         * 而不是直接打开原网站 */
        var detailUrl = it.url || 'hiker://empty';
        lun.push({
            title: it.title || '',
            img: pureImg,
            desc: it.desc || '',
            url: $().lazyRule(function (u) { return u; }, detailUrl),
            extra: { img: pureImg }
        });
    }
    return lun;
}

/* ----------------------------------------------------------------
 * renderEmpty(d, msg) — 空数据提示
 * ----------------------------------------------------------------
 * 在页面中间显示一条提示文字（如"暂无数据"）
 * ============================================================= */
function renderEmpty(d, msg) {
    d.push({
        title: msg || '暂无数据',
        url: 'javascript:;',
        col_type: 'title'
    });
}

/* ----------------------------------------------------------------
 * addCloseListener(clearKey) — 关闭页面时清理变量
 * ----------------------------------------------------------------
 * 注册 onClose 监听器，用户离开页面时自动清除指定变量
 * 防止变量残留影响下次访问
 *
 * 调用方式：addCloseListener(_filterKey());
 * ============================================================= */
function addCloseListener(clearKey) {
    addListener("onClose", $.toString(function (k) {
        clearVar(k);
    }, clearKey));
}


