     *   }
     * ======================================================== */
    buildCatUrl: function (cls, filter, page) {
        /* 海阔源（www.hqvod.com）分类页：/show/{cls}----------.html
         * MacCMS 12 段 URL：段0=cls 段1=地区 段2=排序 段3=类型 段4=语言 段5-7=空 段8=分页 段9-10=空 段11=年份
         * 实测：第1页 /show/1----------.html
         *       类型=喜剧 /show/1---喜剧--------.html
         *       地区=大陆+类型=喜剧 /show/1-大陆--喜剧--------.html
         *       年份=2026 /show/1---喜剧--------2026.html
         *       第2页 /show/1---喜剧-----2---.html（页码固定在第9段） */
        var segs = ['', '', '', '', '', '', '', '', '', '', '', ''];
