            if (filter.class) segs[3]  = _encSeg(filter.class);
            if (filter.lang)  segs[4]  = _encSeg(filter.lang);
            if (filter.year)  segs[11] = filter.year;
        }
        if (page > 1) segs[8] = String(page);
        return this.host + '/show/' + segs.join('-') + '.html';
