     *   }
     * ======================================================== */
    parseFilterOptions: function (html, cls) {
        /* 海阔源筛选栏结构：
         *   <div class="box-width wow fadeInUp ec-casc-list">
         *     <div class="nav-swiper rel"><div class="filter-text bj cor5"><span>类型</span></div>
         *       <ul class="swiper-wrapper"><li class="swiper-slide nav-dt"><a href="/show/1----------.html">全部</a></li>...
         *     *   当前选中项的 li 带 nav-dt；排序维度在 <div class="site-tabs"> 里（按最新/按最热/按评分）
         *   全部项的 href 是 javascript:void(0)，用 /show/{cls}----------.html 兜底（与站点自身的「全部」一致） */
        var dims = [];
        var baseSegs = [String(cls), '', '', '', '', '', '', '', '', '', '', ''];
        var base = '/show/' + baseSegs.join('-') + '.html';

        /* ---- 排序维度（站点自身是一组真实 URL，直接取用） ---- */
        var sortLinks = pdfa(html, 'div.ec-casc-list&&div.site-tabs&&a');
        if (sortLinks && sortLinks.length) {
            var sortOpts = [];
            for (var si = 0; si < sortLinks.length; si++) {
                var sT = (pdfh(sortLinks[si], 'a&&Text') || '').replace(/\s+/g, ' ').trim();
                var sH = pdfh(sortLinks[si], 'a&&href') || '';
                if (!sT || !sH || sH.indexOf('javascript') === 0) continue;
                sortOpts.push({
                    t: sT,
                    s: sH,
                    on: /active/.test(pdfh(sortLinks[si], 'a&&class') || '')
                });
            }
            if (sortOpts.length) dims.push({ title: '排序', options: sortOpts });
        }

        /* ---- 类型 / 地区 / 年份 / 语言 ---- */
        var groups = pdfa(html, 'div.ec-casc-list&&div.nav-swiper');
        for (var gi = 0; gi < groups.length; gi++) {
            var title = (pdfh(groups[gi], 'div.filter-text&&Text') || '').replace(/\s+/g, ' ').trim();
