/* ================================================================
 * buildPlayUrl(playUrl) - 选集URL -> 惰性求值播放规则
 * ----------------------------------------------------------------
 * [禁改] 禁止修改：函数名 buildPlayUrl、参数 (playUrl)
 * [禁改] 禁止修改：$().lazyRule() 惰性求值结构
 * [可改] 可以修改：正则表达式、Referer 地址
 *
 * 参数：playUrl - 选集页面URL（如 '/py/123-0-1.html'）
 * 返回：惰性规则字符串（点击时才解析真实播放地址）
 *
 * 工作流程：
 *   1. 把相对URL转成完整URL（_full）
 *   2. 返回 $().lazyRule() 惰性规则
 *   3. 用户点击选集时，惰性规则执行：
 *      a. 先检查缓存（storage0）-> 有缓存直接返回
 *      b. 缓存未命中 -> 请求播放页HTML
 *      c. 用正则提取 player_aaaa JSON
 *      d. JSON解析成功 -> 取 data.url
 *      e. JSON解析失败 -> 用正则直接提取 "url":"xxx" 字段
 *      f. 都失败 -> 搜索 m3u8 链接作为备用
 *      g. 写入缓存（12小时过期）
 *   4. 返回真实播放地址 + '#.m3u8' 后缀
 *
 * 正则说明：
 *   /player_aaaa\s*=\s*(\{[\s\S]*?\})\s*;?\s*<\/script/
 *   关键点：用 [\s\S]*? 匹配到 </script 结束
 *     避免嵌套JSON被截断（之前用 .*? 会停在第一个 }）
 *
 * 备用提取：
 *   /"url"\s*:\s*"([^"]+)"/  - 直接从JSON字符串提取url字段
 *   搜索m3u8链接 - 作为最后兜底
 * ================================================================ */
function buildPlayUrl(playUrl) {
    /* playUrl 格式: /py/{id}-{line}-{ep}.html -> 先转成完整URL */
    var url = _full(playUrl);

    /* !! 换站必改：缓存 key 前缀
     * lazyRule 的回调会被序列化到独立作用域执行，那里读不到外层的 _cfg，
     * 所以 prefix 必须在【外层】取好，再作为参数传进去。
     * 禁止在回调里直接写 '_cfg.prefix' —— 会报 _cfg is not defined。 */
    var vp = _cfg.prefix;

    /* 返回惰性规则，点击选集时才发起请求提取 m3u8 */
    return $().lazyRule(function (playUrl, vp, hkHost) {
        try {
            /* ---- 1. 先检查缓存 ----
             * 同一集第二次点击直接从缓存返回，不再请求
             * 用 try/catch 包起来，防止 storage0 不可用时报错 */
            try {
                var ck = vp + '_play_' + playUrl.replace(/[^a-zA-Z0-9]/g, '').substring(0, 60);
                var cached = storage0.getItem(ck);
                if (cached) {
                    var obj = JSON.parse(cached);
                    var now = new Date().getTime();
                    if (obj.expire > 0 && now - obj.time > obj.expire) {
                        storage0.removeItem(ck);
                    } else {
                        return obj.data + '#.m3u8';
                    }
                }
            } catch (ec) {}

            /* ---- 2. 请求播放页HTML ----
             * [可改] 可以修改：请求地址
             * 注意：lazyRule 里的 fetch 用 URL 直接请求，
             *       用 #autoCache# 走海阔自带缓存
             * !! 必须带 Referer：多数站点的 m3u8 CDN 有防盗链，
             *    不带 Referer 会返回 403 或空串。
             *    Referer 由外层把 _cfg.host 传进来（回调里读不到 _cfg）。 */
            var html = fetch(playUrl + '#autoCache#', {
                headers: { 'Referer': hkHost + '/', 'User-Agent': 'Mozilla/5.0 (Linux; Android 12) AppleWebKit/537.36' }
            });
            if (!html) return '';
            /* 分诊：拿到空页或挑战页时给出提示，否则真机上只会看到"链接为空" */
            /* 分诊：拿到空页或挑战页时给出提示，否则真机上只会看到"链接为空"
             * 高清点播实测：/bofang/ 页面对脚本请求返回 403 + JS 自刷循环页（132B），
             * 无法解析出 m3u8 → 按 SKILL §7.3 降级：返回 sniff 地址，让播放器嗅探（成功率低） */
            var isChallenge = /window\.location\.href/.test(html) && html.length < 400;
            if (isChallenge) {
                return playUrl + '#.m3u8';
            }
            if (!/player_data|player_aaaa|vod_data|\.m3u8/.test(html)) {
                try { toast('[hq] 播放页无播放数据，可能是 CF 挑战页，长度=' + html.length); } catch (et) {}
            }

            var playLink = '';

            /* ---- 内联 base64 解码器（不能依赖 atob） ----
             * 【踩坑记录】海阔运行环境不提供 atob/btoa，
             * hiker_lib.js 里也没有 base64 工具函数。
             * 原写法直接用 atob() 会抛 ReferenceError，
             * 被外层 try/catch 吞掉 -> 整个回调静默返回空串，
             * 现象就是「点播放提示链接为空」。
             * lazyRule 回调是独立作用域，所以解码器必须内联写在这里。 */
            function _b64dec(str) {
                try {
                    if (!str) return '';
                    var s = String(str).replace(/[\r\n\s]/g, '');
                    /* 兼容 URL-safe base64 */
                    s = s.replace(/-/g, '+').replace(/_/g, '/');
                    var CHARS = 'ABCDEFGHIJKLMNOPQRSTUVWXYZabcdefghijklmnopqrstuvwxyz0123456789+/';
                    var out = '', i = 0, buf = 0, bits = 0;
                    while (i < s.length) {
                        var c = s.charAt(i++);
                        if (c === '=') break;
                        var v = CHARS.indexOf(c);
                        if (v < 0) continue;
                        buf = (buf << 6) | v;
                        bits += 6;
                        if (bits >= 8) {
                            bits -= 8;
                            out += String.fromCharCode((buf >> bits) & 0xFF);
                        }
                    }
                    return out;
                } catch (e) { return ''; }
            }

            /* ---- 3. 方法1：提取 player_aaaa（星廷影院 · 标准 MacCMS） ----
     * [可改] 星廷影院播放页结构：
     *   var player_aaaa={"flag":"play","encrypt":0,"url":"https://v.fengbao14.com/.../index.m3u8","from":"bfzym3u8",...}
     * !! encrypt:0，url 字段就是明文完整 m3u8，直接取即可，无需二次解码。
     * !! 若 JSON.parse 失败，用正则直接提 "url":"..." 字段并还原 \u002f / \/ 转义。 */
            var match = html.match(/player_aaaa\s*=\s*(\{[\s\S]*?\})\s*;?\s*<\/script/);
            if (match) {
                try {
                    var data = JSON.parse(match[1]);
                    if (data && data.url) playLink = data.url;
                } catch (e1) {
                    var urlMatch = match[1].match(/"url"\s*:\s*"([^"]+)"/);
                    if (urlMatch) {
                        playLink = urlMatch[1].replace(/\\u002f/g, '/').replace(/\\\//g, '/');
                    }
                }
            }

            /* 兼容标准 MacCMS：player_aaaa */
            if (!playLink) {
                var matchA = html.match(/player_aaaa\s*=\s*(\{[\s\S]*?\})\s*;?\s*<\/script/);
                if (matchA) {
                    try {
                        var dataA = JSON.parse(matchA[1]);
                        playLink = dataA.url || '';
                    } catch (e1a) {
                        var urlMatchA = matchA[1].match(/"url"\s*:\s*"([^"]+)"/);
                        if (urlMatchA) {
                            playLink = urlMatchA[1].replace(/\\u002f/g, '/').replace(/\\\//g, '/');
                        }
                    }
                }
            }

            /* ---- 4. 方法2：搜索 vod_data 里的 url ----
             * 有些站播放数据在 vod_data 变量里 */
            if (!playLink) {
                var vodMatch = html.match(/vod_data\s*=\s*(\{[\s\S]*?\})\s*;?\s*<\/script/);
                if (vodMatch) {
                    try {
                        var vodData = JSON.parse(vodMatch[1]);
                        playLink = vodData.url || vodData.play_url || '';
                    } catch (e2) {
                        var urlMatch2 = vodMatch[1].match(/"url"\s*:\s*"([^"]+)"/);
                        if (urlMatch2) {
                            playLink = urlMatch2[1].replace(/\\u002f/g, '/').replace(/\\\//g, '/');
                        }
                    }
                }
            }

            /* ---- 5. 方法3：直接搜索 m3u8 链接 ----
             * [可改] 可以修改：m3u8 搜索正则
             * 作为最后兜底，直接从HTML里找m3u8链接 */
            if (!playLink) {
                var m3u8Match = html.match(/https?:\/\/[^\s"'<>]+\.m3u8[^\s"'<>]*/);
                if (m3u8Match) {
                    playLink = m3u8Match[0];
                }
            }

            /* ---- 6. 方法4：搜索 mp4 链接 ----
             * 有些站是mp4直链 */
            if (!playLink) {
                var mp4Match = html.match(/https?:\/\/[^\s"'<>]+\.mp4[^\s"'<>]*/);
                if (mp4Match) {
                    playLink = mp4Match[0];
                }
            }

            /* ---- 7. 校验：播放地址必须是 http(s) 明文直链 ----
             * 海阔源实测：/bofang/ 页的 player_aaaa.url 是站点加密 token
             * （形如 1mIKmHHA... 的 base64url 串，不是 http 链接），
             * 真实 m3u8 要由第三方解析站二次请求取出，海阔脚本无法还原。
             * 按 SKILL §7.3 降级为嗅探地址（成功率低，需在交付说明标注）。 */
            if (playLink && !/^https?:\/\//i.test(playLink)) {
                try { toast('[hq] 播放页返回加密 token，无法直链，改用嗅探'); } catch (et3) {}
                playLink = '';
            }

            /* ---- 7. 写入缓存并返回 ---- */
            if (playLink) {
                /* 写入缓存（12小时过期）
                 * 用 try/catch 包起来，防止 storage0 不可用时报错 */
                try {
                    var cacheKey = vp + '_play_' + playUrl.replace(/[^a-zA-Z0-9]/g, '').substring(0, 60);
                    storage0.setItem(cacheKey, JSON.stringify({
                        data: playLink,
                        time: new Date().getTime(),
                        expire: 12 * 60 * 60 * 1000
                    }));
                } catch (es) {}
                return playLink + '#.m3u8';
            }
        } catch (e) {}
        try { toast('[hq] 播放解析失败（页面无 player_aaaa/url/m3u8 匹配），改用嗅探'); } catch (et2) {}
        /* SKILL §7.3：播放地址拿不到 → 返回播放页地址让播放器嗅探 */
        return playUrl + '#.m3u8';
    }, url, vp, _cfg.host);
}


