/* ================================================================
 * ================================================================
 * [搜索] 搜索函数（两种风格共用）
 * ================================================================
 * ================================================================
 * 海阔调用 search() 时执行
 * 两种风格共用同一个搜索函数，解析逻辑完全一致
 *
 * 流程：
 *   1. 从 MY_KEYWORD 获取搜索关键词
 *   2. 用 SITE.getSearchUrl() 构建搜索URL
 *   3. 请求搜索页HTML
 *   4. 用 parseList() 解析视频卡片
 *   5. 输出结果
 *
 * 海阔内置变量：
 *   MY_KEYWORD — 用户输入的搜索关键词
 * ================================================================ */

function search() {
    /* ============================================================
     * 【严格照参考 cibn search()】多路取词 + 流式渲染
     *
     * 取词顺序：
     *   1) MY_PAGE > 1 → getMyVar(prefix + '_kw', '')   ← 翻页场景
     *   2) KEY（海阔搜索页传参）
     *   3) MY_URL 里的 kw= 参数
     *   4) MY_KW（海阔内置变量）
     *   5) 空 → 显示搜索框 + 提示文案
     *
     * page = 1 时：putMyVar(prefix + '_kw', kw) 存词
     * 渲染：setResult 先推骨架，再 addItemAfter 流式追加结果
     * ============================================================ */
    var pk = SITE.prefix;
    var d = [];
    var kw = '';
    var page = 1;
    try { page = parseInt(MY_PAGE, 10) || 1; } catch (e) { page = 1; }

    /* 取词（对齐独播库正常规则）：海阔原生搜索页调 search() 注入的词是 MY_KEYWORD（带下划线）。
     * 早期误写成不带下划线的取词变量（海阔实际不注入那个）→ kw 恒空 → 卡在"请输入搜索关键词"。
     * 顺序：翻页缓存 → MY_KEYWORD（本规则搜索页词，最高优先）→ 其他兜底路。 */
    if (page > 1) kw = getMyVar(pk + '_kw', '');
    if (!kw) { try { if (typeof MY_KEYWORD !== 'undefined' && MY_KEYWORD) kw = String(MY_KEYWORD); } catch (e) {} }
    if (!kw) { try { if (typeof KEY !== 'undefined' && KEY) kw = String(KEY); } catch (e) {} }
    if (!kw) {
        try {
            var mm = String(MY_URL || '').match(/[?&]kw=([^&#]+)/);
            if (mm) { try { kw = decodeURIComponent(mm[1]); } catch (e) { kw = mm[1]; } }
        } catch (e) {}
    }
    if (!kw) { try { if (typeof MY_KW !== 'undefined' && MY_KW) kw = String(MY_KW); } catch (e) {} }
    kw = String(kw || '').replace(/^\s+|\s+$/g, '');

    if (!kw) {
        renderSearchBox(d);
        d.push({ title: '请输入搜索关键词', desc: '如：斗罗大陆 / 庆余年', col_type: 'text_1', extra: { lineVisible: false } });
        setResult(d);
        return;
    }

    if (page === 1) putMyVar(pk + '_kw', kw);
    try { setPageTitle('搜索：' + kw); } catch (e) {}

    var items = find(kw, page) || [];
    for (var i = 0; i < items.length; i++) d.push(items[i]);
    if (!items.length && page === 1) {
        d.push({ title: '没有找到相关影片', desc: '换个关键词试试', col_type: 'text_center_1', extra: { lineVisible: false } });
    }
    setResult(d);
}


/* ================================================================
 * find(kw, page) — 聚合搜索标准方法
 * ----------------------------------------------------------------
 * 供海阔内置聚合链路 $.require("hiker://page/data").load()
 * 调用：load(page, ruleName)[0].find(keyword, page) → items[]
 *
 * 返回：items 数组（不 setResult、不渲染，纯数据）
 * 逻辑：抓取搜索页 → parseList → 返回
 * ================================================================ */

function find(kw, page) {
    var items = [];
    if (!kw) return items;
    page = parseInt(page, 10) || 1;
    try {
        var url = getSearchUrl(kw);
        if (page > 1) url += '&page=' + page;
        var html = _fetch(url);
        if (html && !isCaptcha(html)) {
            html = html.replace(/<ul class="[^"]*stui-vodlist__\w+ active[^"]*">[\s\S]*?<\/ul>/g, '');
            items = parseList(html) || [];
        }
    } catch (e) { items = []; }
    return items;
}


/* ================================================================
 * ================================================================
 * [详情] 主入口 · 详情页函数（两种风格共用）
 * ================================================================
 * ================================================================
 * 海阔调用 detail() 时执行
 * 两种风格共用同一个详情页函数，数据完全一致
 *
 * 海阔内置变量：
 *   MY_URL — 用户点击的视频详情页URL（可能带 #后缀）
 *
 * 详情页渲染流程：
 *   +------------------------------------------------+
 *   | 1. 请求详情页HTML                               |
 *   | 2. extractDetailInfo() → 标题/封面/简介/演员等 |
 *   | 3. 渲染顶部大图卡片（标题+封面+描述）            |
 *   | 4. setDesc() → 简介展开/收起                    |
 *   | 5. extractEpisodes() → 线路名+选集列表          |
 *   | 6. renderQuickSearch() → 4个快速搜索图标        |
 *   | 7. renderEpisodes() → 选集列表（线路+正倒序）   |
 *   | 8. extractPanResources() → 网盘/磁力资源         |
 *   | 9. renderPanResources() → 网盘资源渲染          |
 *   | 10. 底部免责声明                                |
 *   +------------------------------------------------+
 * ================================================================ */

function detail() {
    /* MY_URL 可能带 #immersiveTheme# 等后缀，去掉 */
    var fetchUrl = MY_URL.split('#')[0];
    var d = [];

    /* [禁改] 禁止删除：数据级缓存 — 详情页数据缓存 6 小时 */
    var cachedDetail = cacheGet('detail', fetchUrl);
    var info, epData, panData;

    if (cachedDetail) {
        /* 命中缓存 → 直接用缓存数据，不再请求+解析 */
        info = cachedDetail.info || {};
        epData = cachedDetail.epData || { lineNames: [], allLinesEp: [] };
        panData = cachedDetail.panData || { groupNames: [], allGroups: [] };
    } else {
        /* 未命中缓存 → 请求 + 解析 → 写入缓存 */
        var res = _fetch(fetchUrl);
        if (!res) { setResult(d); return; }
        info = extractDetailInfo(res) || {};
        epData = extractEpisodes(res) || { lineNames: [], allLinesEp: [] };
        panData = (typeof extractPanResources === 'function') ? extractPanResources(res) : { groupNames: [], allGroups: [] };
        cacheSet('detail', fetchUrl, { info: info, epData: epData, panData: panData }, 6 * 60 * 60 * 1000);
    }

    try {
        var tTitle = info.title || '-';
        var cover = info.pic || '';
        var intro = info.desc || '';

        /* ---- 组合描述文字 ---- */
        var chip = '';
        if (info.year) chip += info.year + ' ';
        if (info.area) chip += info.area + ' ';
        if (info.type) chip += info.type + ' ';
        var desc = chip.trim();
        if (info.actor) desc += '\n主演：' + info.actor;
        if (info.director) desc += '\n导演：' + info.director;
        if (info.rating) desc += '\n评分：' + info.rating;

        /* ---- 顶部大图卡片 ---- */
        d.push({
            title: tTitle,
            desc: desc,
            pic_url: cover ? cover + '@Referer=' + SITE.host + '/' : '',
            url: cover ? cover + '#.jpg#' : 'hiker://empty',
            col_type: 'movie_1_vertical_pic_blur',
            extra: { gradient: true }
        });

        /* ---- 简介展开/收起 ---- */
        setDesc(d, intro, 60);

        /* ---- 选集数据（已在缓存分支提取） ---- */
        var lineNames = epData.lineNames || [];
        var allLinesEp = epData.allLinesEp || [];

        /* ---- 4个快速搜索图标 + TVBOX推送 ---- */
        renderQuickSearch(d, {
            lists: allLinesEp,
            tabs: lineNames,
            tTitle: tTitle,
            cover: cover,
            intro: intro
        });

        /* ---- 选集列表（线路切换 + 正倒序 + 集数） ----
         * buildPlayUrl 是回调函数，点击每一集时才解析真实播放地址 */
        renderEpisodes(d, allLinesEp, lineNames, function (epItem) {
            return buildPlayUrl(epItem.url);
        });

        /* ---- 网盘/磁力资源（已在缓存分支提取） ---- */
        if (panData && panData.allGroups && panData.allGroups.length > 0) {
            renderPanResources(d, panData.groupNames, panData.allGroups);
        }

    } catch(e) {
        /* 解析出错时显示错误信息 */
        d.push({
            title: '解析出错：' + (e.message || e),
            col_type: 'text_center_1',
            extra: { lineVisible: false }
        });
    }

    /* ---- 底部免责声明 ---- */
    d.push({ col_type: 'blank_block' });
    d.push({ col_type: 'line_blank' });
    d.push({
        title: '\u2018\u2018\u2019\u2019<small><font color=#20b2aa>数据资源收集于网络，海阔不提供任何资源！</font></small>',
        desc: '\u2018\u2018\u2019\u2019<small><font color=#ff7f50>本规则仅限学习与交流，请导入后24小时内删除，请勿传播！</font></small>',
        url: 'hiker://empty',
        col_type: 'text_center_1',
        extra: { lineVisible: false }
    });

    setResult(d);
}


/* ================================================================
 * ===== 导出入口函数 =====
 * ----------------------------------------------------------------
 * 海阔通过 $.exports 获取 home / search / detail 三个入口函数
 * ================================================================ */
$.exports = { home: home, search: search, detail: detail, find: find };


